window.BANCO = {"generado":"2026-11-22","ejes":[{"id":"constitucional","nombre":"Constitución y organización del Estado","nucleo":"general","total":30},{"id":"funcion-publica","nombre":"Función pública, empleo y carrera","nucleo":"general","total":28},{"id":"administrativo","nombre":"Derecho administrativo y CPACA","nucleo":"general","total":28},{"id":"contratacion","nombre":"Contratación estatal","nucleo":"general","total":28},{"id":"transparencia","nombre":"Transparencia, información pública y ética","nucleo":"general","total":28},{"id":"pgn","nombre":"Estructura y funciones de la PGN","nucleo":"especifico","total":28},{"id":"disciplinario","nombre":"Derecho disciplinario sustancial","nucleo":"especifico","total":28},{"id":"proc-disciplinario","nombre":"Procedimiento disciplinario","nucleo":"especifico","total":28},{"id":"intervencion","nombre":"Intervención del Ministerio Público","nucleo":"especifico","total":0},{"id":"ddhh-preventiva","nombre":"Derechos humanos, acciones constitucionales y función preventiva","nucleo":"especifico","total":1},{"id":"competencias","nombre":"Competencias comportamentales","nucleo":"competencias","total":42}],"preguntas":[{"id":"real-0001","eje":"constitucional","nucleo":"general","origen":"real","fuente":"Guía PGN convocatoria 2006-2007, ejemplo 2 (Drive: base_Cartilla_Procuraduria.md). C.P. arts. 30 y 152; Ley 1095 de 2006","enunciado":"La acción de habeas corpus debe ser regulada por el Congreso de la República mediante una ley estatutaria, porque","opciones":{"A":"el habeas corpus está consagrado expresamente en el artículo 30 de la Constitución Política.","B":"es un trámite propio del proceso penal y ya fue expedido el Código de Procedimiento Penal.","C":"es un mecanismo de protección del derecho fundamental a la libertad personal.","D":"su resultado lesiona el derecho fundamental a la libertad personal."},"correcta":"C","explicacion":"El artículo 152 de la Constitución reserva a la ley estatutaria la regulación de los derechos fundamentales y de los procedimientos y recursos para su protección. El habeas corpus protege la libertad personal; por eso se reguló mediante ley estatutaria (Ley 1095 de 2006). Estar en el artículo 30 no basta por sí solo, no es un simple trámite del proceso penal y su resultado protege la libertad, no la lesiona.","dificultad":2},{"id":"real-0003","eje":"constitucional","nucleo":"general","origen":"real","tipo":"postulados","fuente":"Cartilla de pruebas escritas PGN 2015, Universidad de Antioquia, ejemplo de análisis de postulados (Drive: act_298581349-Cartilla-Procuraduria-concurso.md). Corte Constitucional, T-422 de 1992","enunciado":"TESIS: El concepto de proporcionalidad sirve como punto de apoyo a la ponderación entre principios constitucionales, cuando en la solución de un caso particular dos o más derechos entran en colisión.\n\nPOSTULADO I: La aplicación plena de uno de los derechos conduce a la reducción significativa del campo de aplicación del otro u otros.\nPOSTULADO II: El juez constitucional debe determinar si la reducción de un derecho o de otro se justifica a la luz de la importancia del derecho afectado para el ordenamiento jurídico.","opciones":{"A":"De la tesis se deducen los postulados I y II.","B":"De la tesis solo se deduce el postulado I.","C":"De la tesis solo se deduce el postulado II.","D":"Ninguno de los postulados se deduce de la tesis."},"correcta":"A","explicacion":"La ponderación existe porque la aplicación plena de un derecho reduce el campo del otro (postulado I), y corresponde al juez constitucional establecer hasta dónde esa reducción se justifica según la importancia del derecho afectado (postulado II). Ambos se deducen de la tesis.","dificultad":3},{"id":"real-0002","eje":"ddhh-preventiva","nucleo":"especifico","origen":"real","tipo":"multiple","fuente":"Cartilla de pruebas escritas PGN 2015, Universidad de Antioquia, ejemplo de selección múltiple con múltiple respuesta (Drive: act_298581349-Cartilla-Procuraduria-concurso.md). C.P. arts. 11, 13, 18 y 22","enunciado":"El Alcalde debe cumplir con la cláusula general de competencia que lo obliga a velar por el cumplimiento de los fines del Estado Social de Derecho y por los derechos humanos en su municipio. De acuerdo con lo anterior, un Alcalde fue requerido por el Procurador ya que incumplió con este mandato constitucional, poniendo en riesgo los derechos\n\n1. a la vida y a la libertad.\n2. al medio ambiente y a la seguridad.\n3. a la paz y a la libertad de conciencia.\n4. a la institucionalidad y a la integralidad personal.","opciones":{"A":"1 y 2 son correctas.","B":"2 y 3 son correctas.","C":"3 y 4 son correctas.","D":"1 y 3 son correctas."},"correcta":"D","explicacion":"Según la clave oficial, la vida (art. 11), la libertad (art. 28), la libertad de conciencia (art. 18) y la paz (art. 22) están consagradas en el capítulo 1 del título II de la Constitución, De los derechos fundamentales. Las demás combinaciones incluyen derechos colectivos o expresiones que no corresponden a derechos fundamentales.","dificultad":2},{"id":"adm-0001","eje":"administrativo","nucleo":"general","origen":"estilo","fuente":"Ley 1437 de 2011, art. 14 (sustituido por Ley 1755 de 2015)","enunciado":"Un ciudadano radica una petición de interés particular ante una gobernación, sin pedir documentos ni formular consulta. Salvo norma especial, la entidad debe resolverla dentro de los","opciones":{"A":"quince días siguientes a su recepción.","B":"diez días siguientes a su recepción.","C":"treinta días siguientes a su recepción.","D":"tres meses siguientes a su recepción."},"correcta":"A","explicacion":"El artículo 14 del CPACA, sustituido por la Ley 1755 de 2015, fija quince días como término general. Diez días aplican a peticiones de documentos e información y treinta días a consultas; los tres meses corresponden al silencio negativo (art. 83).","dificultad":1},{"id":"adm-0002","eje":"administrativo","nucleo":"general","origen":"estilo","fuente":"Ley 1437 de 2011, art. 14, num. 1 (sustituido por Ley 1755 de 2015)","enunciado":"Una persona pide copia de un contrato a una alcaldía y no recibe respuesta en diez días. La consecuencia legal es que","opciones":{"A":"se entiende negada y puede acudir a la jurisdicción.","B":"se entiende aceptada la solicitud y las copias deben entregarse dentro de los tres días siguientes.","C":"debe presentar una nueva petición.","D":"la entidad cuenta con diez días adicionales sin consecuencia alguna."},"correcta":"B","explicacion":"El numeral 1 del artículo 14 dispone que, si una petición de documentos no se responde en diez días, se entiende aceptada; la administración ya no puede negar la entrega y debe entregar las copias dentro de los tres días siguientes.","dificultad":2},{"id":"adm-0003","eje":"administrativo","nucleo":"general","origen":"estilo","fuente":"Ley 1437 de 2011, art. 14, parágrafo (sustituido por Ley 1755 de 2015)","enunciado":"Una entidad no puede resolver una consulta dentro del plazo legal por su complejidad. Debe","opciones":{"A":"responder cuando pueda, sin informar, pues las consultas no son vinculantes.","B":"remitirla a la Procuraduría para que la resuelva.","C":"archivar la consulta y pedir que se presente de nuevo.","D":"informarlo al interesado antes del vencimiento, explicar los motivos y señalar un plazo razonable que no exceda el doble del inicial."},"correcta":"D","explicacion":"El parágrafo del artículo 14 obliga a informar al interesado, antes del vencimiento, los motivos de la demora y el plazo razonable de respuesta, que no podrá exceder del doble del inicialmente previsto.","dificultad":2},{"id":"adm-0004","eje":"administrativo","nucleo":"general","origen":"estilo","fuente":"Ley 1437 de 2011, art. 83","enunciado":"Transcurridos tres meses desde la presentación de una petición sin que se notifique decisión, se entiende que la respuesta es","opciones":{"A":"inexistente, por lo que no hay recurso alguno.","B":"positiva en todos los casos.","C":"negativa, sin que la autoridad quede eximida de responsabilidad ni del deber de decidir.","D":"negativa, y la autoridad pierde competencia para decidir."},"correcta":"C","explicacion":"El artículo 83 establece el silencio administrativo negativo a los tres meses. Su ocurrencia no exime de responsabilidad a las autoridades ni del deber de decidir, salvo que el interesado haya interpuesto recursos o se haya notificado el auto admisorio de una demanda. El silencio positivo solo existe cuando la ley lo prevé (art. 84).","dificultad":1},{"id":"adm-0005","eje":"administrativo","nucleo":"general","origen":"estilo","fuente":"Ley 1437 de 2011, art. 86","enunciado":"Si transcurren dos meses desde la interposición de un recurso de reposición o apelación sin que se notifique decisión expresa, salvo lo dispuesto para el procedimiento sancionatorio","opciones":{"A":"se entiende que el recurso prosperó.","B":"el acto recurrido pierde ejecutoriedad.","C":"el recurso se entiende desistido.","D":"se entiende que la decisión es negativa."},"correcta":"D","explicacion":"El artículo 86 dispone que, salvo lo previsto en el artículo 52, transcurridos dos meses sin decisión expresa sobre los recursos se entiende que la decisión es negativa. En el sancionatorio, si no se deciden en un año, se entienden fallados a favor del recurrente.","dificultad":2},{"id":"adm-0006","eje":"administrativo","nucleo":"general","origen":"estilo","fuente":"Ley 1437 de 2011, art. 52","enunciado":"Una superintendencia sanciona a una empresa por un hecho ocurrido hace cuatro años y no existe ley especial sobre caducidad. La facultad sancionatoria","opciones":{"A":"está vigente, porque caduca a los cinco años.","B":"está vigente, porque el término se cuenta desde que la entidad conoció el hecho.","C":"caducó, porque caduca a los tres años de ocurrido el hecho, término en el cual el acto debe expedirse y notificarse.","D":"no caduca en materia administrativa."},"correcta":"C","explicacion":"El artículo 52 del CPACA dispone que, salvo leyes especiales, la facultad sancionatoria caduca a los tres años de ocurrido el hecho, término en el que el acto sancionatorio debe expedirse y notificarse. Los cinco años corresponden a la prescripción de la sanción ya impuesta.","dificultad":2},{"id":"adm-0007","eje":"administrativo","nucleo":"general","origen":"estilo","fuente":"Ley 1437 de 2011, art. 52","enunciado":"En un procedimiento administrativo sancionatorio, si los recursos contra el acto sancionatorio no se deciden dentro de un año desde su interposición","opciones":{"A":"el expediente pasa a la Procuraduría.","B":"se entienden fallados a favor del recurrente y la autoridad pierde competencia.","C":"opera el silencio negativo y queda en firme la sanción.","D":"la sanción se reduce a la mitad."},"correcta":"B","explicacion":"El artículo 52 ordena decidir los recursos, so pena de pérdida de competencia, en un año desde su interposición; de lo contrario se entienden fallados a favor del recurrente, sin perjuicio de la responsabilidad del funcionario.","dificultad":3},{"id":"adm-0008","eje":"administrativo","nucleo":"general","origen":"estilo","fuente":"Ley 1437 de 2011, art. 47","enunciado":"En el procedimiento administrativo sancionatorio general del CPACA, el investigado puede presentar descargos y solicitar pruebas dentro de los","opciones":{"A":"quince días siguientes a la notificación de la formulación de cargos.","B":"diez días siguientes a la apertura de la averiguación preliminar.","C":"cinco días siguientes a la formulación de cargos, en todos los casos.","D":"treinta días siguientes a la notificación del acto sancionatorio."},"correcta":"A","explicacion":"El artículo 47 otorga quince días desde la notificación del pliego de cargos para presentar descargos y solicitar o aportar pruebas. El término de cinco días aplica solo a los procedimientos sancionatorios fiscales (parágrafo 2).","dificultad":2},{"id":"adm-0009","eje":"administrativo","nucleo":"general","origen":"estilo","fuente":"Ley 1437 de 2011, art. 76","enunciado":"Un acto administrativo particular se notificó personalmente. Los recursos de reposición y apelación deben interponerse","opciones":{"A":"en cualquier tiempo mientras el acto no se ejecute.","B":"por escrito en la diligencia de notificación o dentro de los diez días siguientes.","C":"dentro del mes siguiente a la notificación.","D":"dentro de los cinco días siguientes a la ejecutoria."},"correcta":"B","explicacion":"El artículo 76 dispone que la reposición y la apelación se interponen por escrito en la diligencia de notificación personal o dentro de los diez días siguientes a ella o a la notificación por aviso. Solo contra los actos presuntos pueden interponerse en cualquier tiempo.","dificultad":1},{"id":"adm-0010","eje":"administrativo","nucleo":"general","origen":"estilo","fuente":"Ley 1437 de 2011, art. 76","enunciado":"Respecto de los recursos en la actuación administrativa, es obligatorio para acceder a la jurisdicción, cuando proceda,","opciones":{"A":"el recurso de apelación.","B":"la solicitud de revocatoria directa.","C":"el recurso de reposición.","D":"el recurso de queja."},"correcta":"A","explicacion":"El artículo 76 establece que la apelación, cuando proceda, es obligatoria para acceder a la jurisdicción, mientras que la reposición y la queja no son obligatorias. La revocatoria directa no es un recurso ni requisito de procedibilidad.","dificultad":2},{"id":"adm-0011","eje":"administrativo","nucleo":"general","origen":"estilo","fuente":"Ley 1437 de 2011, art. 75","enunciado":"Una persona interpone recurso de reposición contra un decreto municipal que regula los horarios de funcionamiento de los establecimientos de comercio. El recurso","opciones":{"A":"es procedente dentro de los diez días siguientes a la publicación.","B":"es procedente solo si lo interpone un comerciante afectado.","C":"es improcedente, porque no hay recursos contra los actos de carácter general.","D":"debe tramitarse como derecho de petición en interés general."},"correcta":"C","explicacion":"El artículo 75 dispone que no hay recurso contra los actos de carácter general, ni contra los de trámite, preparatorios o de ejecución, salvo norma expresa. El acto general puede demandarse en nulidad ante la jurisdicción.","dificultad":1},{"id":"adm-0012","eje":"administrativo","nucleo":"general","origen":"estilo","fuente":"Ley 1437 de 2011, art. 76","enunciado":"El funcionario que dictó una decisión se niega a recibir el recurso de reposición que presenta el interesado. El interesado puede","opciones":{"A":"presentarlo ante el juez administrativo.","B":"acudir directamente a la acción de cumplimiento.","C":"darlo por interpuesto sin necesidad de radicación.","D":"presentarlo ante el procurador regional o el personero municipal, para que ordenen recibirlo y tramitarlo."},"correcta":"D","explicacion":"El inciso segundo del artículo 76 prevé que, si el competente no quisiere recibir los recursos, podrán presentarse ante el procurador regional o el personero municipal para que ordene recibirlos, tramitarlos e imponga las sanciones del caso.","dificultad":2},{"id":"adm-0013","eje":"administrativo","nucleo":"general","origen":"estilo","fuente":"Ley 1437 de 2011, art. 87","enunciado":"Contra un acto administrativo procedían recursos, pero el interesado no los interpuso. El acto queda en firme","opciones":{"A":"desde el día de su expedición.","B":"desde el día siguiente al vencimiento del término para interponerlos.","C":"un mes después de la notificación.","D":"cuando la entidad lo ejecute materialmente."},"correcta":"B","explicacion":"El numeral 3 del artículo 87 dispone que los actos quedan en firme desde el día siguiente al vencimiento del término para interponer recursos, si no fueron interpuestos o se renunció expresamente a ellos.","dificultad":1},{"id":"adm-0014","eje":"administrativo","nucleo":"general","origen":"estilo","fuente":"Ley 1437 de 2011, art. 91","enunciado":"Una entidad expidió un acto de demolición que quedó en firme hace seis años, pero nunca hizo nada para ejecutarlo. Hoy pretende ejecutarlo. Según el CPACA","opciones":{"A":"el acto perdió ejecutoriedad, porque pasaron más de cinco años en firme sin actos de ejecución.","B":"necesita autorización del juez para ejecutarlo.","C":"puede ejecutarlo, porque los actos en firme son obligatorios indefinidamente.","D":"debe revocarlo y expedir uno nuevo con el mismo contenido."},"correcta":"A","explicacion":"El numeral 3 del artículo 91 establece que los actos pierden obligatoriedad cuando, al cabo de cinco años de estar en firme, la autoridad no ha realizado los actos que le corresponden para ejecutarlos.","dificultad":2},{"id":"adm-0015","eje":"administrativo","nucleo":"general","origen":"estilo","fuente":"Ley 1437 de 2011, art. 91","enunciado":"La ley que servía de fundamento a un acto administrativo fue declarada inexequible. El acto, que no ha sido anulado","opciones":{"A":"se convierte en acto de carácter general.","B":"debe ser ratificado por el superior jerárquico.","C":"pierde fuerza ejecutoria por desaparición de sus fundamentos de derecho.","D":"conserva plena obligatoriedad hasta que sea anulado."},"correcta":"C","explicacion":"El numeral 2 del artículo 91 dispone que el acto pierde obligatoriedad y no puede ejecutarse cuando desaparecen sus fundamentos de hecho o de derecho, como ocurre con la inexequibilidad de la ley en que se fundaba.","dificultad":2},{"id":"adm-0016","eje":"administrativo","nucleo":"general","origen":"estilo","fuente":"Ley 1437 de 2011, art. 93","enunciado":"Es causal de revocación directa de los actos administrativos","opciones":{"A":"que el acto tenga más de un año de expedido.","B":"que haya cambiado el titular de la entidad.","C":"que el interesado no haya interpuesto recursos.","D":"que con ellos se cause agravio injustificado a una persona."},"correcta":"D","explicacion":"El artículo 93 prevé tres causales de revocación: manifiesta oposición a la Constitución o a la ley, inconformidad con el interés público o social, y agravio injustificado a una persona. El cambio de titular o el paso del tiempo no son causales.","dificultad":1},{"id":"adm-0017","eje":"administrativo","nucleo":"general","origen":"estilo","fuente":"Ley 1437 de 2011, art. 97","enunciado":"Una entidad advierte que un acto particular que reconoció una pensión es contrario a la ley, pero el titular no consiente su revocación. Si no hubo medios ilegales o fraudulentos, la entidad debe","opciones":{"A":"revocarlo unilateralmente mediante resolución motivada.","B":"suspender el pago hasta que el titular consienta.","C":"solicitar a la Procuraduría que lo revoque.","D":"demandar el acto ante la Jurisdicción de lo Contencioso Administrativo."},"correcta":"D","explicacion":"El artículo 97 dispone que un acto que creó una situación particular no puede revocarse sin consentimiento previo, expreso y escrito del titular; si este lo niega y la autoridad considera el acto ilegal, debe demandarlo ante la jurisdicción.","dificultad":2},{"id":"adm-0018","eje":"administrativo","nucleo":"general","origen":"estilo","fuente":"Ley 1437 de 2011, art. 95","enunciado":"La revocación directa de un acto administrativo puede hacerse aun cuando se haya acudido a la jurisdicción, siempre que","opciones":{"A":"no se haya dictado sentencia de primera instancia.","B":"el juez lo autorice expresamente.","C":"no se haya notificado el auto admisorio de la demanda.","D":"el acto no haya sido ejecutado."},"correcta":"C","explicacion":"El artículo 95 permite la revocación directa aunque se haya acudido a la jurisdicción, siempre que no se haya notificado el auto admisorio de la demanda; la solicitud debe resolverse en dos meses.","dificultad":2},{"id":"adm-0019","eje":"administrativo","nucleo":"general","origen":"estilo","fuente":"Ley 1437 de 2011, arts. 68 y 69","enunciado":"Se envió citación para notificación personal a un interesado y este no compareció en cinco días. La entidad debe","opciones":{"A":"declarar desierta la actuación.","B":"notificar por aviso, remitiéndolo con copia íntegra del acto.","C":"notificar por edicto durante diez días.","D":"notificar por estado en la secretaría."},"correcta":"B","explicacion":"El artículo 69 dispone que si no puede hacerse la notificación personal al cabo de cinco días del envío de la citación, se hará por aviso, con copia íntegra del acto. El edicto no es la forma prevista en el CPACA para este evento.","dificultad":1},{"id":"adm-0020","eje":"administrativo","nucleo":"general","origen":"estilo","fuente":"Ley 1437 de 2011, art. 137","enunciado":"Un ciudadano sin interés particular quiere atacar un decreto departamental de carácter general expedido sin competencia. El medio de control procedente es","opciones":{"A":"la nulidad.","B":"la acción de tutela.","C":"la nulidad y restablecimiento del derecho.","D":"la reparación directa."},"correcta":"A","explicacion":"El artículo 137 permite a toda persona solicitar la nulidad de actos de carácter general por infracción de normas, falta de competencia, expedición irregular, desconocimiento del derecho de audiencia, falsa motivación o desviación de poder. La nulidad y restablecimiento procede cuando hay lesión de un derecho subjetivo.","dificultad":1},{"id":"adm-0021","eje":"administrativo","nucleo":"general","origen":"estilo","fuente":"Ley 1437 de 2011, art. 164, num. 2, lit. d","enunciado":"Un servidor fue declarado insubsistente mediante acto que considera ilegal y quiere ser reintegrado. Debe presentar la demanda de nulidad y restablecimiento del derecho, por regla general, dentro de los","opciones":{"A":"cuatro meses contados a partir del día siguiente a la comunicación, notificación, ejecución o publicación del acto.","B":"cinco años contados desde la ejecutoria.","C":"dos años contados desde el retiro.","D":"treinta días hábiles desde la notificación."},"correcta":"A","explicacion":"El literal d del numeral 2 del artículo 164 fija cuatro meses para la nulidad y restablecimiento del derecho, contados desde el día siguiente a la comunicación, notificación, ejecución o publicación del acto. Los dos años corresponden a la reparación directa.","dificultad":2},{"id":"adm-0022","eje":"administrativo","nucleo":"general","origen":"estilo","fuente":"Ley 1437 de 2011, arts. 140 y 164, num. 2, lit. i","enunciado":"Una persona resultó lesionada por la caída de un muro en una obra pública. Para pedir la indemnización del daño debe presentar la demanda de reparación directa dentro de","opciones":{"A":"cinco años, contados desde el hecho.","B":"dos años, contados a partir del día siguiente a la ocurrencia del hecho o de cuando tuvo o debió tener conocimiento de él.","C":"un año, contado desde la terminación de la obra.","D":"cuatro meses, contados desde el hecho."},"correcta":"B","explicacion":"El literal i del numeral 2 del artículo 164 dispone que la reparación directa debe presentarse dentro de dos años contados desde el día siguiente a la acción u omisión causante del daño, o desde cuando el demandante tuvo o debió tener conocimiento de él.","dificultad":1},{"id":"adm-0023","eje":"administrativo","nucleo":"general","origen":"estilo","fuente":"Ley 1437 de 2011, art. 161, num. 1","enunciado":"Antes de presentar una demanda de reparación directa por un asunto conciliable, el demandante debe","opciones":{"A":"presentar derecho de petición de reconocimiento.","B":"obtener concepto previo del Consejo de Estado.","C":"interponer recurso de apelación ante la entidad.","D":"agotar la conciliación extrajudicial como requisito de procedibilidad."},"correcta":"D","explicacion":"El numeral 1 del artículo 161 establece que, cuando los asuntos sean conciliables, la conciliación extrajudicial es requisito de procedibilidad de las demandas de nulidad y restablecimiento, reparación directa y controversias contractuales. Esta conciliación se adelanta ante los agentes del Ministerio Público.","dificultad":2},{"id":"adm-0024","eje":"administrativo","nucleo":"general","origen":"estilo","fuente":"Ley 1437 de 2011, art. 141","enunciado":"Un contratista quiere que se declare el incumplimiento de la entidad contratante y se le indemnicen los perjuicios. El medio de control es","opciones":{"A":"acción de cumplimiento.","B":"nulidad simple.","C":"controversias contractuales.","D":"reparación directa."},"correcta":"C","explicacion":"El artículo 141 permite a cualquiera de las partes de un contrato estatal pedir que se declare su existencia, nulidad, revisión, incumplimiento, la nulidad de actos contractuales y la indemnización de perjuicios. La reparación directa procede por hechos u omisiones extracontractuales.","dificultad":1},{"id":"adm-0025","eje":"administrativo","nucleo":"general","origen":"estilo","fuente":"Ley 1437 de 2011, art. 137","enunciado":"Se demanda la nulidad de un acto alegando que el funcionario lo expidió con un fin distinto del interés público para el que se le confirió la competencia. La causal invocada es","opciones":{"A":"desviación de las atribuciones propias de quien lo profirió.","B":"falta de competencia.","C":"falsa motivación.","D":"expedición irregular."},"correcta":"A","explicacion":"La desviación de poder, prevista en el artículo 137 como desviación de las atribuciones propias de quien profirió el acto, se configura cuando la competencia se usa para un fin distinto al previsto. La falsa motivación se refiere a motivos inexistentes o erróneos.","dificultad":2},{"id":"adm-0026","eje":"administrativo","nucleo":"general","origen":"estilo","fuente":"Ley 1437 de 2011, art. 40","enunciado":"En una actuación administrativa, el interesado solicita una prueba y la autoridad la niega mediante un acto. Contra ese acto","opciones":{"A":"procede la acción de tutela de manera directa.","B":"procede reposición y apelación.","C":"procede únicamente el recurso de queja.","D":"no proceden recursos, aunque el interesado puede controvertir las pruebas antes de la decisión de fondo."},"correcta":"D","explicacion":"El artículo 40 dispone que contra el acto que decide la solicitud de pruebas no proceden recursos, y que el interesado tendrá oportunidad de controvertir las pruebas antes de la decisión de fondo.","dificultad":3},{"id":"adm-0027","eje":"administrativo","nucleo":"general","origen":"estilo","fuente":"Ley 1437 de 2011, art. 303","enunciado":"Ante la Jurisdicción de lo Contencioso Administrativo, el Ministerio Público","opciones":{"A":"interviene únicamente cuando el juez lo solicita.","B":"solo puede intervenir en los procesos de nulidad electoral.","C":"puede actuar como demandante o como sujeto procesal especial e intervenir en todos los procesos en defensa del orden jurídico, el patrimonio público y los derechos fundamentales.","D":"actúa exclusivamente como apoderado de las entidades públicas demandadas."},"correcta":"C","explicacion":"El artículo 303 faculta al Ministerio Público para actuar como demandante o como sujeto procesal especial en todos los procesos e incidentes de esa jurisdicción, en defensa del orden jurídico, del patrimonio público y de los derechos y garantías fundamentales. No es apoderado de las entidades.","dificultad":1},{"id":"adm-0028","eje":"administrativo","nucleo":"general","origen":"estilo","fuente":"Ley 1437 de 2011, art. 84","enunciado":"El silencio administrativo positivo","opciones":{"A":"opera cuando el peticionario lo invoca en su solicitud.","B":"solo opera en los casos expresamente previstos en disposiciones legales especiales.","C":"es la regla general cuando la entidad no responde en quince días.","D":"opera siempre que la petición sea de documentos."},"correcta":"B","explicacion":"El artículo 84 dispone que solamente en los casos expresamente previstos en disposiciones legales especiales el silencio de la administración equivale a decisión positiva. La regla general es el silencio negativo (art. 83).","dificultad":2},{"id":"comp-0001","eje":"competencias","nucleo":"competencias","origen":"estilo","fuente":"Cartilla PGN 2015, competencia Responsabilidad con la organización; Diccionario de competencias PGN","enunciado":"Faltando una hora para terminar la jornada, su jefe le informa que un informe para la Procuraduría Delegada debe entregarse mañana a primera hora y aún falta revisar los anexos. Usted","opciones":{"A":"informa que su horario terminó y que lo revisará en la semana.","B":"organiza los anexos pendientes, los revisa con prioridad y avisa a su jefe si necesita apoyo para cumplir el plazo.","C":"pide a un compañero que lo revise por usted sin informar al jefe.","D":"entrega el informe sin anexos y explica que no hubo tiempo."},"correcta":"B","explicacion":"La responsabilidad con la organización implica asumir con compromiso los objetivos asignados. La conducta más alineada es priorizar la tarea, cumplir el plazo con calidad y comunicar oportunamente las necesidades de apoyo, sin trasladar la responsabilidad ni entregar trabajo incompleto.","dificultad":1},{"id":"comp-0002","eje":"competencias","nucleo":"competencias","origen":"estilo","fuente":"Cartilla PGN 2015, competencia Organización del trabajo","enunciado":"Recibe al mismo tiempo cinco expedientes con términos distintos de vencimiento. La forma de proceder más adecuada es","opciones":{"A":"atenderlos en el orden en que llegaron, sin revisar términos.","B":"empezar por el más sencillo para avanzar rápido.","C":"esperar instrucciones del jefe para cada expediente.","D":"registrar los vencimientos, ordenar los expedientes por urgencia legal y fijar un cronograma de trabajo."},"correcta":"D","explicacion":"Organización del trabajo es la capacidad para realizar actividades siguiendo procesos, procedimientos y criterios establecidos. Identificar términos y planificar según la urgencia legal evita vencimientos, que en materia disciplinaria pueden causar prescripción.","dificultad":1},{"id":"comp-0003","eje":"competencias","nucleo":"competencias","origen":"estilo","fuente":"Cartilla PGN 2015, competencia Investigación","enunciado":"Debe proyectar un concepto sobre un tema que no conoce bien y en el que hay jurisprudencia reciente. Usted","opciones":{"A":"consulta la norma vigente, la jurisprudencia reciente y los conceptos previos de la entidad, y contrasta las posiciones antes de redactar.","B":"redacta con base en lo que recuerda de la universidad.","C":"copia la posición que encuentre primero en internet.","D":"reutiliza un concepto antiguo de otro tema similar."},"correcta":"A","explicacion":"La competencia Investigación es la capacidad para buscar información relevante y pertinente y analizarla con dominio técnico. Consultar fuentes vigentes y contrastarlas es la conducta esperada en un profesional.","dificultad":1},{"id":"comp-0004","eje":"competencias","nucleo":"competencias","origen":"estilo","fuente":"Cartilla PGN 2015, competencia Pensamiento conceptual","enunciado":"Una queja describe muchos hechos mezclados sobre varios funcionarios y fechas. Para analizarla usted","opciones":{"A":"abre investigación contra todos los mencionados para no omitir a nadie.","B":"pide al quejoso que la reescriba antes de cualquier análisis.","C":"separa los hechos por persona, fecha y conducta, e identifica cuáles tienen relevancia disciplinaria.","D":"la archiva porque está desordenada."},"correcta":"C","explicacion":"El pensamiento conceptual es la capacidad de entender una situación a partir de los elementos que la conforman. Descomponer la queja permite identificar autores, conductas y relevancia antes de decidir.","dificultad":2},{"id":"comp-0005","eje":"competencias","nucleo":"competencias","origen":"estilo","fuente":"Cartilla PGN 2015, competencia Orientación a resultados","enunciado":"Su dependencia tiene como meta reducir en un 20 % el tiempo de respuesta a las quejas este año. A mitad de año va en un 8 %. Usted","opciones":{"A":"analiza dónde se concentran las demoras y propone acciones concretas a su jefe para alcanzar la meta.","B":"acelera las respuestas sin revisar su calidad.","C":"considera que la meta era muy alta y deja de medirla.","D":"espera al cierre del año para explicar por qué no se cumplió."},"correcta":"A","explicacion":"La orientación a resultados es la capacidad de lograr las metas alineadas con la misión. Implica hacer seguimiento, identificar causas y proponer mejoras sin sacrificar la calidad.","dificultad":1},{"id":"comp-0006","eje":"competencias","nucleo":"competencias","origen":"estilo","fuente":"Cartilla PGN 2015, competencia Cumplimiento de parámetros de trabajo","enunciado":"Un compañero le sugiere omitir la comunicación al quejoso de una decisión de archivo porque 'nadie la revisa'. Usted","opciones":{"A":"la omite para ganar tiempo.","B":"la omite solo si el quejoso es anónimo.","C":"la hace verbalmente sin dejar constancia.","D":"realiza la comunicación conforme a la norma y le explica a su compañero por qué es obligatoria."},"correcta":"D","explicacion":"Cumplimiento de parámetros de trabajo es la capacidad para aplicar la normatividad interna y externa. La decisión de archivo debe comunicarse al quejoso (Ley 1952 de 2019, art. 90), y omitirlo afecta el debido proceso.","dificultad":1},{"id":"comp-0007","eje":"competencias","nucleo":"competencias","origen":"estilo","fuente":"Cartilla PGN 2015, competencia Creatividad e innovación (nivel Asesor)","enunciado":"Como asesor, nota que cada mes se pierden horas consolidando a mano los reportes de las procuradurías provinciales. Usted","opciones":{"A":"delega la consolidación en un pasante.","B":"diseña una propuesta de formato único con consolidación automática, la prueba con dos provinciales y la presenta con resultados.","C":"sigue el procedimiento actual porque siempre ha funcionado.","D":"cambia el formato de inmediato para todas sin consultar."},"correcta":"B","explicacion":"La creatividad e innovación implica generar soluciones nuevas y útiles. Proponer, probar y mostrar resultados antes de generalizar combina innovación con responsabilidad institucional.","dificultad":2},{"id":"comp-0008","eje":"competencias","nucleo":"competencias","origen":"estilo","fuente":"Diccionario de competencias PGN, Adaptación al cambio","enunciado":"La entidad implanta un nuevo sistema de gestión documental electrónico que cambia la forma en que usted tramita expedientes. Usted","opciones":{"A":"critica el sistema ante los usuarios.","B":"pide traslado a una dependencia donde no se use.","C":"asiste a la capacitación, aplica el sistema y reporta las fallas que encuentre para mejorarlo.","D":"sigue usando el método anterior hasta que se lo exijan."},"correcta":"C","explicacion":"La adaptación al cambio supone ajustarse a nuevas situaciones generadas por factores internos o externos. Aprender la herramienta y contribuir a su mejora es la conducta esperada.","dificultad":1},{"id":"comp-0009","eje":"competencias","nucleo":"competencias","origen":"estilo","fuente":"Diccionario de competencias PGN, Autocontrol","enunciado":"En una audiencia, el apoderado del investigado lo acusa en voz alta de parcialidad. Usted","opciones":{"A":"le responde en el mismo tono.","B":"suspende la audiencia y se retira.","C":"mantiene la calma, deja constancia de la manifestación y continúa la diligencia conforme al procedimiento.","D":"ignora al apoderado durante el resto de la diligencia."},"correcta":"C","explicacion":"El autocontrol es la capacidad de dominar las propias emociones ante situaciones demandantes. Dejar constancia y seguir el trámite protege el proceso; si se formula recusación, se tramita por la vía legal.","dificultad":1},{"id":"comp-0010","eje":"competencias","nucleo":"competencias","origen":"estilo","fuente":"Diccionario de competencias PGN, Aprendizaje continuo","enunciado":"Se expide una reforma al procedimiento disciplinario que afecta los expedientes a su cargo. Usted","opciones":{"A":"estudia la reforma, identifica qué expedientes afecta y ajusta su trámite.","B":"sigue aplicando la norma anterior porque conoce mejor su manejo.","C":"pregunta a un compañero y aplica su resumen sin leer la norma.","D":"espera a que la entidad programe una capacitación."},"correcta":"A","explicacion":"El aprendizaje continuo implica actualizar conocimientos por iniciativa propia. Estudiar directamente la norma y aplicarla a los casos evita errores de procedimiento.","dificultad":1},{"id":"comp-0011","eje":"competencias","nucleo":"competencias","origen":"estilo","fuente":"Cartilla PGN 2015, competencia Responsabilidad con la organización","enunciado":"Se da cuenta de que cometió un error en el cálculo de un término en un auto ya comunicado. Usted","opciones":{"A":"atribuye el error al sistema de información.","B":"espera a ver si alguien lo nota.","C":"corrige el documento en el expediente sin dejar constancia.","D":"informa a su jefe de inmediato y propone la corrección por la vía procesal adecuada."},"correcta":"D","explicacion":"Asumir con compromiso los objetivos de la entidad incluye reconocer los errores propios y corregirlos por los medios legales. Ocultar o alterar documentos agrava el problema y puede constituir falta.","dificultad":1},{"id":"comp-0012","eje":"competencias","nucleo":"competencias","origen":"estilo","fuente":"Diccionario de competencias PGN, Trabajo en equipo","enunciado":"Un compañero nuevo tiene dificultades con el manejo del sistema de expedientes y retrasa el trabajo del grupo. Usted","opciones":{"A":"asume las tareas del compañero sin decirle nada.","B":"le ofrece una explicación breve de los pasos clave y comparte la guía de uso.","C":"espera a que aprenda solo.","D":"informa al jefe que el compañero no sirve para el cargo."},"correcta":"B","explicacion":"El trabajo en equipo implica colaborar para cumplir los objetivos comunes. Apoyar el aprendizaje del compañero mejora el resultado del grupo sin desplazar sus responsabilidades.","dificultad":1},{"id":"comp-0013","eje":"competencias","nucleo":"competencias","origen":"estilo","fuente":"Cartilla PGN 2015, competencia Investigación","enunciado":"Durante una visita preventiva, un funcionario le entrega un informe que contradice los datos publicados por la entidad. Usted","opciones":{"A":"no lo menciona para evitar conflictos.","B":"acepta el informe entregado porque es el más reciente.","C":"descarta el informe porque contradice la información oficial.","D":"solicita los soportes de ambas fuentes, los compara y deja constancia de la diferencia en el informe de visita."},"correcta":"D","explicacion":"La investigación exige buscar información pertinente y evaluarla con rigor técnico. Verificar soportes y documentar la diferencia permite una conclusión objetiva.","dificultad":2},{"id":"comp-0014","eje":"competencias","nucleo":"competencias","origen":"estilo","fuente":"Diccionario de competencias PGN, Orientación al usuario","enunciado":"Un ciudadano llega molesto porque su queja lleva meses sin respuesta. Usted","opciones":{"A":"le pide que presente una nueva queja.","B":"lo escucha, consulta el estado real del trámite y le informa con claridad qué sigue y en qué plazo.","C":"le dice que no es su dependencia y lo envía a otra ventanilla.","D":"le promete una respuesta inmediata aunque no sabe si es posible."},"correcta":"B","explicacion":"La orientación al usuario es la capacidad de atender las necesidades de los usuarios conforme a las responsabilidades de la entidad. Dar información veraz y concreta es mejor que remitir sin orientar o prometer lo que no puede cumplirse.","dificultad":1},{"id":"comp-0015","eje":"competencias","nucleo":"competencias","origen":"estilo","fuente":"Cartilla PGN 2015, competencia Organización del trabajo","enunciado":"Su jefe le asigna una tarea urgente mientras usted adelanta otra con vencimiento próximo. Usted","opciones":{"A":"le informa el estado de la tarea en curso y acuerda con él cuál debe priorizarse.","B":"rechaza la nueva tarea.","C":"intenta hacer ambas a la vez sin avisar del riesgo.","D":"deja la tarea en curso sin informar."},"correcta":"A","explicacion":"Organizar el trabajo implica gestionar prioridades con base en criterios claros. Informar y acordar la prioridad evita incumplimientos y alinea el trabajo con las necesidades de la dependencia.","dificultad":1},{"id":"comp-0016","eje":"competencias","nucleo":"competencias","origen":"estilo","fuente":"Diccionario de competencias PGN, Compromiso con la ética","enunciado":"Un conocido le pide que le adelante información sobre el estado de una investigación reservada contra un amigo suyo. Usted","opciones":{"A":"le da información general sin documentos.","B":"le muestra el expediente pero sin copias.","C":"se niega, le explica que la actuación tiene reserva y que solo los sujetos procesales pueden acceder a ella.","D":"le sugiere hablar con otro funcionario."},"correcta":"C","explicacion":"La ética en el servicio público exige respetar la reserva de las actuaciones disciplinarias y no usar el cargo en beneficio de terceros. Revelar información reservada puede constituir falta y delito.","dificultad":1},{"id":"comp-0017","eje":"competencias","nucleo":"competencias","origen":"estilo","fuente":"Cartilla PGN 2015, competencia Pensamiento conceptual","enunciado":"Le piden explicar a un grupo de personeros los cambios de la Ley 2094 de 2021. Usted","opciones":{"A":"presenta un esquema de las etapas antes y después de la reforma, con sus efectos prácticos y ejemplos.","B":"lee el texto completo de la ley.","C":"entrega una copia de la ley sin explicación.","D":"se limita a responder preguntas sueltas."},"correcta":"A","explicacion":"El pensamiento conceptual permite entender y explicar un tema a partir de sus elementos. Un esquema comparativo con efectos prácticos facilita la comprensión y la aplicación.","dificultad":2},{"id":"comp-0018","eje":"competencias","nucleo":"competencias","origen":"estilo","fuente":"Cartilla PGN 2015, competencia Cumplimiento de parámetros de trabajo","enunciado":"Un superior le ordena verbalmente archivar una actuación sin el análisis de pruebas que exige la ley. Usted","opciones":{"A":"archiva sin análisis porque es una orden.","B":"ignora la orden sin decir nada.","C":"denuncia de inmediato al superior ante los medios.","D":"le manifiesta respetuosamente que la decisión requiere análisis motivado y le propone el proyecto ajustado a la norma."},"correcta":"D","explicacion":"Cumplir los parámetros de trabajo implica aplicar la normatividad. Una orden contraria a la ley no debe ejecutarse; lo adecuado es advertirlo por los canales institucionales y proponer la decisión conforme a derecho.","dificultad":2},{"id":"comp-0019","eje":"competencias","nucleo":"competencias","origen":"estilo","fuente":"Diccionario de competencias PGN, Autocrítica","enunciado":"En la evaluación de desempeño su jefe señala que sus proyectos tienen errores de redacción frecuentes. Usted","opciones":{"A":"acepta el comentario pero no cambia su forma de trabajar.","B":"revisa los ejemplos señalados, identifica sus errores habituales y establece una lista de verificación antes de entregar.","C":"argumenta que la redacción no es importante si el contenido está bien.","D":"pide que otro jefe lo evalúe."},"correcta":"B","explicacion":"La autocrítica es la capacidad de evaluar el propio desempeño, detectar lo que debe mejorar y actuar en consecuencia. Convertir la observación en un plan concreto es la conducta esperada.","dificultad":1},{"id":"comp-0020","eje":"competencias","nucleo":"competencias","origen":"estilo","fuente":"Cartilla PGN 2015, competencia Orientación a resultados","enunciado":"Un procedimiento interno exige tres firmas para un trámite sencillo, lo que genera demoras. Usted","opciones":{"A":"omite dos firmas para agilizar.","B":"se queja con los usuarios del procedimiento.","C":"documenta el impacto de la demora y propone a la instancia competente simplificar el trámite sin afectar los controles necesarios.","D":"no hace nada porque el procedimiento no es suyo."},"correcta":"C","explicacion":"Orientarse a resultados implica buscar eficiencia dentro de la legalidad. Proponer la mejora por el canal competente respeta los controles y apunta a la meta institucional.","dificultad":2},{"id":"comp-0021","eje":"competencias","nucleo":"competencias","origen":"estilo","fuente":"Diccionario de competencias PGN, Trabajo en equipo","enunciado":"En un grupo de trabajo hay desacuerdo sobre la calificación jurídica de una falta. Usted","opciones":{"A":"se retira del grupo.","B":"acepta cualquier posición para evitar conflicto.","C":"impone su criterio porque tiene más experiencia.","D":"expone sus argumentos con sustento normativo, escucha los de los demás y apoya la decisión que se adopte por la instancia competente."},"correcta":"D","explicacion":"Trabajar en equipo supone aportar con argumentos, escuchar y respetar la decisión colectiva o de la autoridad competente. Imponer, retirarse o ceder sin criterio no aporta al resultado.","dificultad":1},{"id":"comp-0022","eje":"competencias","nucleo":"competencias","origen":"estilo","fuente":"Cartilla PGN 2015, competencia Responsabilidad con la organización","enunciado":"Observa que un compañero se lleva a casa expedientes originales con información reservada. Usted","opciones":{"A":"publica la situación en el grupo de chat de la dependencia.","B":"le recuerda las reglas de custodia y, si persiste, informa al superior.","C":"no dice nada porque no es su asunto.","D":"le pide que también le lleve algunos de los suyos."},"correcta":"B","explicacion":"La responsabilidad con la organización incluye velar por la custodia de la información. Advertir al compañero y, si es necesario, informar al superior protege la reserva sin exponerlo indebidamente.","dificultad":1},{"id":"comp-0023","eje":"competencias","nucleo":"competencias","origen":"estilo","fuente":"Diccionario de competencias PGN, Adaptación al cambio","enunciado":"Lo trasladan a una dependencia con funciones distintas a las que conoce. Usted","opciones":{"A":"solicita volver a su dependencia anterior de inmediato.","B":"trabaja solo en lo que ya conocía.","C":"identifica las funciones y normas del nuevo cargo, pide orientación inicial y se pone al día con los expedientes en curso.","D":"espera a que le asignen tareas concretas."},"correcta":"C","explicacion":"Adaptarse al cambio implica asumir de manera activa las nuevas responsabilidades, buscar la información necesaria y ponerse al día sin esperar a que todo se le indique.","dificultad":1},{"id":"comp-0024","eje":"competencias","nucleo":"competencias","origen":"estilo","fuente":"Cartilla PGN 2015, competencia Investigación","enunciado":"Debe recaudar pruebas sobre un presunto pago irregular en un municipio. Usted","opciones":{"A":"define qué hechos debe probar, identifica los documentos y testigos conducentes y planifica su práctica.","B":"se basa solo en la versión del quejoso.","C":"espera a que el investigado aporte pruebas.","D":"pide todos los documentos de la alcaldía de los últimos diez años."},"correcta":"A","explicacion":"La investigación requiere buscar información pertinente con criterio técnico. Planificar las pruebas según los hechos a demostrar respeta la conducencia, pertinencia y utilidad, y evita recaudos desproporcionados.","dificultad":2},{"id":"comp-0025","eje":"competencias","nucleo":"competencias","origen":"estilo","fuente":"Diccionario de competencias PGN, Orientación al usuario","enunciado":"Una persona con discapacidad visual pide información sobre cómo presentar una queja. Usted","opciones":{"A":"le pide que vuelva con un acompañante.","B":"le indica que use la página web.","C":"le entrega el formulario impreso.","D":"le explica verbalmente el trámite, le ofrece recibir la queja de forma verbal y la lee en voz alta antes de radicarla."},"correcta":"D","explicacion":"La orientación al usuario exige atención con enfoque diferencial. Ajustar el canal y verificar que la persona conozca el contenido garantiza su derecho de acceso.","dificultad":1},{"id":"comp-0026","eje":"competencias","nucleo":"competencias","origen":"estilo","fuente":"Cartilla PGN 2015, competencia Organización del trabajo","enunciado":"Va a salir a vacaciones y tiene expedientes con términos que vencen en ese período. Usted","opciones":{"A":"deja un informe de estado de cada expediente con sus vencimientos y lo entrega a quien lo reemplaza, con copia al jefe.","B":"suspende los términos por su cuenta.","C":"se lleva los expedientes para revisarlos en vacaciones.","D":"confía en que el reemplazo revise el sistema."},"correcta":"A","explicacion":"Organizar el trabajo incluye asegurar la continuidad del servicio. Un empalme documentado evita vencimientos; los términos no pueden suspenderse a discreción ni sacarse expedientes de la sede.","dificultad":1},{"id":"comp-0027","eje":"competencias","nucleo":"competencias","origen":"estilo","fuente":"Diccionario de competencias PGN, Autocontrol","enunciado":"Recibe un correo de un compañero con críticas injustas a su trabajo, con copia a toda la dependencia. Usted","opciones":{"A":"reenvía el correo a otras dependencias.","B":"responde de inmediato a todos con un tono fuerte.","C":"espera a estar tranquilo, conversa en privado con el compañero y, si es necesario, aclara los hechos con datos ante el jefe.","D":"deja de colaborar con ese compañero."},"correcta":"C","explicacion":"El autocontrol permite manejar las emociones ante situaciones que comprometen la convivencia. Tratar el asunto en privado y con datos evita escalar el conflicto.","dificultad":1},{"id":"comp-0028","eje":"competencias","nucleo":"competencias","origen":"estilo","fuente":"Cartilla PGN 2015, competencia Creatividad e innovación (nivel Asesor)","enunciado":"El despacho necesita llegar a más municipios con su labor preventiva, pero no hay presupuesto para más visitas. Como asesor usted","opciones":{"A":"pide a los municipios que se autoevalúen sin seguimiento.","B":"propone combinar visitas presenciales priorizadas por riesgo con mesas virtuales y reportes en línea, y plantea indicadores para medir su efecto.","C":"concluye que sin presupuesto no se puede hacer nada.","D":"reduce las visitas a los municipios más cercanos."},"correcta":"B","explicacion":"La creatividad e innovación busca soluciones nuevas a restricciones reales. Priorizar por riesgo, usar canales virtuales y medir resultados amplía la cobertura con los mismos recursos.","dificultad":2},{"id":"comp-0029","eje":"competencias","nucleo":"competencias","origen":"estilo","fuente":"Cartilla PGN 2015, competencia Cumplimiento de parámetros de trabajo","enunciado":"El manual de procesos exige registrar cada actuación en el sistema el mismo día. En una semana de mucho trabajo, usted","opciones":{"A":"reserva un tiempo diario para el registro y, si no alcanza, informa al jefe para reorganizar cargas.","B":"registra todo a fin de mes.","C":"deja de registrar las actuaciones menores.","D":"pide a un pasante que registre con su clave."},"correcta":"A","explicacion":"Cumplir los parámetros de trabajo exige aplicar la normatividad interna aun con presión. Planificar el registro y comunicar dificultades es lo adecuado; compartir claves vulnera la seguridad de la información.","dificultad":1},{"id":"comp-0030","eje":"competencias","nucleo":"competencias","origen":"estilo","fuente":"Diccionario de competencias PGN, Comunicación efectiva","enunciado":"Debe explicar a un ciudadano sin formación jurídica por qué su queja fue archivada. Usted","opciones":{"A":"le explica los fundamentos con términos técnicos y citas jurisprudenciales.","B":"le dice que no puede hacer nada más.","C":"le entrega la decisión y le dice que la lea.","D":"le explica con lenguaje sencillo los motivos de la decisión, los recursos que proceden y el plazo para interponerlos."},"correcta":"D","explicacion":"Comunicar con efectividad implica adaptar el mensaje al interlocutor. El ciudadano debe entender la decisión y conocer los recursos, como la apelación contra el archivo (Ley 1952 de 2019, art. 134).","dificultad":1},{"id":"comp-0031","eje":"competencias","nucleo":"competencias","origen":"estilo","fuente":"Cartilla PGN 2015, competencia Orientación a resultados","enunciado":"Le asignan un indicador de expedientes evacuados por mes. Nota que podría cumplirlo archivando casos sin el análisis suficiente. Usted","opciones":{"A":"ignora el indicador.","B":"deja de recibir expedientes nuevos.","C":"busca cumplir la meta con decisiones de fondo bien sustentadas y alerta a su jefe si el indicador incentiva decisiones apresuradas.","D":"archiva casos rápidamente para cumplir el indicador."},"correcta":"C","explicacion":"La orientación a resultados se refiere a metas alineadas con la misión. Una meta numérica no justifica decisiones sin sustento; advertir el efecto del indicador ayuda a mejorar la gestión.","dificultad":2},{"id":"comp-0032","eje":"competencias","nucleo":"competencias","origen":"estilo","fuente":"Diccionario de competencias PGN, Autoconfianza","enunciado":"En una reunión con directivos de otra entidad, usted tiene una posición jurídica distinta a la de la mayoría, sustentada en una norma clara. Usted","opciones":{"A":"guarda silencio para no contradecir a los directivos.","B":"expone su posición con respeto y con la norma que la sustenta.","C":"cambia su posición para coincidir con la mayoría.","D":"espera a que termine la reunión para criticar la decisión."},"correcta":"B","explicacion":"La autoconfianza implica reconocer las propias fortalezas y sostener opiniones fundadas ante superiores o terceros, con respeto. Callar o cambiar de opinión sin razones no aporta a la decisión.","dificultad":1},{"id":"comp-0033","eje":"competencias","nucleo":"competencias","origen":"estilo","fuente":"Cartilla PGN 2015, competencia Pensamiento conceptual","enunciado":"Nota que en varios municipios se repite el mismo tipo de queja sobre contratación directa. Usted","opciones":{"A":"identifica el patrón común y propone a su jefe una acción preventiva general sobre esa modalidad.","B":"archiva las quejas porque son repetitivas.","C":"tramita cada queja por separado sin relacionarlas.","D":"concluye que todos los alcaldes actúan de mala fe."},"correcta":"A","explicacion":"El pensamiento conceptual permite reconocer patrones y relaciones entre situaciones. Identificar una tendencia y proponer una acción preventiva aporta más que tramitar casos aislados.","dificultad":2},{"id":"comp-0034","eje":"competencias","nucleo":"competencias","origen":"estilo","fuente":"Diccionario de competencias PGN, Trabajo en equipo","enunciado":"Su equipo debe entregar un informe conjunto y usted terminó su parte antes. Usted","opciones":{"A":"reescribe las partes de los demás sin consultarles.","B":"ofrece apoyo a quienes van más atrasados para cumplir el plazo común.","C":"entrega su parte y se desentiende del resto.","D":"informa al jefe quiénes están atrasados."},"correcta":"B","explicacion":"El trabajo en equipo implica responsabilidad por el resultado común. Ofrecer apoyo coordinado es la conducta más alineada; reescribir sin consultar afecta la colaboración.","dificultad":1},{"id":"comp-0035","eje":"competencias","nucleo":"competencias","origen":"estilo","fuente":"Cartilla PGN 2015, competencia Responsabilidad con la organización","enunciado":"Un medio de comunicación lo contacta para que opine sobre una investigación de su dependencia. Usted","opciones":{"A":"da una opinión personal sin revelar nombres.","B":"concede la entrevista para mostrar la gestión de la entidad.","C":"niega que exista la investigación.","D":"remite la solicitud a la oficina de prensa, porque no está autorizado para declarar sobre actuaciones en curso."},"correcta":"D","explicacion":"La responsabilidad con la organización implica respetar los canales institucionales y la reserva. La comunicación pública la maneja la dependencia autorizada.","dificultad":1},{"id":"comp-0036","eje":"competencias","nucleo":"competencias","origen":"estilo","fuente":"Diccionario de competencias PGN, Aprendizaje continuo","enunciado":"Comete el mismo tipo de error de notificación en dos expedientes. Usted","opciones":{"A":"considera que fue mala suerte.","B":"espera a que el error genere una nulidad para aprender.","C":"revisa la norma de notificaciones, elabora una guía rápida para su trabajo y la comparte con el equipo.","D":"pide que otro funcionario haga las notificaciones."},"correcta":"C","explicacion":"El aprendizaje continuo convierte los errores en mejoras. Repasar la norma y crear una herramienta práctica evita repetir el error y beneficia al equipo.","dificultad":1},{"id":"comp-0037","eje":"competencias","nucleo":"competencias","origen":"estilo","fuente":"Cartilla PGN 2015, competencia Investigación","enunciado":"Un testigo clave da una versión que parece contradictoria con un documento del expediente. Usted","opciones":{"A":"no menciona la contradicción para no influir al testigo.","B":"descarta el testimonio.","C":"le pone de presente el documento en la diligencia y le pide que explique la diferencia, dejando constancia.","D":"descarta el documento."},"correcta":"C","explicacion":"Investigar con rigor implica contrastar las pruebas y aclarar las contradicciones en la oportunidad procesal, dejando registro. Descartar una prueba sin análisis afecta la investigación integral.","dificultad":2},{"id":"comp-0038","eje":"competencias","nucleo":"competencias","origen":"estilo","fuente":"Diccionario de competencias PGN, Compromiso con la ética","enunciado":"Le asignan un expediente en el que el investigado es su antiguo socio de negocios. Usted","opciones":{"A":"tramita el expediente sin decir nada porque ya no son socios.","B":"manifiesta su impedimento por escrito ante quien corresponda antes de actuar.","C":"pide a un compañero que firme las decisiones por usted.","D":"tramita el expediente con especial rigor."},"correcta":"B","explicacion":"La ética y la imparcialidad exigen apartarse cuando existe una causal de impedimento o un conflicto de intereses (Ley 1952 de 2019, arts. 44 y 104). El trámite de impedimento es la vía correcta.","dificultad":1},{"id":"comp-0039","eje":"competencias","nucleo":"competencias","origen":"estilo","fuente":"Cartilla PGN 2015, competencia Organización del trabajo","enunciado":"Recibe muchas consultas por correo que interrumpen constantemente su trabajo de análisis. Usted","opciones":{"A":"define franjas del día para revisar y responder los correos, y atiende de inmediato solo los urgentes.","B":"pide que no le envíen más consultas.","C":"deja de leer los correos.","D":"responde cada correo apenas llega."},"correcta":"A","explicacion":"Organizar el trabajo implica administrar el tiempo según prioridades. Programar la atención del correo protege las tareas de análisis sin desatender lo urgente.","dificultad":1},{"id":"comp-0040","eje":"competencias","nucleo":"competencias","origen":"estilo","fuente":"Diccionario de competencias PGN, Orientación al usuario","enunciado":"Un alcalde pide orientación preventiva sobre cómo adelantar un proceso de contratación sin incurrir en faltas. Usted","opciones":{"A":"le revisa y aprueba los pliegos antes de publicarlos.","B":"le recomienda un contratista confiable.","C":"le dice que la Procuraduría no asesora a entidades.","D":"le orienta sobre las normas aplicables y los riesgos frecuentes, sin coadministrar ni tomar decisiones por la entidad."},"correcta":"D","explicacion":"La función preventiva permite orientar y advertir, pero la Procuraduría no coadministra ni sustituye a la entidad en sus decisiones. Recomendar contratistas o aprobar pliegos excede la función.","dificultad":2},{"id":"comp-0041","eje":"competencias","nucleo":"competencias","origen":"estilo","fuente":"Cartilla PGN 2015, competencia Orientación a resultados","enunciado":"Al cierre del trimestre, su dependencia superó la meta de decisiones, pero muchas fueron revocadas en segunda instancia. Usted","opciones":{"A":"destaca solo el cumplimiento de la meta en el informe.","B":"atribuye las revocatorias a criterios distintos de la segunda instancia.","C":"analiza las causas de las revocatorias y propone ajustes de calidad en los proyectos.","D":"propone bajar la meta para tener más tiempo."},"correcta":"C","explicacion":"Los resultados deben medirse por su aporte a la misión. Analizar las revocatorias y mejorar la calidad es más coherente con la orientación a resultados que reportar solo cantidades.","dificultad":2},{"id":"comp-0042","eje":"competencias","nucleo":"competencias","origen":"estilo","fuente":"Cartilla PGN 2015, competencia Cumplimiento de parámetros de trabajo","enunciado":"Un usuario le ofrece pagar las copias de un expediente directamente en efectivo a usted para agilizar la entrega. Usted","opciones":{"A":"recibe el dinero y lo consigna después.","B":"le indica el procedimiento oficial de pago y entrega, y no recibe dinero.","C":"le entrega las copias gratis para evitar el trámite.","D":"le pide que pague a un tercero de confianza."},"correcta":"B","explicacion":"Aplicar la normatividad interna implica seguir el procedimiento oficial. Recibir dinero directamente puede constituir falta disciplinaria o delito, aun si se consigna después.","dificultad":1},{"id":"cons-0001","eje":"constitucional","nucleo":"general","origen":"estilo","fuente":"Constitución Política, art. 1","enunciado":"Según el artículo 1 de la Constitución, Colombia es un Estado social de derecho organizado en forma de","opciones":{"A":"república federal, con estados autónomos.","B":"república unitaria, descentralizada, con autonomía de sus entidades territoriales.","C":"república unitaria y centralizada, sin autonomía territorial.","D":"confederación de departamentos con autonomía legislativa."},"correcta":"B","explicacion":"El artículo 1 define a Colombia como Estado social de derecho, organizado en forma de república unitaria, descentralizada, con autonomía de sus entidades territoriales, democrática, participativa y pluralista. No es federal ni confederada, y la descentralización excluye el centralismo absoluto.","dificultad":1},{"id":"cons-0002","eje":"constitucional","nucleo":"general","origen":"estilo","fuente":"Constitución Política, art. 4","enunciado":"Una ordenanza departamental contradice de manera directa un artículo de la Constitución. Según el artículo 4 de la Carta, la autoridad que debe aplicarla en un caso concreto","opciones":{"A":"debe aplicar la ordenanza mientras no sea anulada.","B":"debe consultar previamente al Consejo de Estado.","C":"debe suspender la actuación hasta que la Corte Constitucional se pronuncie.","D":"debe aplicar de preferencia las disposiciones constitucionales."},"correcta":"D","explicacion":"El artículo 4 establece que la Constitución es norma de normas y que, en caso de incompatibilidad con la ley u otra norma jurídica, se aplicarán las disposiciones constitucionales. Es la excepción de inconstitucionalidad, que no exige consulta previa ni suspensión.","dificultad":2},{"id":"cons-0003","eje":"constitucional","nucleo":"general","origen":"estilo","fuente":"Constitución Política, art. 6","enunciado":"Según el artículo 6 de la Constitución, los servidores públicos son responsables","opciones":{"A":"por infringir la Constitución y las leyes y por omisión o extralimitación en el ejercicio de sus funciones.","B":"exclusivamente ante sus superiores jerárquicos.","C":"solo por infringir la Constitución y las leyes.","D":"únicamente por las omisiones que causen daño patrimonial."},"correcta":"A","explicacion":"El artículo 6 señala que los particulares solo responden por infringir la Constitución y las leyes, mientras que los servidores públicos responden por la misma causa y además por omisión o extralimitación en el ejercicio de sus funciones.","dificultad":1},{"id":"cons-0004","eje":"constitucional","nucleo":"general","origen":"estilo","fuente":"Constitución Política, art. 86; Decreto 2591 de 1991, art. 6","enunciado":"Un ciudadano interpone tutela para obtener el pago de una suma de dinero derivada de un contrato con una entidad, aunque tiene a su alcance la acción contractual y no existe perjuicio irremediable. El juez debe","opciones":{"A":"tramitarla como acción de cumplimiento.","B":"remitirla a la Procuraduría para conciliación.","C":"declararla improcedente, por existir otro medio de defensa judicial idóneo.","D":"concederla, porque toda deuda estatal afecta derechos fundamentales."},"correcta":"C","explicacion":"La tutela es subsidiaria: según el artículo 86 de la Constitución y el artículo 6 del Decreto 2591 de 1991, solo procede cuando el afectado no dispone de otro medio de defensa judicial, salvo como mecanismo transitorio para evitar un perjuicio irremediable.","dificultad":2},{"id":"cons-0005","eje":"constitucional","nucleo":"general","origen":"estilo","fuente":"Constitución Política, art. 86","enunciado":"El juez debe resolver una acción de tutela en un término máximo de","opciones":{"A":"cinco días.","B":"quince días hábiles.","C":"treinta días.","D":"diez días."},"correcta":"D","explicacion":"El artículo 86 de la Constitución dispone que en ningún caso podrán transcurrir más de diez días entre la solicitud de tutela y su resolución. El fallo puede impugnarse ante el juez competente y se remite a la Corte Constitucional para eventual revisión.","dificultad":1},{"id":"cons-0006","eje":"constitucional","nucleo":"general","origen":"estilo","fuente":"Constitución Política, art. 87; Ley 393 de 1997","enunciado":"Un municipio se niega a aplicar una ley que le ordena destinar un porcentaje de sus ingresos a un fondo específico. El mecanismo constitucional para exigir el cumplimiento de esa ley es","opciones":{"A":"la acción de tutela.","B":"la acción de cumplimiento.","C":"la acción popular.","D":"la acción de nulidad por inconstitucionalidad."},"correcta":"B","explicacion":"El artículo 87 de la Constitución, desarrollado por la Ley 393 de 1997, consagra la acción de cumplimiento para que toda persona exija ante la autoridad judicial el cumplimiento de una ley o un acto administrativo. La tutela protege derechos fundamentales y la popular, derechos colectivos.","dificultad":1},{"id":"cons-0007","eje":"constitucional","nucleo":"general","origen":"estilo","fuente":"Constitución Política, art. 88; Ley 472 de 1998","enunciado":"Los habitantes de un barrio quieren proteger el espacio público invadido por construcciones ilegales. La acción que procede es","opciones":{"A":"la acción de tutela de cada propietario.","B":"la acción de cumplimiento contra los invasores.","C":"la acción popular, para la protección de derechos e intereses colectivos.","D":"la acción de grupo, para obtener una indemnización individual."},"correcta":"C","explicacion":"El artículo 88 de la Constitución y la Ley 472 de 1998 regulan la acción popular para proteger derechos e intereses colectivos como el espacio público. La acción de grupo busca indemnizar perjuicios a un número plural de personas, y la tutela protege derechos fundamentales.","dificultad":1},{"id":"cons-0008","eje":"constitucional","nucleo":"general","origen":"estilo","fuente":"Constitución Política, art. 93","enunciado":"Los tratados y convenios internacionales ratificados por el Congreso que reconocen derechos humanos y prohíben su limitación en estados de excepción","opciones":{"A":"prevalecen en el orden interno y hacen parte del bloque de constitucionalidad.","B":"tienen rango inferior a las leyes estatutarias.","C":"tienen rango de ley ordinaria.","D":"solo obligan si son reglamentados por decreto."},"correcta":"A","explicacion":"El artículo 93 dispone que esos tratados prevalecen en el orden interno y que los derechos y deberes se interpretan de conformidad con ellos. La Corte Constitucional ha precisado que integran el bloque de constitucionalidad.","dificultad":2},{"id":"cons-0009","eje":"constitucional","nucleo":"general","origen":"estilo","fuente":"Constitución Política, art. 23; Ley 1755 de 2015","enunciado":"El derecho de petición, según la Constitución, permite presentar peticiones respetuosas a las autoridades","opciones":{"A":"siempre que se presenten por escrito y con abogado.","B":"únicamente para solicitar documentos.","C":"por motivos de interés general o particular y obtener pronta resolución.","D":"solo por motivos de interés particular."},"correcta":"C","explicacion":"El artículo 23 de la Constitución consagra el derecho a presentar peticiones respetuosas por motivos de interés general o particular y a obtener pronta resolución. La Ley 1755 de 2015 permite presentarlas verbalmente o por escrito, sin necesidad de abogado.","dificultad":1},{"id":"cons-0010","eje":"constitucional","nucleo":"general","origen":"estilo","fuente":"Constitución Política, art. 113","enunciado":"Son ramas del poder público según el artículo 113 de la Constitución","opciones":{"A":"la legislativa, la ejecutiva y la judicial.","B":"la ejecutiva, la judicial y la electoral.","C":"la legislativa, la ejecutiva y el Ministerio Público.","D":"la legislativa, la ejecutiva, la judicial y la de control."},"correcta":"A","explicacion":"El artículo 113 señala como ramas del poder público la legislativa, la ejecutiva y la judicial; además existen otros órganos autónomos e independientes, como los de control (Ministerio Público y Contraloría) y la organización electoral, que no son ramas.","dificultad":1},{"id":"cons-0011","eje":"constitucional","nucleo":"general","origen":"estilo","fuente":"Constitución Política, art. 117","enunciado":"Son órganos de control según la Constitución","opciones":{"A":"la Contraloría y la Auditoría General únicamente.","B":"el Ministerio Público y la Contraloría General de la República.","C":"la Fiscalía General y la Procuraduría.","D":"la Registraduría y el Consejo Nacional Electoral."},"correcta":"B","explicacion":"El artículo 117 establece que el Ministerio Público y la Contraloría General de la República son órganos de control. La Fiscalía pertenece a la Rama Judicial y la Registraduría y el CNE integran la organización electoral.","dificultad":1},{"id":"cons-0012","eje":"constitucional","nucleo":"general","origen":"estilo","fuente":"Constitución Política, art. 121","enunciado":"Una autoridad territorial expide un acto sobre una materia que ninguna norma le atribuye. Según la Constitución","opciones":{"A":"las autoridades pueden ejercer funciones implícitas si son útiles al interés general.","B":"basta que el acto no esté prohibido expresamente.","C":"el acto es válido si lo ratifica el concejo municipal.","D":"ninguna autoridad del Estado podrá ejercer funciones distintas de las que le atribuyen la Constitución y la ley."},"correcta":"D","explicacion":"El artículo 121 consagra el principio de legalidad de la función pública: ninguna autoridad podrá ejercer funciones distintas de las que le atribuyen la Constitución y la ley. A diferencia de los particulares, el servidor solo puede hacer lo que la norma le permite.","dificultad":1},{"id":"cons-0013","eje":"constitucional","nucleo":"general","origen":"estilo","fuente":"Constitución Política, art. 122","enunciado":"Antes de tomar posesión de un cargo público, todo servidor debe","opciones":{"A":"prestar juramento de cumplir y defender la Constitución y desempeñar los deberes que le incumben.","B":"obtener aprobación del Congreso.","C":"inscribirse en la carrera administrativa.","D":"presentar únicamente el certificado de antecedentes fiscales."},"correcta":"A","explicacion":"El artículo 122 dispone que ningún servidor entrará a ejercer su cargo sin prestar juramento de cumplir y defender la Constitución y desempeñar los deberes que le incumben; también exige declarar bajo juramento el monto de sus bienes y rentas cuando la ley lo ordene.","dificultad":1},{"id":"cons-0014","eje":"constitucional","nucleo":"general","origen":"estilo","fuente":"Constitución Política, art. 125","enunciado":"Según el artículo 125 de la Constitución, los empleos en los órganos y entidades del Estado","opciones":{"A":"son de período fijo de cuatro años.","B":"se proveen por sorteo entre los aspirantes que cumplan requisitos.","C":"son de carrera, salvo los de elección popular, libre nombramiento y remoción, trabajadores oficiales y los demás que determine la ley.","D":"son de libre nombramiento, salvo los del nivel técnico."},"correcta":"C","explicacion":"El artículo 125 establece la carrera como regla general y enumera las excepciones: elección popular, libre nombramiento y remoción, trabajadores oficiales y los demás que determine la ley. El ingreso y ascenso en carrera se hacen por méritos.","dificultad":1},{"id":"cons-0015","eje":"constitucional","nucleo":"general","origen":"estilo","fuente":"Constitución Política, art. 125","enunciado":"Según la Constitución, el retiro de un empleado de carrera se produce","opciones":{"A":"por decisión discrecional del nominador.","B":"por cambio de gobierno.","C":"solo por pensión de jubilación.","D":"por calificación no satisfactoria del desempeño, violación del régimen disciplinario y las demás causales previstas en la Constitución o la ley."},"correcta":"D","explicacion":"El artículo 125 dispone que el retiro se hará por calificación no satisfactoria, violación del régimen disciplinario y demás causales previstas en la Constitución o la ley, y que la filiación política no puede determinar nombramiento, ascenso ni remoción.","dificultad":1},{"id":"cons-0016","eje":"constitucional","nucleo":"general","origen":"estilo","fuente":"Constitución Política, art. 127","enunciado":"Un profesional universitario de carrera de una alcaldía quiere asistir a la reunión de un partido político y votar en las elecciones. Según el artículo 127 de la Constitución","opciones":{"A":"puede participar libremente en campañas si lo hace fuera de la jornada laboral.","B":"puede votar, pero no puede tomar parte en las actividades de los partidos ni en las controversias políticas, salvo lo que autorice la ley estatutaria.","C":"puede participar en política solo si pide licencia no remunerada.","D":"tiene prohibido incluso votar mientras sea servidor público."},"correcta":"B","explicacion":"El artículo 127 prohíbe a los empleados del Estado que se desempeñen en la Rama Judicial, en órganos electorales, de control y de seguridad, tomar parte en actividades de partidos; a los demás empleados solo se les permite participar en las condiciones que señale la ley estatutaria. El voto es un derecho que conservan.","dificultad":3},{"id":"cons-0017","eje":"constitucional","nucleo":"general","origen":"estilo","fuente":"Constitución Política, art. 128","enunciado":"Una servidora pública de planta es contratada además como docente de cátedra en una universidad pública. Según el artículo 128 de la Constitución","opciones":{"A":"la prohibición solo cobija a los empleados de carrera.","B":"nadie puede desempeñar simultáneamente más de un empleo público ni recibir más de una asignación del tesoro público, salvo los casos expresamente determinados por la ley.","C":"siempre puede recibir dos asignaciones si las jornadas no coinciden.","D":"la prohibición solo aplica a cargos de elección popular."},"correcta":"B","explicacion":"El artículo 128 prohíbe desempeñar simultáneamente más de un empleo público o recibir más de una asignación del tesoro, salvo los casos que la ley determine. La ley contempla excepciones, como ciertas horas de cátedra, por lo que la conducta depende de que encaje en ellas.","dificultad":2},{"id":"cons-0018","eje":"constitucional","nucleo":"general","origen":"estilo","fuente":"Constitución Política, art. 209","enunciado":"Según el artículo 209 de la Constitución, la función administrativa está al servicio de los intereses generales y se desarrolla con fundamento en los principios de","opciones":{"A":"igualdad, moralidad, eficacia, economía, celeridad, imparcialidad y publicidad.","B":"legalidad, tipicidad, culpabilidad y proporcionalidad.","C":"oralidad, concentración e inmediación.","D":"libre competencia, rentabilidad y autonomía de la voluntad."},"correcta":"A","explicacion":"El artículo 209 enumera los principios de la función administrativa: igualdad, moralidad, eficacia, economía, celeridad, imparcialidad y publicidad, mediante la descentralización, delegación y desconcentración. Los demás son principios del derecho sancionador, del proceso oral y del mercado.","dificultad":1},{"id":"cons-0019","eje":"constitucional","nucleo":"general","origen":"estilo","fuente":"Constitución Política, art. 211","enunciado":"Un ministro delega en un viceministro la firma de ciertos contratos. Según el artículo 211 de la Constitución, la delegación","opciones":{"A":"requiere autorización previa del Congreso en cada caso.","B":"mantiene la responsabilidad exclusiva del delegante.","C":"impide al delegante revisar los actos del delegatario.","D":"exime de responsabilidad al delegante, la cual corresponde exclusivamente al delegatario, cuyos actos podrá reformar o revocar aquel."},"correcta":"D","explicacion":"El artículo 211 dispone que la delegación exime de responsabilidad al delegante, que corresponde exclusivamente al delegatario, y que el delegante puede reformar o revocar los actos de este, reasumiendo la responsabilidad. La jurisprudencia ha matizado que el delegante conserva deberes de control.","dificultad":2},{"id":"cons-0020","eje":"constitucional","nucleo":"general","origen":"estilo","fuente":"Constitución Política, art. 241","enunciado":"A la Corte Constitucional le corresponde decidir sobre las demandas de inconstitucionalidad que promuevan los ciudadanos contra","opciones":{"A":"los actos administrativos de carácter particular.","B":"los decretos reglamentarios ordinarios.","C":"las leyes, tanto por su contenido material como por vicios de procedimiento en su formación.","D":"las resoluciones de los ministerios."},"correcta":"C","explicacion":"El numeral 4 del artículo 241 asigna a la Corte decidir sobre las demandas ciudadanas contra las leyes, por vicios de contenido o de procedimiento. Los decretos reglamentarios y actos administrativos se controlan ante el Consejo de Estado o la jurisdicción contencioso administrativa.","dificultad":2},{"id":"cons-0021","eje":"constitucional","nucleo":"general","origen":"estilo","fuente":"Constitución Política, art. 237","enunciado":"Para controvertir un decreto del Gobierno Nacional cuya competencia no corresponda a la Corte Constitucional, el ciudadano debe acudir a","opciones":{"A":"la Corte Suprema de Justicia, en casación.","B":"la Procuraduría General, mediante queja.","C":"el Congreso, mediante moción de censura.","D":"el Consejo de Estado, mediante acción de nulidad por inconstitucionalidad."},"correcta":"D","explicacion":"El numeral 2 del artículo 237 atribuye al Consejo de Estado conocer de las acciones de nulidad por inconstitucionalidad de los decretos del Gobierno cuya competencia no corresponda a la Corte Constitucional.","dificultad":2},{"id":"cons-0022","eje":"constitucional","nucleo":"general","origen":"estilo","fuente":"Constitución Política, art. 152","enunciado":"Debe tramitarse como ley estatutaria la regulación de","opciones":{"A":"los derechos y deberes fundamentales y los procedimientos y recursos para su protección.","B":"el presupuesto general de la Nación.","C":"el régimen de contratación estatal.","D":"los códigos en todas las ramas de la legislación."},"correcta":"A","explicacion":"El artículo 152 reserva a la ley estatutaria, entre otras materias, los derechos y deberes fundamentales y sus procedimientos y recursos de protección, la administración de justicia, los partidos, los mecanismos de participación y los estados de excepción. El presupuesto es materia orgánica y los códigos son leyes ordinarias.","dificultad":2},{"id":"cons-0023","eje":"constitucional","nucleo":"general","origen":"estilo","fuente":"Constitución Política, arts. 103 y 104","enunciado":"Son mecanismos de participación del pueblo en ejercicio de su soberanía, según el artículo 103 de la Constitución","opciones":{"A":"el derecho de petición y la queja disciplinaria.","B":"la acción de tutela, la acción popular y la acción de grupo.","C":"el voto, el plebiscito, el referendo, la consulta popular, el cabildo abierto, la iniciativa legislativa y la revocatoria del mandato.","D":"la moción de censura y la pérdida de investidura."},"correcta":"C","explicacion":"El artículo 103 enumera los mecanismos de participación ciudadana: voto, plebiscito, referendo, consulta popular, cabildo abierto, iniciativa legislativa y revocatoria del mandato. Las acciones judiciales y los mecanismos de control político son instituciones distintas.","dificultad":1},{"id":"cons-0024","eje":"constitucional","nucleo":"general","origen":"estilo","fuente":"Constitución Política, art. 29","enunciado":"Según el artículo 29 de la Constitución, la prueba obtenida con violación del debido proceso","opciones":{"A":"es válida si resulta determinante para la decisión.","B":"es nula de pleno derecho.","C":"solo puede valorarse en procesos disciplinarios.","D":"se convalida si el afectado no la objeta en cinco días."},"correcta":"B","explicacion":"El último inciso del artículo 29 dispone que es nula, de pleno derecho, la prueba obtenida con violación del debido proceso. Esta garantía aplica a toda clase de actuaciones judiciales y administrativas, incluidas las disciplinarias.","dificultad":1},{"id":"cons-0025","eje":"constitucional","nucleo":"general","origen":"estilo","fuente":"Constitución Política, art. 90","enunciado":"El Estado es condenado a reparar un daño antijurídico causado por la conducta dolosa de un servidor. Según el artículo 90 de la Constitución, el Estado","opciones":{"A":"solo puede pedir sanción disciplinaria.","B":"debe esperar a que el servidor sea condenado penalmente para pagar.","C":"deberá repetir contra el servidor.","D":"no puede recuperar lo pagado."},"correcta":"C","explicacion":"El artículo 90 establece que el Estado responde patrimonialmente por los daños antijurídicos imputables a la acción u omisión de las autoridades y que, si es condenado por un daño consecuencia de la conducta dolosa o gravemente culposa de un agente, deberá repetir contra este.","dificultad":1},{"id":"cons-0026","eje":"constitucional","nucleo":"general","origen":"estilo","fuente":"Constitución Política, art. 13","enunciado":"Una entidad adopta medidas de acceso preferente a sus programas para personas en situación de discapacidad. Según el artículo 13 de la Constitución, estas medidas","opciones":{"A":"son compatibles con la igualdad, porque el Estado debe adoptar medidas a favor de grupos discriminados o marginados.","B":"solo son válidas si las ordena un juez de tutela.","C":"requieren una reforma constitucional previa.","D":"violan la igualdad formal y deben suprimirse."},"correcta":"A","explicacion":"El artículo 13 consagra la igualdad material: el Estado promoverá las condiciones para que la igualdad sea real y efectiva y adoptará medidas en favor de grupos discriminados o marginados, protegiendo especialmente a quienes están en circunstancia de debilidad manifiesta.","dificultad":1},{"id":"cons-0027","eje":"constitucional","nucleo":"general","origen":"estilo","fuente":"Constitución Política, arts. 212 a 215","enunciado":"Los estados de excepción previstos en la Constitución son","opciones":{"A":"guerra exterior y estado de sitio.","B":"guerra exterior, conmoción interior y emergencia económica, social y ecológica.","C":"estado de sitio, toque de queda y ley marcial.","D":"emergencia sanitaria, calamidad pública y conmoción interior."},"correcta":"B","explicacion":"Los artículos 212, 213 y 215 regulan los estados de guerra exterior, conmoción interior y emergencia económica, social y ecológica. El estado de sitio fue una figura de la Constitución de 1886.","dificultad":1},{"id":"cons-0028","eje":"constitucional","nucleo":"general","origen":"estilo","fuente":"Constitución Política, art. 214","enunciado":"Durante los estados de excepción","opciones":{"A":"se suspende el funcionamiento del Congreso.","B":"los decretos legislativos no tienen control de constitucionalidad.","C":"el Gobierno puede suspender la acción de tutela.","D":"no podrán suspenderse los derechos humanos ni las libertades fundamentales y se respetarán las reglas del derecho internacional humanitario."},"correcta":"D","explicacion":"El artículo 214 dispone que en los estados de excepción no podrán suspenderse los derechos humanos ni las libertades fundamentales, se respetarán las reglas del DIH, no se interrumpirá el funcionamiento de las ramas del poder y la Corte Constitucional ejercerá control automático sobre los decretos legislativos.","dificultad":2},{"id":"cont-0001","eje":"contratacion","nucleo":"general","origen":"estilo","fuente":"Ley 1150 de 2007, art. 2","enunciado":"Según la Ley 1150 de 2007, la regla general para escoger al contratista es","opciones":{"A":"la selección abreviada en todos los casos.","B":"la contratación directa, salvo que el valor supere la menor cuantía.","C":"la licitación pública, salvo los casos de selección abreviada, concurso de méritos, contratación directa y mínima cuantía.","D":"el concurso de méritos para todo tipo de contrato."},"correcta":"C","explicacion":"El numeral 1 del artículo 2 de la Ley 1150 de 2007 establece que la escogencia del contratista se efectuará por regla general a través de licitación pública, con las excepciones de las demás modalidades previstas en la ley.","dificultad":1},{"id":"cont-0002","eje":"contratacion","nucleo":"general","origen":"estilo","fuente":"Ley 1150 de 2007, art. 2, num. 3","enunciado":"Una entidad necesita contratar los estudios técnicos y diseños de un puente con una firma consultora. La modalidad de selección aplicable es","opciones":{"A":"la contratación directa por ausencia de pluralidad de oferentes.","B":"la mínima cuantía.","C":"la selección abreviada por subasta inversa.","D":"el concurso de méritos."},"correcta":"D","explicacion":"El numeral 3 del artículo 2 de la Ley 1150 de 2007 dispone que la selección de consultores, como los de estudios y diseños, se hace mediante concurso de méritos, en el que se evalúa la calidad técnica y la experiencia, no el precio.","dificultad":1},{"id":"cont-0003","eje":"contratacion","nucleo":"general","origen":"estilo","fuente":"Ley 1150 de 2007, art. 2, num. 2, lit. a","enunciado":"Una gobernación necesita adquirir papelería y equipos de cómputo estándar, de características técnicas uniformes y común utilización. La modalidad que corresponde es","opciones":{"A":"la licitación pública obligatoria por el tipo de bien.","B":"la selección abreviada.","C":"el concurso de méritos.","D":"la contratación directa."},"correcta":"B","explicacion":"El literal a del numeral 2 del artículo 2 de la Ley 1150 de 2007 prevé la selección abreviada para la adquisición de bienes y servicios de características técnicas uniformes y de común utilización, mediante subasta inversa, acuerdo marco de precios o bolsa de productos.","dificultad":1},{"id":"cont-0004","eje":"contratacion","nucleo":"general","origen":"estilo","fuente":"Ley 1150 de 2007, art. 2, num. 4, lit. h","enunciado":"Un municipio requiere contratar a un abogado para que lo asesore en un asunto jurídico puntual, por un período corto. Puede hacerlo mediante","opciones":{"A":"contratación directa, por tratarse de prestación de servicios profesionales.","B":"concurso de méritos abierto.","C":"subasta inversa.","D":"licitación pública obligatoria."},"correcta":"A","explicacion":"El literal h del numeral 4 del artículo 2 de la Ley 1150 de 2007 permite la contratación directa para la prestación de servicios profesionales y de apoyo a la gestión, o para trabajos artísticos que solo puedan encomendarse a determinadas personas naturales.","dificultad":1},{"id":"cont-0005","eje":"contratacion","nucleo":"general","origen":"estilo","fuente":"Ley 1150 de 2007, art. 2, num. 4; Ley 80 de 1993, art. 42","enunciado":"Una avalancha destruye el acueducto de un municipio y se requiere restablecer el servicio de inmediato. El alcalde puede contratar directamente invocando","opciones":{"A":"la ausencia de pluralidad de oferentes.","B":"la urgencia manifiesta.","C":"la mínima cuantía, sin importar el valor.","D":"el contrato interadministrativo con cualquier particular."},"correcta":"B","explicacion":"La urgencia manifiesta (art. 42 de la Ley 80 de 1993) procede ante calamidades, desastres o situaciones de fuerza mayor que exigen actuar de inmediato y es causal de contratación directa según el artículo 2, numeral 4, de la Ley 1150 de 2007.","dificultad":1},{"id":"cont-0006","eje":"contratacion","nucleo":"general","origen":"estilo","fuente":"Ley 80 de 1993, art. 43","enunciado":"Inmediatamente después de celebrar los contratos originados en una urgencia manifiesta, la entidad debe enviar el contrato, el acto que la declaró y sus antecedentes a","opciones":{"A":"la Agencia Colombia Compra Eficiente, para su aprobación.","B":"el concejo municipal, para su ratificación.","C":"el Consejo de Estado, para su revisión previa.","D":"el funcionario u organismo que ejerza el control fiscal en la entidad."},"correcta":"D","explicacion":"El artículo 43 de la Ley 80 de 1993 ordena enviar los contratos, el acto que declaró la urgencia y los antecedentes al organismo de control fiscal, que debe pronunciarse sobre los hechos y circunstancias que la determinaron.","dificultad":2},{"id":"cont-0007","eje":"contratacion","nucleo":"general","origen":"estilo","fuente":"Ley 1474 de 2011, art. 94 (adiciona art. 2 de Ley 1150 de 2007)","enunciado":"La modalidad de mínima cuantía se aplica a la contratación cuyo valor","opciones":{"A":"no exceda el diez por ciento de la menor cuantía de la entidad, independientemente de su objeto.","B":"no exceda la mitad de la menor cuantía, solo para obras.","C":"no exceda cien salarios mínimos en todas las entidades.","D":"sea inferior al presupuesto anual de inversión."},"correcta":"A","explicacion":"El artículo 94 de la Ley 1474 de 2011 creó la modalidad de mínima cuantía para contratos cuyo valor no exceda el diez por ciento de la menor cuantía de la entidad, independientemente de su objeto, con un procedimiento simplificado.","dificultad":2},{"id":"cont-0008","eje":"contratacion","nucleo":"general","origen":"estilo","fuente":"Ley 80 de 1993, art. 14","enunciado":"Son cláusulas excepcionales al derecho común en los contratos estatales","opciones":{"A":"la cláusula penal y la de confidencialidad.","B":"la indexación y los intereses moratorios.","C":"la interpretación, modificación y terminación unilaterales, el sometimiento a las leyes nacionales, la caducidad y la reversión.","D":"el arbitramento y la amigable composición."},"correcta":"C","explicacion":"El artículo 14 de la Ley 80 de 1993 enumera como cláusulas excepcionales la interpretación, modificación y terminación unilaterales, el sometimiento a las leyes nacionales, la caducidad y, en ciertos contratos, la reversión.","dificultad":1},{"id":"cont-0009","eje":"contratacion","nucleo":"general","origen":"estilo","fuente":"Ley 80 de 1993, art. 18","enunciado":"Un contratista de obra abandona los trabajos y su incumplimiento afecta de manera grave y directa la ejecución, con evidencia de que puede conducir a su paralización. La entidad puede","opciones":{"A":"ceder el contrato a otro contratista sin acto alguno.","B":"únicamente demandar al contratista ante el juez.","C":"declarar la caducidad del contrato mediante acto motivado y ordenar su liquidación.","D":"pagar el saldo y terminar de mutuo acuerdo."},"correcta":"C","explicacion":"El artículo 18 de la Ley 80 de 1993 faculta a la entidad para declarar la caducidad, mediante acto motivado, cuando hay incumplimiento que afecta de manera grave y directa la ejecución y evidencia que puede conducir a su paralización, y ordenar la liquidación en el estado en que se encuentre.","dificultad":2},{"id":"cont-0010","eje":"contratacion","nucleo":"general","origen":"estilo","fuente":"Ley 80 de 1993, art. 8, num. 1, lit. c","enunciado":"A un contratista le declararon la caducidad de un contrato estatal. En cuanto a nuevos contratos con el Estado, queda inhabilitado por","opciones":{"A":"un año contado desde la notificación.","B":"diez años contados desde la firma del contrato.","C":"dos años contados desde la liquidación.","D":"cinco años contados desde la ejecutoria del acto que la declaró."},"correcta":"D","explicacion":"El literal c del numeral 1 del artículo 8 de la Ley 80 de 1993 inhabilita a quienes dieron lugar a la declaratoria de caducidad, por cinco años contados desde la fecha de ejecutoria del acto que la declaró.","dificultad":2},{"id":"cont-0011","eje":"contratacion","nucleo":"general","origen":"estilo","fuente":"Ley 80 de 1993, art. 40, parágrafo","enunciado":"Un contrato de obra se pactó por 1.000 SMMLV y la entidad requiere adicionarlo. Según la Ley 80 de 1993, la adición no puede superar","opciones":{"A":"el valor que autorice el contratista.","B":"el cincuenta por ciento de su valor inicial, expresado en salarios mínimos legales mensuales.","C":"el cien por ciento del valor inicial.","D":"el veinte por ciento del valor inicial."},"correcta":"B","explicacion":"El parágrafo del artículo 40 de la Ley 80 de 1993 dispone que los contratos no podrán adicionarse en más del cincuenta por ciento de su valor inicial, expresado en salarios mínimos legales mensuales.","dificultad":2},{"id":"cont-0012","eje":"contratacion","nucleo":"general","origen":"estilo","fuente":"Ley 1150 de 2007, art. 11","enunciado":"Terminado un contrato que requiere liquidación, si no se pactó plazo, la liquidación de mutuo acuerdo debe hacerse dentro de los","opciones":{"A":"cuatro meses siguientes a la expiración del término de ejecución.","B":"seis meses siguientes a la última factura.","C":"dos años siguientes a la firma del contrato.","D":"diez días hábiles siguientes a la entrega."},"correcta":"A","explicacion":"El artículo 11 de la Ley 1150 de 2007 dispone que la liquidación de mutuo acuerdo se hará en el término pactado o, en su defecto, dentro de los cuatro meses siguientes a la expiración del plazo de ejecución; si no se logra, la entidad puede liquidar unilateralmente dentro de los dos meses siguientes.","dificultad":2},{"id":"cont-0013","eje":"contratacion","nucleo":"general","origen":"estilo","fuente":"Ley 1150 de 2007, art. 11","enunciado":"Vencidos los plazos de liquidación bilateral y unilateral sin que el contrato se haya liquidado, la liquidación","opciones":{"A":"solo puede hacerla la Contraloría.","B":"debe hacerse dentro de los treinta días siguientes, so pena de nulidad.","C":"ya no es posible y el contrato queda cerrado sin liquidar.","D":"podrá realizarse en cualquier tiempo dentro de los dos años siguientes, de mutuo acuerdo o unilateralmente."},"correcta":"D","explicacion":"El artículo 11 de la Ley 1150 de 2007 permite liquidar en cualquier tiempo dentro de los dos años siguientes al vencimiento de los términos legales, de mutuo acuerdo o unilateralmente, sin perjuicio de la liquidación judicial.","dificultad":3},{"id":"cont-0014","eje":"contratacion","nucleo":"general","origen":"estilo","fuente":"Ley 1150 de 2007, art. 5","enunciado":"En una licitación, la entidad otorga puntaje adicional a los proponentes con mayor patrimonio, que es un requisito de capacidad financiera. Según la Ley 1150 de 2007","opciones":{"A":"es válido solo en obras públicas.","B":"los requisitos habilitantes, como la capacidad financiera, son objeto de verificación de cumplimiento y no otorgan puntaje.","C":"es obligatorio otorgar puntaje a la capacidad financiera.","D":"es válido porque mejora la selección objetiva."},"correcta":"B","explicacion":"El numeral 1 del artículo 5 de la Ley 1150 de 2007 dispone que la capacidad jurídica, la experiencia, la capacidad financiera y de organización son requisitos habilitantes que se verifican como cumple o no cumple y no otorgan puntaje.","dificultad":2},{"id":"cont-0015","eje":"contratacion","nucleo":"general","origen":"estilo","fuente":"Ley 1150 de 2007, art. 5, num. 4","enunciado":"En el concurso de méritos para seleccionar consultores, el precio","opciones":{"A":"define el orden de elegibilidad en caso de empate técnico.","B":"es el único factor de evaluación.","C":"no puede incluirse como factor de escogencia.","D":"vale como mínimo el cincuenta por ciento del puntaje."},"correcta":"C","explicacion":"El numeral 4 del artículo 5 de la Ley 1150 de 2007 establece que en la selección de consultores la entidad no puede incluir el precio como factor de escogencia; se evalúan la experiencia, la formación y la calidad técnica.","dificultad":2},{"id":"cont-0016","eje":"contratacion","nucleo":"general","origen":"estilo","fuente":"Ley 1150 de 2007, art. 6","enunciado":"Las personas naturales o jurídicas que aspiren a celebrar contratos con las entidades estatales deben, por regla general, inscribirse en","opciones":{"A":"el Registro Único de Proponentes que llevan las cámaras de comercio.","B":"el registro nacional de abogados.","C":"el SIGEP administrado por la Función Pública.","D":"el registro de la Procuraduría General."},"correcta":"A","explicacion":"El artículo 6 de la Ley 1150 de 2007 exige inscribirse en el Registro Único de Proponentes, que llevan las cámaras de comercio, salvo excepciones como la contratación directa, la mínima cuantía o los bienes de características técnicas uniformes, entre otras.","dificultad":1},{"id":"cont-0017","eje":"contratacion","nucleo":"general","origen":"estilo","fuente":"Ley 1150 de 2007, art. 23 (modifica art. 41 de Ley 80 de 1993)","enunciado":"Un contrato estatal fue firmado por las partes. Para iniciar su ejecución se requiere","opciones":{"A":"la aprobación de la garantía y la existencia de las disponibilidades presupuestales correspondientes.","B":"la autorización de la Contraloría.","C":"el pago del anticipo pactado.","D":"la publicación en el Diario Oficial y el registro ante notario."},"correcta":"A","explicacion":"El artículo 41 de la Ley 80 de 1993, modificado por el artículo 23 de la Ley 1150 de 2007, dispone que el contrato se perfecciona con el acuerdo sobre objeto y contraprestación elevado a escrito, y que su ejecución requiere la aprobación de la garantía y el registro presupuestal.","dificultad":2},{"id":"cont-0018","eje":"contratacion","nucleo":"general","origen":"estilo","fuente":"Ley 80 de 1993, art. 44","enunciado":"Es causal de nulidad absoluta del contrato estatal","opciones":{"A":"que el contratista incumpla una obligación menor.","B":"celebrarlo con personas incursas en causales de inhabilidad o incompatibilidad previstas en la Constitución y la ley.","C":"que la entidad pague con retraso.","D":"que la obra se termine antes del plazo."},"correcta":"B","explicacion":"El artículo 44 de la Ley 80 de 1993 establece como causales de nulidad absoluta celebrar el contrato con personas inhabilitadas o incompatibles, contra expresa prohibición, con abuso o desviación de poder, cuando se declaren nulos los actos en que se funda o con desconocimiento de reglas sobre cláusulas excepcionales.","dificultad":1},{"id":"cont-0019","eje":"contratacion","nucleo":"general","origen":"estilo","fuente":"Ley 1474 de 2011, art. 83","enunciado":"Una entidad debe vigilar un contrato de obra de gran complejidad técnica. Según el Estatuto Anticorrupción, el seguimiento técnico especializado","opciones":{"A":"debe hacerlo siempre el ordenador del gasto personalmente.","B":"corresponde a la Procuraduría por ser una obra de gran cuantía.","C":"lo realiza el mismo contratista mediante autocontrol.","D":"se hace mediante interventoría contratada con una persona natural o jurídica, cuando el seguimiento suponga conocimiento especializado o la complejidad lo justifique."},"correcta":"D","explicacion":"El artículo 83 de la Ley 1474 de 2011 distingue la supervisión, que ejerce la entidad con sus funcionarios cuando no se requieren conocimientos especializados, y la interventoría, contratada con una persona natural o jurídica cuando el seguimiento supone conocimiento especializado o la complejidad o extensión del contrato lo justifiquen.","dificultad":2},{"id":"cont-0020","eje":"contratacion","nucleo":"general","origen":"estilo","fuente":"Ley 1474 de 2011, art. 86","enunciado":"Una entidad pretende imponer una multa a un contratista por retraso. Según la Ley 1474 de 2011, debe","opciones":{"A":"pedir autorización al juez administrativo.","B":"publicar la sanción antes de notificar al contratista.","C":"citarlo a una audiencia en la que se le presenten los hechos, las cláusulas afectadas y las consecuencias, para que ejerza su defensa.","D":"descontar la multa de la factura sin trámite."},"correcta":"C","explicacion":"El artículo 86 de la Ley 1474 de 2011 establece un procedimiento en audiencia para imponer multas, sanciones y declaratorias de incumplimiento, con citación al contratista y a su garante, garantizando el debido proceso.","dificultad":2},{"id":"cont-0021","eje":"contratacion","nucleo":"general","origen":"estilo","fuente":"Ley 80 de 1993, art. 24","enunciado":"El principio de la contratación estatal según el cual los procesos de selección deben permitir a los interesados conocer y controvertir los informes, conceptos y decisiones, y en virtud del cual los actos deben motivarse, es el de","opciones":{"A":"transparencia.","B":"responsabilidad.","C":"ecuación contractual.","D":"economía."},"correcta":"A","explicacion":"El artículo 24 de la Ley 80 de 1993 desarrolla el principio de transparencia: publicidad de las actuaciones, posibilidad de controvertir informes y decisiones, pliegos con reglas objetivas y motivación de los actos.","dificultad":1},{"id":"cont-0022","eje":"contratacion","nucleo":"general","origen":"estilo","fuente":"Ley 80 de 1993, art. 27","enunciado":"Durante la ejecución de un contrato, un hecho imprevisible ajeno a las partes encarece de forma extraordinaria los insumos y rompe el equilibrio económico. Según la Ley 80 de 1993","opciones":{"A":"el contrato se termina de pleno derecho.","B":"las partes deben adoptar las medidas necesarias para restablecer la ecuación económica del contrato.","C":"la entidad debe declarar la caducidad.","D":"el contratista debe asumir todo el riesgo sin compensación."},"correcta":"B","explicacion":"El artículo 27 de la Ley 80 de 1993 dispone que se mantendrá la igualdad o equivalencia entre derechos y obligaciones surgidos al proponer o contratar, y que si se rompe por causas no imputables a quien resulte afectado, las partes adoptarán las medidas para su restablecimiento.","dificultad":2},{"id":"cont-0023","eje":"contratacion","nucleo":"general","origen":"estilo","fuente":"Ley 1150 de 2007, art. 2, num. 4, lit. c","enunciado":"Un municipio y una universidad pública celebran un contrato para que esta realice un diagnóstico social. Pueden hacerlo mediante contratación directa porque se trata de","opciones":{"A":"una urgencia manifiesta.","B":"un contrato de mínima cuantía.","C":"un concurso de méritos simplificado.","D":"un contrato interadministrativo, siempre que las obligaciones tengan relación directa con el objeto de la entidad ejecutora."},"correcta":"D","explicacion":"El literal c del numeral 4 del artículo 2 de la Ley 1150 de 2007 permite contratar directamente los contratos interadministrativos, siempre que las obligaciones tengan relación directa con el objeto de la entidad ejecutora señalado en la ley o en sus reglamentos.","dificultad":2},{"id":"cont-0024","eje":"contratacion","nucleo":"general","origen":"estilo","fuente":"Ley 1474 de 2011, art. 82","enunciado":"Los interventores responden por el cumplimiento de sus obligaciones","opciones":{"A":"solo disciplinariamente.","B":"únicamente si son servidores públicos.","C":"civil, fiscal, penal y disciplinariamente.","D":"solo civilmente frente a la entidad."},"correcta":"C","explicacion":"El artículo 82 de la Ley 1474 de 2011 dispone que los consultores, asesores e interventores responden civil, fiscal, penal y disciplinariamente por los hechos u omisiones que les sean imputables. La Ley 1952 de 2019 los incluye como sujetos disciplinables (art. 70).","dificultad":1},{"id":"cont-0025","eje":"contratacion","nucleo":"general","origen":"estilo","fuente":"Ley 80 de 1993, art. 25","enunciado":"Una entidad abre un proceso de selección sin tener disponibilidad presupuestal para el contrato. Esta actuación desconoce el principio de","opciones":{"A":"publicidad.","B":"buena fe del contratista.","C":"economía, que exige contar con las apropiaciones presupuestales antes de iniciar el proceso.","D":"autonomía de la voluntad."},"correcta":"C","explicacion":"El numeral 6 del artículo 25 de la Ley 80 de 1993, dentro del principio de economía, exige que las entidades abran licitaciones o concursos e inicien procesos de suscripción de contratos solo cuando existan las respectivas partidas o disponibilidades presupuestales.","dificultad":2},{"id":"cont-0026","eje":"contratacion","nucleo":"general","origen":"estilo","fuente":"Ley 80 de 1993, art. 26","enunciado":"Según el principio de responsabilidad de la Ley 80 de 1993, los servidores públicos que intervienen en la contratación","opciones":{"A":"responden por sus actuaciones y omisiones antijurídicas y deben indemnizar los daños que causen por ellas.","B":"no responden si actúan por delegación.","C":"solo responden ante el contratista.","D":"responden únicamente por dolo, nunca por culpa."},"correcta":"A","explicacion":"El artículo 26 de la Ley 80 de 1993 establece que los servidores públicos están obligados a buscar los fines de la contratación y a proteger los derechos de la entidad, y responden por sus actuaciones y omisiones antijurídicas, debiendo indemnizar los daños que causen.","dificultad":1},{"id":"cont-0027","eje":"contratacion","nucleo":"general","origen":"estilo","fuente":"Ley 80 de 1993, art. 8, num. 1, lit. a","enunciado":"Un aspirante a contratista fue condenado a la pena accesoria de interdicción de derechos y funciones públicas, que aún está vigente. Para contratar con el Estado","opciones":{"A":"puede contratar si ofrece una garantía mayor.","B":"solo está inhabilitado para contratos de obra.","C":"puede contratar por intermedio de un consorcio.","D":"está inhabilitado durante el término de la interdicción."},"correcta":"D","explicacion":"El artículo 8 de la Ley 80 de 1993 inhabilita para contratar a quienes se hallen inhabilitados por la Constitución y las leyes, entre ellos los condenados a interdicción de derechos y funciones públicas, durante el término de la pena. La inhabilidad no se elude participando en un consorcio.","dificultad":2},{"id":"cont-0028","eje":"contratacion","nucleo":"general","origen":"estilo","fuente":"Ley 80 de 1993, art. 24; Ley 1150 de 2007, art. 3","enunciado":"La publicidad de los procesos de contratación de las entidades estatales se garantiza principalmente mediante","opciones":{"A":"el envío de los pliegos solo a los proveedores registrados.","B":"el Sistema Electrónico de Contratación Pública, SECOP.","C":"la publicación en la cartelera de la alcaldía únicamente.","D":"la notificación personal a cada posible oferente."},"correcta":"B","explicacion":"El artículo 3 de la Ley 1150 de 2007 dispone que la sustanciación de las actuaciones y la expedición de los actos en la contratación pública se publicarán en el Sistema Electrónico de Contratación Pública, SECOP, desarrollado por Colombia Compra Eficiente.","dificultad":1},{"id":"disc-0001","eje":"disciplinario","nucleo":"especifico","origen":"estilo","fuente":"Ley 1952 de 2019, art. 33 (modif. Ley 2094 de 2021, art. 7)","enunciado":"Un secretario de despacho municipal omitió el 10 de marzo de 2020 publicar un acto en el SECOP. Para efectos de la prescripción de la acción disciplinaria por una falta instantánea, el término general es de","opciones":{"A":"cinco años contados desde que la entidad conoció la falta.","B":"tres años contados desde la apertura de la investigación.","C":"doce años contados desde el último acto.","D":"cinco años contados desde el día de su consumación."},"correcta":"D","explicacion":"El artículo 33 de la Ley 1952 de 2019, modificado por el artículo 7 de la Ley 2094 de 2021, fija en cinco años la prescripción; para faltas instantáneas se cuenta desde la consumación. Los doce años aplican solo a las faltas del artículo 52; el término no se cuenta desde la apertura ni desde el conocimiento de la entidad.","dificultad":1},{"id":"disc-0002","eje":"disciplinario","nucleo":"especifico","origen":"estilo","fuente":"Ley 1952 de 2019, art. 33 (modif. Ley 2094 de 2021, art. 7)","enunciado":"En un proceso por desaparición forzada atribuida a un servidor público, falta prevista en el artículo 52 del Código General Disciplinario, la acción disciplinaria prescribe en","opciones":{"A":"doce años.","B":"diez años.","C":"veinte años.","D":"cinco años."},"correcta":"A","explicacion":"Para las faltas del artículo 52 (infracciones al Derecho Internacional de los Derechos Humanos y al DIH) el término de prescripción es de doce años, según el inciso cuarto del artículo 33 modificado por la Ley 2094 de 2021. Cinco años es el término general; diez y veinte años no están previstos.","dificultad":2},{"id":"disc-0003","eje":"disciplinario","nucleo":"especifico","origen":"estilo","fuente":"Ley 1952 de 2019, art. 33 (modif. Ley 2094 de 2021, art. 7)","enunciado":"Se notificó el fallo sancionatorio de primera instancia por una falta grave dolosa. Según el Código General Disciplinario, la prescripción","opciones":{"A":"se interrumpe y se producirá si en tres años no se notifica la segunda instancia.","B":"se interrumpe y se producirá si en los dos años siguientes no se notifica la decisión de segunda instancia.","C":"se suspende hasta que quede en firme la sanción, sin límite de tiempo.","D":"vuelve a contarse por cinco años completos desde la notificación."},"correcta":"B","explicacion":"El artículo 33 dispone que la notificación del fallo de primera instancia interrumpe la prescripción y que esta se produce si transcurren dos años sin notificarse la segunda instancia. El plazo de tres años corresponde solo a las faltas del artículo 52; no hay suspensión indefinida ni reinicio por cinco años.","dificultad":2},{"id":"disc-0004","eje":"disciplinario","nucleo":"especifico","origen":"estilo","fuente":"Ley 1952 de 2019, art. 29 (modif. Ley 2094 de 2021, art. 4)","enunciado":"Una profesional de una alcaldía firmó un acto sin revisar un requisito elemental que cualquier persona del común habría verificado, sin que exista ignorancia supina ni violación manifiesta de reglas. Su conducta corresponde a","opciones":{"A":"culpa leve, no sancionable.","B":"dolo eventual.","C":"culpa grave.","D":"culpa gravísima."},"correcta":"C","explicacion":"Según el artículo 29, hay culpa grave cuando se incurre en falta por inobservancia del cuidado necesario que cualquier persona del común imprime a sus actuaciones. La culpa gravísima exige ignorancia supina, desatención elemental o violación manifiesta de reglas; la culpa leve no se sanciona, y el dolo requiere conocer y querer la falta.","dificultad":2},{"id":"disc-0005","eje":"disciplinario","nucleo":"especifico","origen":"estilo","fuente":"Ley 1952 de 2019, art. 29 (modif. Ley 2094 de 2021, art. 4)","enunciado":"En materia disciplinaria, la culpa leve","opciones":{"A":"solo es sancionable en faltas gravísimas.","B":"se sanciona con amonestación escrita.","C":"se sanciona con multa de diez a ciento ochenta días.","D":"no es sancionable."},"correcta":"D","explicacion":"El artículo 29 del Código General Disciplinario establece expresamente que la culpa leve no será sancionable; la culpa sancionable solo puede ser gravísima o grave. La amonestación escrita corresponde a faltas leves culposas, cometidas con culpa grave o gravísima, no a la culpa leve.","dificultad":1},{"id":"disc-0006","eje":"disciplinario","nucleo":"especifico","origen":"estilo","fuente":"Ley 1952 de 2019, art. 28","enunciado":"Según el Código General Disciplinario, la conducta es dolosa cuando el sujeto disciplinable","opciones":{"A":"actúa con desatención elemental de reglas de obligatorio cumplimiento.","B":"conoce los hechos constitutivos de falta, su ilicitud y quiere su realización.","C":"obtiene un beneficio económico con la conducta.","D":"infringe el deber objetivo de cuidado y debió prever el resultado."},"correcta":"B","explicacion":"El artículo 28 define el dolo con tres elementos: conocimiento de los hechos, conocimiento de la ilicitud y voluntad de realizarlos. La infracción del deber de cuidado y la desatención elemental describen la culpa (art. 29); el beneficio económico no hace parte de la definición.","dificultad":1},{"id":"disc-0007","eje":"disciplinario","nucleo":"especifico","origen":"estilo","fuente":"Ley 1952 de 2019, art. 48 (modif. Ley 2094 de 2021, art. 9)","enunciado":"A un servidor se le comprueba una falta gravísima cometida con dolo. La sanción que corresponde es","opciones":{"A":"destitución e inhabilidad general de ocho a diez años.","B":"suspensión de tres a dieciocho meses e inhabilidad especial.","C":"destitución e inhabilidad general de diez a veinte años.","D":"destitución e inhabilidad general de uno a veinte años."},"correcta":"C","explicacion":"El numeral 1 del artículo 48 asigna a las faltas gravísimas dolosas la destitución e inhabilidad general de diez a veinte años. De ocho a diez años corresponde a la culpa gravísima; la suspensión es para faltas graves, y el rango de uno a veinte años es propio de particulares (art. 73).","dificultad":1},{"id":"disc-0008","eje":"disciplinario","nucleo":"especifico","origen":"estilo","fuente":"Ley 1952 de 2019, art. 48 (modif. Ley 2094 de 2021, art. 9)","enunciado":"Para las faltas gravísimas realizadas con culpa gravísima, el Código General Disciplinario prevé","opciones":{"A":"destitución e inhabilidad general de ocho a diez años.","B":"multa de diez a ciento ochenta días de salario.","C":"destitución e inhabilidad general de diez a veinte años.","D":"suspensión de uno a doce meses."},"correcta":"A","explicacion":"El numeral 2 del artículo 48 fija destitución e inhabilidad general de ocho a diez años para las faltas gravísimas con culpa gravísima. De diez a veinte años es para las dolosas; la suspensión de uno a doce meses es para faltas graves culposas y la multa para leves dolosas.","dificultad":2},{"id":"disc-0009","eje":"disciplinario","nucleo":"especifico","origen":"estilo","fuente":"Ley 1952 de 2019, art. 48 (modif. Ley 2094 de 2021, art. 9)","enunciado":"Una falta grave cometida a título de dolo se sanciona con","opciones":{"A":"suspensión en el ejercicio del cargo de tres a dieciocho meses e inhabilidad especial por el mismo término.","B":"suspensión de uno a doce meses sin inhabilidad.","C":"multa de diez a ciento ochenta días del salario básico.","D":"destitución e inhabilidad general de ocho a diez años."},"correcta":"A","explicacion":"El numeral 3 del artículo 48 prevé para las faltas graves dolosas suspensión de tres a dieciocho meses e inhabilidad especial por el mismo término. La suspensión de uno a doce meses es para las graves culposas; la multa para leves dolosas y la destitución para gravísimas.","dificultad":2},{"id":"disc-0010","eje":"disciplinario","nucleo":"especifico","origen":"estilo","fuente":"Ley 1952 de 2019, art. 48 (modif. Ley 2094 de 2021, art. 9)","enunciado":"Una auxiliar de una personería incurre en una falta leve dolosa. La sanción aplicable es","opciones":{"A":"amonestación escrita con registro en la hoja de vida.","B":"suspensión de uno a doce meses.","C":"multa de diez a ciento ochenta días del salario básico devengado para la época de los hechos.","D":"multa de diez a cien salarios mínimos mensuales."},"correcta":"C","explicacion":"Según el numeral 5 del artículo 48, la falta leve dolosa se sanciona con multa de diez a ciento ochenta días del salario básico. La amonestación escrita es para faltas leves culposas; la multa en salarios mínimos mensuales es propia de los particulares disciplinables (art. 73).","dificultad":2},{"id":"disc-0011","eje":"disciplinario","nucleo":"especifico","origen":"estilo","fuente":"Ley 1952 de 2019, art. 47 (modif. Ley 2094 de 2021, art. 8)","enunciado":"Un servidor realizó objetivamente una conducta descrita como falta gravísima, pero se probó que actuó con culpa grave. Según el Código General Disciplinario, la falta","opciones":{"A":"será considerada falta leve.","B":"será considerada falta grave.","C":"no es sancionable por ausencia de dolo.","D":"conserva su calificación de gravísima."},"correcta":"B","explicacion":"El numeral 9 del artículo 47 dispone que la realización típica de una falta objetivamente gravísima cometida con culpa grave será considerada falta grave. No conserva la calificación de gravísima, no se degrada a leve y la culpa grave sí es sancionable.","dificultad":3},{"id":"disc-0012","eje":"disciplinario","nucleo":"especifico","origen":"estilo","fuente":"Ley 1952 de 2019, art. 47 (modif. Ley 2094 de 2021, art. 8)","enunciado":"Respecto de la clasificación de las faltas disciplinarias, es correcto afirmar que","opciones":{"A":"la autoridad disciplinaria califica libremente cualquier falta como gravísima según su impacto.","B":"todas las faltas están enumeradas taxativamente, incluidas las leves.","C":"la gravedad depende solo del cargo del disciplinado.","D":"las faltas gravísimas están taxativamente señaladas en la ley y las graves o leves se determinan según criterios legales."},"correcta":"D","explicacion":"El artículo 47 establece que las faltas gravísimas están taxativamente señaladas en la ley y que la gravedad o levedad de las demás se determina con criterios como la forma de culpabilidad, la jerarquía, la perturbación del servicio o la trascendencia social. La jerarquía es solo uno de esos criterios.","dificultad":2},{"id":"disc-0013","eje":"disciplinario","nucleo":"especifico","origen":"estilo","fuente":"Ley 1952 de 2019, art. 50 (modif. Ley 2094 de 2021, art. 11)","enunciado":"Al graduar la sanción de un servidor, la autoridad disciplinaria encuentra que este confesó la falta y además reparó por iniciativa propia el perjuicio causado. Estas circunstancias son","opciones":{"A":"irrelevantes, pues solo cuentan los antecedentes.","B":"atenuantes para fijar la sanción.","C":"causales de exclusión de responsabilidad.","D":"causales de extinción de la acción disciplinaria."},"correcta":"B","explicacion":"El artículo 50 incluye entre los atenuantes la confesión de la falta o aceptación de cargos y el resarcimiento del daño por iniciativa propia. No excluyen la responsabilidad (art. 31) ni extinguen la acción, cuyas causales son la muerte, la caducidad y la prescripción (art. 32).","dificultad":1},{"id":"disc-0014","eje":"disciplinario","nucleo":"especifico","origen":"estilo","fuente":"Ley 1952 de 2019, art. 50 (modif. Ley 2094 de 2021, art. 11)","enunciado":"Es un criterio agravante para graduar la sanción disciplinaria","opciones":{"A":"pertenecer el servidor público al nivel directivo o ejecutivo de la entidad.","B":"haber aceptado los cargos en la etapa de investigación.","C":"la ausencia de antecedentes disciplinarios.","D":"haber devuelto el bien afectado con la conducta."},"correcta":"A","explicacion":"El literal f del numeral 2 del artículo 50 prevé como agravante pertenecer al nivel directivo o ejecutivo. La ausencia de antecedentes, la devolución del bien y la aceptación de cargos son atenuantes según el numeral 1 del mismo artículo.","dificultad":1},{"id":"disc-0015","eje":"disciplinario","nucleo":"especifico","origen":"estilo","fuente":"Ley 1952 de 2019, art. 50 (modif. Ley 2094 de 2021, art. 11)","enunciado":"Para que una sanción de suspensión impuesta previamente opere como agravante, debe haberse impuesto dentro de los","opciones":{"A":"dos años anteriores al fallo de primera instancia.","B":"tres años anteriores a la apertura de la investigación.","C":"diez años anteriores a la conducta investigada.","D":"cinco años anteriores a la comisión de la conducta investigada."},"correcta":"D","explicacion":"El literal a del numeral 2 del artículo 50 considera agravante haber sido sancionado fiscal o disciplinariamente dentro de los cinco años anteriores a la conducta. El plazo de tres años aplica solo a la multa y la amonestación.","dificultad":3},{"id":"disc-0016","eje":"disciplinario","nucleo":"especifico","origen":"estilo","fuente":"Ley 1952 de 2019, art. 32 (modif. Ley 2094 de 2021, art. 6)","enunciado":"Durante una investigación, el ciudadano que presentó la queja manifiesta por escrito que desiste de ella. La consecuencia es que","opciones":{"A":"la acción se extingue y se archiva el proceso.","B":"la investigación se suspende hasta que el quejoso ratifique.","C":"la acción disciplinaria continúa, porque el desistimiento del quejoso no la extingue.","D":"el proceso pasa a la Personería por pérdida de competencia."},"correcta":"C","explicacion":"El parágrafo del artículo 32 dispone que el desistimiento del quejoso no extingue la acción disciplinaria. Las causales de extinción son taxativas: muerte del disciplinable, caducidad y prescripción.","dificultad":1},{"id":"disc-0017","eje":"disciplinario","nucleo":"especifico","origen":"estilo","fuente":"Ley 1952 de 2019, art. 32 (modif. Ley 2094 de 2021, art. 6)","enunciado":"Es causal de extinción de la acción disciplinaria","opciones":{"A":"el retiro del servicio del disciplinable.","B":"el pago voluntario de la multa.","C":"la muerte del disciplinable.","D":"la reparación integral del daño."},"correcta":"C","explicacion":"El artículo 32 enumera como causales de extinción la muerte del disciplinable, la caducidad y la prescripción. El retiro del servicio no impide la acción (art. 89), y la reparación del daño solo opera como atenuante.","dificultad":1},{"id":"disc-0018","eje":"disciplinario","nucleo":"especifico","origen":"estilo","fuente":"Ley 1952 de 2019, arts. 25 y 89","enunciado":"Un exfuncionario renunció hace un año y es investigado por hechos ocurridos durante su vinculación. Su defensa alega que ya no es destinatario de la ley disciplinaria. El argumento es","opciones":{"A":"procedente, porque la acción solo cobija a servidores activos.","B":"procedente solo si la renuncia fue aceptada antes de la queja.","C":"improcedente solo si la falta es gravísima.","D":"improcedente, porque son destinatarios los servidores públicos aunque se encuentren retirados del servicio."},"correcta":"D","explicacion":"El artículo 25 dispone que son destinatarios los servidores públicos aunque estén retirados, y el artículo 89 señala que la acción procede aunque el servidor ya no ejerza funciones; si la sanción no puede cumplirse, se registra. No depende de la gravedad de la falta ni de la fecha de la renuncia.","dificultad":1},{"id":"disc-0019","eje":"disciplinario","nucleo":"especifico","origen":"estilo","fuente":"Ley 1952 de 2019, art. 70","enunciado":"Una empresa privada presta un servicio público domiciliario sin que la ley o un contrato le atribuya prerrogativas exclusivas del Estado. Respecto del régimen disciplinario, sus empleados","opciones":{"A":"no son disciplinables, salvo que en ejercicio de esas actividades desempeñen funciones públicas.","B":"son disciplinables por el solo hecho de prestar un servicio público.","C":"son disciplinables únicamente por faltas gravísimas.","D":"son disciplinables por la Superintendencia y no por la Procuraduría."},"correcta":"A","explicacion":"El artículo 70 señala que no son disciplinables los particulares que presten servicios públicos, salvo que en ejercicio de esas actividades desempeñen funciones públicas. La prestación de un servicio público no equivale por sí sola a ejercer función pública.","dificultad":2},{"id":"disc-0020","eje":"disciplinario","nucleo":"especifico","origen":"estilo","fuente":"Ley 1952 de 2019, art. 70","enunciado":"Es sujeto disciplinable en su condición de particular","opciones":{"A":"el accionista minoritario de una empresa contratista.","B":"el interventor de un contrato estatal de obra.","C":"el proveedor que vende papelería a una entidad.","D":"el ciudadano que presenta una queja disciplinaria."},"correcta":"B","explicacion":"El artículo 70 aplica el régimen a los particulares que ejerzan funciones públicas, administren recursos públicos, cumplan labores de interventoría o supervisión en contratos estatales y a los auxiliares de la justicia. El proveedor, el quejoso y el accionista no están en esos supuestos.","dificultad":1},{"id":"disc-0021","eje":"disciplinario","nucleo":"especifico","origen":"estilo","fuente":"Ley 1952 de 2019, art. 73","enunciado":"Un particular que administraba recursos públicos fue hallado responsable de una falta que causó detrimento patrimonial. Además de la inhabilidad, la sanción patrimonial será","opciones":{"A":"igual al valor exacto del detrimento.","B":"de cien a mil salarios mínimos mensuales.","C":"de diez a ciento ochenta días de salario.","D":"igual al doble del detrimento patrimonial sufrido por el Estado."},"correcta":"D","explicacion":"El artículo 73 prevé para particulares multa de 10 a 100 salarios mínimos mensuales y, cuando la conducta implique detrimento del patrimonio público, una sanción patrimonial igual al doble del detrimento. Los días de salario corresponden a servidores públicos (art. 48).","dificultad":3},{"id":"disc-0022","eje":"disciplinario","nucleo":"especifico","origen":"estilo","fuente":"Ley 1952 de 2019, art. 31 (modif. Ley 2094 de 2021, art. 5)","enunciado":"Un servidor incumplió un plazo porque un deslizamiento de tierra, imprevisible e irresistible, destruyó la sede y los equipos. En materia disciplinaria","opciones":{"A":"no hay responsabilidad, por fuerza mayor.","B":"responde a título de culpa grave.","C":"la acción se extingue por caducidad.","D":"solo procede una amonestación verbal."},"correcta":"A","explicacion":"El numeral 1 del artículo 31 excluye la responsabilidad disciplinaria cuando la conducta se realiza por fuerza mayor. No es un caso de culpa ni de extinción de la acción, y la amonestación verbal no existe como sanción en el Código.","dificultad":1},{"id":"disc-0023","eje":"disciplinario","nucleo":"especifico","origen":"estilo","fuente":"Ley 1952 de 2019, art. 31, num. 8 (modif. Ley 2094 de 2021, art. 5)","enunciado":"Un servidor actuó con la convicción errada de que su conducta no era falta, pero el error de hecho era vencible. Si la falta admite la modalidad culposa, se sancionará","opciones":{"A":"con la mitad de la sanción dolosa.","B":"a título de culpa.","C":"con amonestación escrita en todo caso.","D":"a título de dolo, sin reducción."},"correcta":"B","explicacion":"El numeral 8 del artículo 31 señala que si el error de hecho fuere vencible se sancionará la conducta a título de culpa, siempre que la falta admita esa modalidad. La reducción a la mitad corresponde al error de derecho vencible.","dificultad":3},{"id":"disc-0024","eje":"disciplinario","nucleo":"especifico","origen":"estilo","fuente":"Ley 1952 de 2019, art. 9 (modif. Ley 2094 de 2021, art. 2)","enunciado":"Según el Código General Disciplinario, la conducta del disciplinable es ilícita cuando","opciones":{"A":"coincide con una descripción típica de la ley penal.","B":"contraría cualquier reglamento interno, aunque no afecte el servicio.","C":"afecta sustancialmente el deber funcional sin justificación alguna.","D":"causa un daño patrimonial cuantificable a la entidad."},"correcta":"C","explicacion":"El artículo 9 define la ilicitud sustancial como la afectación sustancial del deber funcional sin justificación. No exige daño patrimonial ni tipicidad penal, y la sola infracción formal de un reglamento no basta si no afecta sustancialmente el deber funcional.","dificultad":2},{"id":"disc-0025","eje":"disciplinario","nucleo":"especifico","origen":"estilo","fuente":"Ley 1952 de 2019, art. 44","enunciado":"Un profesional de una entidad debe evaluar las propuestas de una licitación en la que participa una sociedad de la que su hermano es socio. Conforme al Código General Disciplinario, debe","opciones":{"A":"declararse impedido, porque existe conflicto de intereses.","B":"informar al comité solo si la sociedad resulta adjudicataria.","C":"continuar, pues el parentesco entre hermanos no genera impedimento.","D":"evaluar la propuesta con mayor rigor para evitar sospechas."},"correcta":"A","explicacion":"El artículo 44 obliga a declararse impedido cuando el servidor o sus parientes dentro del cuarto grado de consanguinidad tengan interés particular y directo en el asunto. Un hermano es pariente en segundo grado de consanguinidad, por lo que debe apartarse antes de actuar.","dificultad":1},{"id":"disc-0026","eje":"disciplinario","nucleo":"especifico","origen":"estilo","fuente":"Ley 1952 de 2019, art. 54, num. 5","enunciado":"El alcalde de un municipio declaró la urgencia manifiesta para contratar el mantenimiento rutinario de vías, sin que existiera ninguna de las causales previstas en la ley. Esta conducta está descrita como","opciones":{"A":"conducta atípica, porque la urgencia la declara el representante legal.","B":"falta leve, porque se trata de una decisión discrecional.","C":"falta gravísima relacionada con la contratación pública.","D":"falta grave relacionada con el servicio."},"correcta":"C","explicacion":"El numeral 5 del artículo 54 tipifica como falta gravísima aplicar la urgencia manifiesta para la celebración de contratos sin existir las causales previstas en la ley. Ser el representante legal no autoriza a declararla sin causal.","dificultad":2},{"id":"disc-0027","eje":"disciplinario","nucleo":"especifico","origen":"estilo","fuente":"Ley 1952 de 2019, art. 54, num. 6","enunciado":"La supervisora de un contrato certificó como recibida a satisfacción una obra que no había sido ejecutada a cabalidad. Según el Código General Disciplinario, incurre en","opciones":{"A":"ninguna falta, si el contratista termina la obra después.","B":"falta grave por descuido administrativo.","C":"una irregularidad que solo genera responsabilidad fiscal.","D":"falta gravísima relacionada con la contratación pública."},"correcta":"D","explicacion":"El numeral 6 del artículo 54 describe como falta gravísima que el supervisor o interventor certifique como recibida a satisfacción obra no ejecutada a cabalidad. La responsabilidad disciplinaria es independiente de la fiscal y la terminación posterior no borra la falta.","dificultad":1},{"id":"disc-0028","eje":"disciplinario","nucleo":"especifico","origen":"estilo","fuente":"Ley 1952 de 2019, art. 60, num. 2","enunciado":"Un jefe de oficina presiona a sus subalternos para que asistan a eventos de la campaña de un candidato a la alcaldía. Esta conducta constituye","opciones":{"A":"ejercicio legítimo del derecho al voto.","B":"falta gravísima relacionada con la intervención en política.","C":"falta leve si los eventos son fuera del horario laboral.","D":"conducta sancionable solo por el Consejo Nacional Electoral."},"correcta":"B","explicacion":"El numeral 2 del artículo 60 tipifica como falta gravísima utilizar el empleo para presionar a particulares o subalternos a respaldar una causa o campaña política. No importa el horario y su conocimiento corresponde a las autoridades disciplinarias.","dificultad":1},{"id":"fp-0001","eje":"funcion-publica","nucleo":"general","origen":"estilo","fuente":"Ley 909 de 2004, art. 5","enunciado":"Según la Ley 909 de 2004, los empleos de los organismos y entidades regulados por ella son","opciones":{"A":"provisionales mientras no exista lista de elegibles.","B":"de libre nombramiento y remoción, salvo los del nivel técnico y asistencial.","C":"de período fijo de cuatro años coincidente con el del nominador.","D":"de carrera administrativa, con excepción de los de elección popular, período fijo, trabajadores oficiales, libre nombramiento y remoción y los temporales, entre otros."},"correcta":"D","explicacion":"El artículo 5 de la Ley 909 de 2004 desarrolla el artículo 125 de la Constitución: los empleos son de carrera, salvo las excepciones que la misma ley enumera, como elección popular, período fijo, trabajadores oficiales, libre nombramiento y remoción y temporales.","dificultad":1},{"id":"fp-0002","eje":"funcion-publica","nucleo":"general","origen":"estilo","fuente":"Constitución Política, art. 130; Ley 909 de 2004, art. 7","enunciado":"La administración y vigilancia de las carreras de los servidores públicos, excepción hecha de las que tengan carácter especial, corresponde a","opciones":{"A":"la Procuraduría General de la Nación.","B":"el Ministerio del Trabajo.","C":"la Comisión Nacional del Servicio Civil.","D":"el Departamento Administrativo de la Función Pública."},"correcta":"C","explicacion":"El artículo 130 de la Constitución crea la Comisión Nacional del Servicio Civil, responsable de la administración y vigilancia de las carreras, salvo las especiales. La carrera de la Procuraduría es especial y la administra la propia entidad (Decreto Ley 262 de 2000).","dificultad":1},{"id":"fp-0003","eje":"funcion-publica","nucleo":"general","origen":"estilo","fuente":"Ley 909 de 2004, art. 31 (modif. Ley 1960 de 2019, art. 6)","enunciado":"En el régimen general de carrera, la lista de elegibles resultante de un concurso tiene una vigencia de","opciones":{"A":"dos años.","B":"un año.","C":"tres años.","D":"cuatro años."},"correcta":"A","explicacion":"El numeral 4 del artículo 31 de la Ley 909 de 2004, modificado por la Ley 1960 de 2019, establece que la lista de elegibles tendrá una vigencia de dos años.","dificultad":1},{"id":"fp-0004","eje":"funcion-publica","nucleo":"general","origen":"estilo","fuente":"Ley 909 de 2004, art. 31, num. 5","enunciado":"En el régimen general de la Ley 909 de 2004, la persona seleccionada por concurso es nombrada en período de prueba por","opciones":{"A":"tres meses.","B":"seis meses.","C":"cuatro meses.","D":"un año."},"correcta":"B","explicacion":"El numeral 5 del artículo 31 de la Ley 909 de 2004 fija el período de prueba en seis meses, al final de los cuales se evalúa el desempeño. En la Procuraduría, por su régimen especial, es de cuatro meses (Decreto Ley 262 de 2000, art. 218).","dificultad":1},{"id":"fp-0005","eje":"funcion-publica","nucleo":"general","origen":"estilo","fuente":"Ley 909 de 2004, art. 31","enunciado":"Según la Ley 909 de 2004, la convocatoria de un concurso","opciones":{"A":"es norma reguladora de todo concurso y obliga tanto a la administración como a los participantes.","B":"solo obliga a los aspirantes, no a la entidad.","C":"puede modificarse en cualquier momento por el nominador.","D":"es una simple guía que la entidad puede variar libremente."},"correcta":"A","explicacion":"El numeral 1 del artículo 31 dispone que la convocatoria es norma reguladora del concurso y obliga a la administración, a las entidades contratadas para realizarlo y a los participantes. Solo puede modificarse en los casos y momentos que la ley permite.","dificultad":1},{"id":"fp-0006","eje":"funcion-publica","nucleo":"general","origen":"estilo","fuente":"Ley 909 de 2004, art. 24 (modif. Ley 1960 de 2019, art. 1)","enunciado":"Mientras se surte el proceso de selección para un empleo de carrera vacante, los empleados de carrera","opciones":{"A":"no tienen ninguna preferencia frente a personas externas.","B":"pueden ser nombrados en propiedad sin concurso.","C":"tienen derecho preferencial a ser encargados si cumplen los requisitos y tienen las aptitudes y la evaluación de desempeño exigidas.","D":"solo pueden ser encargados en empleos de libre nombramiento."},"correcta":"C","explicacion":"El artículo 24 de la Ley 909 de 2004, modificado por la Ley 1960 de 2019, otorga a los empleados de carrera derecho preferencial a ser encargados en empleos de carrera vacantes cuando cumplan los requisitos y las condiciones de desempeño exigidas.","dificultad":2},{"id":"fp-0007","eje":"funcion-publica","nucleo":"general","origen":"estilo","fuente":"Ley 909 de 2004, art. 41","enunciado":"Es causal de retiro del servicio de los empleados de carrera según la Ley 909 de 2004","opciones":{"A":"el cambio del jefe de la entidad.","B":"la reestructuración de procesos sin supresión de cargos.","C":"la decisión discrecional del nominador sin motivación.","D":"la declaratoria de insubsistencia del nombramiento como consecuencia del resultado no satisfactorio en la evaluación del desempeño."},"correcta":"D","explicacion":"El artículo 41 de la Ley 909 de 2004 enumera causales como la insubsistencia por evaluación no satisfactoria, la renuncia regularmente aceptada, la destitución por proceso disciplinario y la supresión del empleo, entre otras. La remoción discrecional aplica a empleos de libre nombramiento.","dificultad":1},{"id":"fp-0008","eje":"funcion-publica","nucleo":"general","origen":"estilo","fuente":"Ley 909 de 2004, art. 1","enunciado":"Según la Ley 909 de 2004, integran la función pública los siguientes empleos públicos","opciones":{"A":"de elección popular únicamente.","B":"de carrera, de libre nombramiento y remoción, de período fijo y temporales.","C":"de trabajadores particulares que contratan con el Estado.","D":"de contrato de prestación de servicios y de carrera."},"correcta":"B","explicacion":"El artículo 1 de la Ley 909 de 2004 señala que hacen parte de la función pública los empleos de carrera, de libre nombramiento y remoción, de período fijo y temporales. Los contratistas de prestación de servicios no son empleados públicos.","dificultad":2},{"id":"fp-0009","eje":"funcion-publica","nucleo":"general","origen":"estilo","fuente":"Decreto 785 de 2005, art. 3; Decreto 1083 de 2015","enunciado":"Los niveles jerárquicos de los empleos en las entidades territoriales son","opciones":{"A":"directivo, ejecutivo, profesional y operativo.","B":"superior, medio y bajo.","C":"directivo, asesor, profesional, técnico y asistencial.","D":"gerencial, administrativo y de apoyo."},"correcta":"C","explicacion":"El Decreto 785 de 2005 clasifica los empleos territoriales en los niveles directivo, asesor, profesional, técnico y asistencial; el Decreto 1083 de 2015 prevé los mismos niveles para el orden nacional. La Procuraduría tiene además el nivel ejecutivo en su régimen especial.","dificultad":1},{"id":"fp-0010","eje":"funcion-publica","nucleo":"general","origen":"estilo","fuente":"Decreto 1083 de 2015, art. 2.2.5.5.1 y ss.","enunciado":"Un empleado sale temporalmente del ejercicio de su cargo para cumplir una misión propia de su empleo en otra ciudad, por instrucción de su jefe. Esta situación administrativa es","opciones":{"A":"una comisión de servicios.","B":"un permiso remunerado.","C":"una licencia ordinaria.","D":"un encargo."},"correcta":"A","explicacion":"La comisión de servicios permite ejercer temporalmente las funciones propias del empleo en un lugar diferente a la sede habitual o atender actividades oficiales distintas a las inherentes al cargo, según el Decreto 1083 de 2015. La licencia separa del cargo y el encargo asigna otro empleo.","dificultad":1},{"id":"fp-0011","eje":"funcion-publica","nucleo":"general","origen":"estilo","fuente":"Decreto 1045 de 1978, art. 8; Decreto 1083 de 2015","enunciado":"Los empleados públicos tienen derecho, por cada año de servicio, a vacaciones remuneradas de","opciones":{"A":"diez días hábiles.","B":"quince días hábiles.","C":"quince días calendario.","D":"treinta días hábiles."},"correcta":"B","explicacion":"El artículo 8 del Decreto 1045 de 1978 reconoce a los empleados públicos quince días hábiles de vacaciones por cada año de servicio, salvo regímenes especiales.","dificultad":1},{"id":"fp-0012","eje":"funcion-publica","nucleo":"general","origen":"estilo","fuente":"Ley 909 de 2004, art. 38","enunciado":"Según la Ley 909 de 2004, el desempeño laboral de los empleados de carrera debe ser evaluado y calificado con base en","opciones":{"A":"la percepción personal del jefe inmediato sin criterios previos.","B":"la antigüedad del empleado en la entidad.","C":"las quejas de los usuarios exclusivamente.","D":"parámetros previamente establecidos a partir de los planes anuales de gestión del área respectiva y las metas institucionales."},"correcta":"D","explicacion":"El artículo 38 de la Ley 909 de 2004 exige que la evaluación del desempeño se base en parámetros previamente establecidos, derivados de los planes de gestión y las metas institucionales; su resultado no satisfactorio puede conducir al retiro.","dificultad":2},{"id":"fp-0013","eje":"funcion-publica","nucleo":"general","origen":"estilo","fuente":"Ley 909 de 2004, art. 44","enunciado":"Se suprime el cargo de un empleado de carrera administrativa por una reestructuración. Según la Ley 909 de 2004, el empleado","opciones":{"A":"conserva el cargo hasta que se pensione.","B":"pierde todos sus derechos sin compensación.","C":"debe ser trasladado a cualquier cargo aunque sea de inferior nivel.","D":"tiene derecho preferencial a ser incorporado en un empleo equivalente o, si no es posible, a ser indemnizado."},"correcta":"D","explicacion":"El artículo 44 de la Ley 909 de 2004 dispone que los empleados de carrera cuyo cargo sea suprimido tienen derecho preferencial a ser incorporados en un empleo igual o equivalente o, de no ser posible, a recibir una indemnización.","dificultad":1},{"id":"fp-0014","eje":"funcion-publica","nucleo":"general","origen":"estilo","fuente":"Ley 1010 de 2006, art. 2","enunciado":"Un jefe insulta de manera reiterada y pública a una profesional a su cargo y la expone a burlas sobre su origen regional. Según la Ley 1010 de 2006, esta conducta corresponde a","opciones":{"A":"un ejercicio legítimo del poder de subordinación.","B":"maltrato laboral, como modalidad de acoso laboral.","C":"una falta leve que solo admite llamado de atención verbal.","D":"inequidad laboral únicamente."},"correcta":"B","explicacion":"El artículo 2 de la Ley 1010 de 2006 define el maltrato laboral como todo acto de violencia contra la integridad física o moral, la libertad o los bienes de quien se desempeña como empleado, incluidas expresiones verbales injuriosas o ultrajantes. Las conductas descritas encajan en esa modalidad.","dificultad":2},{"id":"fp-0015","eje":"funcion-publica","nucleo":"general","origen":"estilo","fuente":"Ley 1010 de 2006, art. 12","enunciado":"Cuando la víctima de acoso laboral es un servidor público, la competencia para conocer de la falta disciplinaria corresponde a","opciones":{"A":"el Ministerio Público o las salas disciplinarias competentes, conforme a las normas de competencia.","B":"el comité de convivencia, que impone la sanción.","C":"la Comisión Nacional del Servicio Civil.","D":"el juez laboral exclusivamente."},"correcta":"A","explicacion":"El artículo 12 de la Ley 1010 de 2006 atribuye la competencia, cuando las víctimas son servidores públicos, al Ministerio Público o a las autoridades disciplinarias competentes; si son trabajadores particulares, a los jueces laborales. El comité de convivencia es instancia preventiva y no sancionadora.","dificultad":2},{"id":"fp-0016","eje":"funcion-publica","nucleo":"general","origen":"estilo","fuente":"Ley 909 de 2004, art. 2","enunciado":"Según la Ley 909 de 2004, la función pública se desarrolla teniendo en cuenta principios como","opciones":{"A":"confianza política, lealtad partidista y libre remoción.","B":"oralidad, inmediación y concentración.","C":"igualdad, mérito, moralidad, eficacia, economía, imparcialidad, transparencia, celeridad y publicidad.","D":"autonomía de la voluntad y libre competencia."},"correcta":"C","explicacion":"El artículo 2 de la Ley 909 de 2004 retoma los principios del artículo 209 de la Constitución y agrega el mérito y la transparencia como criterios para el acceso y permanencia en los empleos.","dificultad":1},{"id":"fp-0017","eje":"funcion-publica","nucleo":"general","origen":"estilo","fuente":"Ley 909 de 2004, art. 21","enunciado":"Una entidad necesita cubrir funciones que no realiza el personal de planta por no formar parte de sus actividades permanentes, por un plazo determinado. Según la Ley 909 de 2004 puede crear","opciones":{"A":"contratos de prestación de servicios con subordinación.","B":"cargos de período fijo.","C":"empleos de libre nombramiento y remoción permanentes.","D":"empleos de carácter temporal."},"correcta":"D","explicacion":"El artículo 21 de la Ley 909 de 2004 permite crear empleos temporales para cumplir funciones que no realiza el personal de planta por no ser permanentes, desarrollar programas de duración determinada o suplir necesidades por sobrecarga de trabajo, entre otros. Contratar con subordinación configura un contrato realidad.","dificultad":2},{"id":"fp-0018","eje":"funcion-publica","nucleo":"general","origen":"estilo","fuente":"Ley 1952 de 2019, art. 38","enunciado":"Es un deber de todo servidor público según el Código General Disciplinario","opciones":{"A":"delegar en particulares sus funciones cuando lo considere útil.","B":"participar en las actividades de los partidos políticos.","C":"cumplir y hacer que se cumplan los deberes contenidos en la Constitución, los tratados de derechos humanos y DIH, las leyes, decretos y demás normas.","D":"aceptar dádivas de los usuarios como reconocimiento a su labor."},"correcta":"C","explicacion":"El numeral 1 del artículo 38 de la Ley 1952 de 2019 consagra como deber cumplir y hacer cumplir la Constitución, los tratados de derechos humanos y DIH, las leyes y demás normas. Participar en política, recibir dádivas o delegar funciones en particulares sin habilitación legal son conductas prohibidas.","dificultad":1},{"id":"fp-0019","eje":"funcion-publica","nucleo":"general","origen":"estilo","fuente":"Ley 1952 de 2019, art. 39","enunciado":"Un profesional universitario acepta un viaje pagado por un contratista cuyo contrato supervisa. Según el Código General Disciplinario","opciones":{"A":"solo incurre en falta si el viaje supera un salario mínimo.","B":"incurre en la prohibición de solicitar o aceptar dádivas, agasajos, regalos o cualquier otra clase de beneficios.","C":"no incurre en falta porque el contratista es un particular.","D":"actúa válidamente si el viaje se hace en vacaciones."},"correcta":"B","explicacion":"El artículo 39 de la Ley 1952 de 2019 prohíbe solicitar, directa o indirectamente, dádivas, agasajos, regalos, favores o cualquier otra clase de beneficios. No hay cuantía mínima y el momento del viaje no elimina la prohibición.","dificultad":1},{"id":"fp-0020","eje":"funcion-publica","nucleo":"general","origen":"estilo","fuente":"Constitución Política, art. 122; Ley 190 de 1995","enunciado":"Antes de posesionarse en un empleo público, la persona debe declarar bajo juramento","opciones":{"A":"el monto de sus bienes y rentas.","B":"su filiación política.","C":"su orientación religiosa.","D":"sus calificaciones académicas de pregrado."},"correcta":"A","explicacion":"El artículo 122 de la Constitución y la Ley 190 de 1995 exigen que, antes de tomar posesión, el servidor declare bajo juramento el monto de sus bienes y rentas, y la actualice cuando la ley lo ordene. La filiación política y la religión no pueden ser exigidas.","dificultad":1},{"id":"fp-0021","eje":"funcion-publica","nucleo":"general","origen":"estilo","fuente":"Ley 909 de 2004, art. 47","enunciado":"Según la Ley 909 de 2004, son empleos de gerencia pública","opciones":{"A":"los empleos de carrera del nivel profesional.","B":"los cargos de elección popular del nivel territorial.","C":"los contratos de prestación de servicios de alto valor.","D":"los cargos de libre nombramiento y remoción que conllevan ejercicio de responsabilidad directiva en la administración pública."},"correcta":"D","explicacion":"El artículo 47 de la Ley 909 de 2004 define los empleos de naturaleza gerencial como los de libre nombramiento y remoción que conllevan ejercicio de responsabilidad directiva, sujetos a acuerdos de gestión.","dificultad":3},{"id":"fp-0022","eje":"funcion-publica","nucleo":"general","origen":"estilo","fuente":"Ley 909 de 2004, art. 25","enunciado":"El titular de un empleo de carrera sale a disfrutar una licencia de maternidad. Mientras dura la situación, el empleo puede proveerse","opciones":{"A":"con nombramiento en propiedad de otra persona.","B":"en forma provisional, solo por el tiempo que dure la vacancia temporal, cuando no sea posible el encargo con servidores de carrera.","C":"mediante contrato de prestación de servicios con funciones permanentes.","D":"únicamente con la lista de elegibles vigente, en período de prueba."},"correcta":"B","explicacion":"El artículo 25 de la Ley 909 de 2004 dispone que los empleos de carrera cuyos titulares estén en situaciones administrativas que impliquen separación temporal se proveen en forma provisional solo por el tiempo de la vacancia, cuando no sea posible proveerlos mediante encargo con servidores de carrera.","dificultad":2},{"id":"fp-0023","eje":"funcion-publica","nucleo":"general","origen":"estilo","fuente":"Constitución Política, art. 123","enunciado":"Según el artículo 123 de la Constitución, son servidores públicos","opciones":{"A":"los particulares que prestan servicios públicos domiciliarios.","B":"todas las personas que contratan con el Estado.","C":"los miembros de las corporaciones públicas, los empleados y trabajadores del Estado y de sus entidades descentralizadas territorialmente y por servicios.","D":"solo los empleados de carrera administrativa."},"correcta":"C","explicacion":"El artículo 123 define como servidores públicos a los miembros de corporaciones públicas, los empleados y los trabajadores del Estado y de sus entidades descentralizadas. Los particulares pueden ejercer funciones públicas temporalmente, pero no por ello son servidores públicos.","dificultad":1},{"id":"fp-0024","eje":"funcion-publica","nucleo":"general","origen":"estilo","fuente":"Ley 1952 de 2019, art. 37","enunciado":"Es un derecho de todo servidor público según el Código General Disciplinario","opciones":{"A":"recibir capacitación para el mejor desempeño de sus funciones.","B":"participar en controversias políticas en horario laboral.","C":"ser ascendido sin concurso al cumplir cinco años de servicio.","D":"negarse a cumplir órdenes legítimas que considere inconvenientes."},"correcta":"A","explicacion":"El artículo 37 de la Ley 1952 de 2019 reconoce derechos como percibir puntualmente la remuneración, recibir capacitación, participar en programas de bienestar y disfrutar de estímulos. El ascenso se obtiene por mérito y las demás conductas contrarían deberes y prohibiciones.","dificultad":1},{"id":"fp-0025","eje":"funcion-publica","nucleo":"general","origen":"estilo","fuente":"Ley 1952 de 2019, art. 42","enunciado":"Una persona que fue condenada por un delito contra el patrimonio del Estado aspira a un cargo público. Según el Código General Disciplinario y la Constitución","opciones":{"A":"está inhabilitada para desempeñar cargos públicos.","B":"puede posesionarse después de cinco años de la condena.","C":"solo está inhabilitada para cargos de elección popular.","D":"puede posesionarse si paga la condena."},"correcta":"A","explicacion":"El artículo 122 de la Constitución, modificado por el Acto Legislativo 01 de 2009, y el artículo 42 de la Ley 1952 de 2019 establecen inhabilidad para quienes hayan sido condenados por delitos que afecten el patrimonio del Estado. Es una inhabilidad que no se supera con el pago.","dificultad":2},{"id":"fp-0026","eje":"funcion-publica","nucleo":"general","origen":"estilo","fuente":"Constitución Política, art. 126","enunciado":"El secretario de una entidad pretende nombrar como su asistente a su sobrino. Según el artículo 126 de la Constitución","opciones":{"A":"puede hacerlo con autorización del jefe de talento humano.","B":"puede hacerlo si el sobrino cumple los requisitos del cargo.","C":"los servidores públicos no pueden nombrar como empleados a personas con las cuales tengan parentesco hasta el cuarto grado de consanguinidad, segundo de afinidad o primero civil.","D":"solo está prohibido nombrar a hijos y cónyuges."},"correcta":"C","explicacion":"El artículo 126 de la Constitución prohíbe nombrar como empleados a personas con las que se tenga parentesco hasta el cuarto grado de consanguinidad, segundo de afinidad o primero civil. Un sobrino es pariente en tercer grado de consanguinidad, salvo normas sobre ingreso o ascenso por méritos.","dificultad":2},{"id":"fp-0027","eje":"funcion-publica","nucleo":"general","origen":"estilo","fuente":"Ley 1952 de 2019, art. 38, num. 12","enunciado":"Un servidor de carrera se ausenta de su sitio de trabajo varias horas para atender asuntos personales sin permiso. Esta conducta","opciones":{"A":"es válida si recupera el tiempo otro día sin informar.","B":"desconoce el deber de dedicar la totalidad del tiempo reglamentario de trabajo al desempeño de las funciones encomendadas.","C":"no tiene relevancia disciplinaria para empleados de carrera.","D":"solo puede ser objeto de descuento salarial."},"correcta":"B","explicacion":"El artículo 38 de la Ley 1952 de 2019 consagra el deber de dedicar la totalidad del tiempo reglamentario de trabajo al desempeño de las funciones. Su incumplimiento puede constituir falta disciplinaria, además de las consecuencias salariales.","dificultad":1},{"id":"fp-0028","eje":"funcion-publica","nucleo":"general","origen":"estilo","fuente":"Ley 909 de 2004, art. 23","enunciado":"Los empleos de libre nombramiento y remoción se proveen","opciones":{"A":"por elección del concejo o la asamblea.","B":"mediante sorteo público.","C":"mediante concurso abierto de méritos con lista de elegibles.","D":"por nombramiento ordinario, previo cumplimiento de los requisitos exigidos para el desempeño del empleo."},"correcta":"D","explicacion":"El artículo 23 de la Ley 909 de 2004 dispone que los empleos de libre nombramiento y remoción se proveen por nombramiento ordinario, previo cumplimiento de los requisitos del cargo. Los de carrera se proveen por concurso y período de prueba.","dificultad":2},{"id":"pgn-0001","eje":"pgn","nucleo":"especifico","origen":"estilo","fuente":"Decreto Ley 262 de 2000, art. 1","enunciado":"Según el Decreto Ley 262 de 2000, la Procuraduría General de la Nación","opciones":{"A":"es un órgano adscrito al Ministerio de Justicia con autonomía técnica.","B":"es el máximo organismo del Ministerio Público y tiene autonomía administrativa, financiera y presupuestal.","C":"es parte de la Rama Judicial y está sujeta al Consejo Superior de la Judicatura.","D":"es un organismo de control fiscal con autonomía presupuestal."},"correcta":"B","explicacion":"El artículo 1 del Decreto Ley 262 de 2000 define a la PGN como el máximo organismo del Ministerio Público, con autonomía administrativa, financiera y presupuestal, bajo la suprema dirección del Procurador General. Es un órgano de control autónomo, no adscrito al Ejecutivo ni a la Rama Judicial, y no ejerce control fiscal.","dificultad":1},{"id":"pgn-0002","eje":"pgn","nucleo":"especifico","origen":"estilo","fuente":"Constitución Política, art. 276; Decreto Ley 262 de 2000, art. 3","enunciado":"El Procurador General de la Nación es elegido por","opciones":{"A":"el Senado de la República, de terna integrada por candidatos del Presidente, la Corte Suprema de Justicia y el Consejo de Estado.","B":"la Cámara de Representantes, de terna enviada por el Presidente de la República.","C":"el Congreso en pleno, de lista de elegibles conformada por concurso.","D":"la Corte Constitucional, de terna enviada por el Senado."},"correcta":"A","explicacion":"El artículo 276 de la Constitución y el artículo 3 del Decreto Ley 262 de 2000 disponen que el Senado elige al Procurador para un período de cuatro años, de terna del Presidente, la Corte Suprema de Justicia y el Consejo de Estado. La Cámara elige al Defensor del Pueblo, de terna del Presidente.","dificultad":1},{"id":"pgn-0003","eje":"pgn","nucleo":"especifico","origen":"estilo","fuente":"Decreto Ley 262 de 2000, art. 3","enunciado":"El Procurador General de la Nación toma posesión ante","opciones":{"A":"el Presidente del Senado.","B":"el Presidente de la Corte Suprema de Justicia.","C":"el Presidente de la República o quien haga sus veces.","D":"el Consejo de Estado en pleno."},"correcta":"C","explicacion":"El artículo 3 del Decreto Ley 262 de 2000 establece que el Procurador General tomará posesión ante el Presidente de la República o ante quien haga sus veces, aunque su elección corresponda al Senado.","dificultad":2},{"id":"pgn-0004","eje":"pgn","nucleo":"especifico","origen":"estilo","fuente":"Decreto Ley 262 de 2000, art. 6","enunciado":"Mientras se realiza la elección y posesión de un nuevo Procurador General por falta absoluta del titular, ejerce como Procurador General","opciones":{"A":"el Defensor del Pueblo.","B":"el Secretario General.","C":"el Procurador Delegado más antiguo.","D":"el Viceprocurador General."},"correcta":"D","explicacion":"El Decreto Ley 262 de 2000 dispone que, en caso de falta absoluta, mientras se realiza la elección y posesión, el Viceprocurador ejercerá como Procurador General de la Nación.","dificultad":1},{"id":"pgn-0005","eje":"pgn","nucleo":"especifico","origen":"estilo","fuente":"Constitución Política, art. 118","enunciado":"Según la Constitución Política, el Ministerio Público es ejercido por","opciones":{"A":"el Procurador General de la Nación, el Defensor del Pueblo, los procuradores delegados, los agentes del Ministerio Público ante las autoridades jurisdiccionales, los personeros municipales y los demás funcionarios que determine la ley.","B":"el Procurador General de la Nación, el Contralor General y el Fiscal General.","C":"la Procuraduría y la Fiscalía General de la Nación.","D":"exclusivamente la Procuraduría General de la Nación y sus dependencias."},"correcta":"A","explicacion":"El artículo 118 de la Constitución enumera quienes ejercen el Ministerio Público: Procurador General, Defensor del Pueblo, procuradores delegados, agentes ante las autoridades jurisdiccionales, personeros municipales y demás funcionarios que determine la ley. La Contraloría y la Fiscalía no hacen parte del Ministerio Público.","dificultad":1},{"id":"pgn-0006","eje":"pgn","nucleo":"especifico","origen":"estilo","fuente":"Constitución Política, art. 278, num. 1","enunciado":"El Procurador General debe ejercer directamente, sin delegar, la función de","opciones":{"A":"intervenir en los procesos civiles de familia.","B":"desvincular del cargo, previa audiencia y mediante decisión motivada, al funcionario que infrinja de manera manifiesta la Constitución o la ley.","C":"realizar visitas preventivas a las alcaldías.","D":"vigilar el cumplimiento de las decisiones judiciales."},"correcta":"B","explicacion":"El artículo 278 de la Constitución enumera funciones que el Procurador ejerce directamente, entre ellas desvincular del cargo, previa audiencia y decisión motivada, al funcionario que infrinja de manera manifiesta la Constitución o la ley. Las otras corresponden al artículo 277 y pueden asignarse a sus agentes.","dificultad":2},{"id":"pgn-0007","eje":"pgn","nucleo":"especifico","origen":"estilo","fuente":"Constitución Política, art. 278, num. 5","enunciado":"En los procesos de control de constitucionalidad que se tramitan ante la Corte Constitucional, el Procurador General","opciones":{"A":"interviene solo si la norma demandada es disciplinaria.","B":"actúa como demandante obligatorio.","C":"rinde concepto, función que ejerce directamente.","D":"decide la admisión de la demanda."},"correcta":"C","explicacion":"El numeral 5 del artículo 278 asigna al Procurador, como función directa, rendir concepto en los procesos de control de constitucionalidad. No decide la admisión, que corresponde al magistrado sustanciador, y su concepto no se limita a normas disciplinarias.","dificultad":1},{"id":"pgn-0008","eje":"pgn","nucleo":"especifico","origen":"estilo","fuente":"Constitución Política, art. 277, parágrafo","enunciado":"Para el cumplimiento de sus funciones, la Constitución otorga a la Procuraduría","opciones":{"A":"la facultad de dictar sentencias en procesos penales contra servidores públicos.","B":"la función de juzgar a los congresistas.","C":"la potestad de expedir leyes en materia disciplinaria.","D":"atribuciones de policía judicial y la facultad de interponer las acciones que considere necesarias."},"correcta":"D","explicacion":"El parágrafo del artículo 277 dispone que la Procuraduría tendrá atribuciones de policía judicial y podrá interponer las acciones que considere necesarias. No dicta sentencias penales ni juzga a los congresistas, y no tiene potestad legislativa, aunque puede presentar proyectos de ley (art. 278).","dificultad":2},{"id":"pgn-0009","eje":"pgn","nucleo":"especifico","origen":"estilo","fuente":"Constitución Política, art. 277, num. 4","enunciado":"Entre las funciones del Procurador General, por sí o por medio de sus delegados y agentes, la Constitución incluye","opciones":{"A":"defender los intereses colectivos, en especial el ambiente.","B":"expedir los actos de nombramiento de los personeros.","C":"ejercer el control fiscal posterior y selectivo.","D":"dirigir la acción penal contra los servidores públicos."},"correcta":"A","explicacion":"El numeral 4 del artículo 277 atribuye al Procurador defender los intereses colectivos, en especial el ambiente. El control fiscal es de la Contraloría, la acción penal de la Fiscalía y los personeros son elegidos por los concejos.","dificultad":1},{"id":"pgn-0010","eje":"pgn","nucleo":"especifico","origen":"estilo","fuente":"Constitución Política, art. 280","enunciado":"Los agentes del Ministerio Público que actúan ante magistrados y jueces tienen","opciones":{"A":"categoría inferior a la del juez, pero igual remuneración.","B":"las calidades de los fiscales delegados ante la misma instancia.","C":"un régimen salarial fijado libremente por el Procurador General.","D":"las mismas calidades, categoría, remuneración, derechos y prestaciones de los magistrados y jueces ante quienes ejercen el cargo."},"correcta":"D","explicacion":"El artículo 280 de la Constitución dispone que los agentes del Ministerio Público tendrán las mismas calidades, categoría, remuneración, derechos y prestaciones de los magistrados y jueces de mayor jerarquía ante quienes ejerzan el cargo.","dificultad":2},{"id":"pgn-0011","eje":"pgn","nucleo":"especifico","origen":"estilo","fuente":"Constitución Política, art. 281","enunciado":"El Defensor del Pueblo","opciones":{"A":"es independiente del Ministerio Público y lo elige el Senado.","B":"forma parte del Ministerio Público, ejerce sus funciones bajo la suprema dirección del Procurador General y es elegido por la Cámara de Representantes.","C":"depende del Ministerio del Interior y lo nombra el Presidente.","D":"es elegido por el Procurador General de terna de la Cámara."},"correcta":"B","explicacion":"El artículo 281 de la Constitución establece que el Defensor del Pueblo forma parte del Ministerio Público, ejerce sus funciones bajo la suprema dirección del Procurador General y es elegido por la Cámara de Representantes para un período de cuatro años, de terna del Presidente.","dificultad":1},{"id":"pgn-0012","eje":"pgn","nucleo":"especifico","origen":"estilo","fuente":"Decreto Ley 262 de 2000, art. 7, num. 3","enunciado":"En ejercicio de la suprema dirección del Ministerio Público, el Procurador General puede","opciones":{"A":"designar a los personeros municipales.","B":"remover libremente al Defensor del Pueblo.","C":"expedir actos y directrices que señalen políticas y criterios orientadores de actuación de la Defensoría del Pueblo en derechos humanos.","D":"revocar las sentencias de tutela proferidas por los jueces."},"correcta":"C","explicacion":"El numeral 3 del artículo 7 del Decreto Ley 262 de 2000 faculta al Procurador para expedir actos, órdenes y directrices que señalen políticas generales y criterios orientadores de la actuación de la Defensoría del Pueblo en derechos humanos. No puede remover al Defensor, revocar tutelas ni designar personeros.","dificultad":3},{"id":"pgn-0013","eje":"pgn","nucleo":"especifico","origen":"estilo","fuente":"Decreto Ley 262 de 2000, art. 7, num. 12","enunciado":"En defensa del orden jurídico, el patrimonio público o los derechos fundamentales, el Procurador General puede solicitar a la Corte Constitucional","opciones":{"A":"la suspensión de leyes en trámite.","B":"la revisión de fallos de tutela.","C":"la nulidad de actos administrativos de carácter general.","D":"la pérdida de investidura de congresistas."},"correcta":"B","explicacion":"El numeral 12 del artículo 7 faculta al Procurador para solicitar ante la Corte Constitucional la revisión de fallos de tutela. La nulidad de actos generales y la pérdida de investidura se tramitan ante el Consejo de Estado, y la Corte no suspende leyes en trámite.","dificultad":2},{"id":"pgn-0014","eje":"pgn","nucleo":"especifico","origen":"estilo","fuente":"Decreto Ley 262 de 2000, art. 7, num. 18","enunciado":"Por razones de orden público, trascendencia social o imparcialidad, el Procurador General puede crear comisiones disciplinarias especiales. En ese caso, el fallo será proferido por quien presida la comisión, que debe ser","opciones":{"A":"el mismo funcionario desplazado.","B":"un particular designado como conjuez.","C":"necesariamente un procurador delegado.","D":"de igual o superior jerarquía que el funcionario desplazado."},"correcta":"D","explicacion":"El numeral 18 del artículo 7 dispone que el fallo será proferido por quien presida la comisión o por el funcionario designado, quien deberá ser de igual o superior jerarquía que el funcionario desplazado.","dificultad":3},{"id":"pgn-0015","eje":"pgn","nucleo":"especifico","origen":"estilo","fuente":"Ley 1952 de 2019, art. 101 (modif. Ley 2094 de 2021, art. 16)","enunciado":"Tras la reforma de la Ley 2094 de 2021, la Procuraduría cuenta con salas disciplinarias encargadas de la instrucción y el juzgamiento de altos servidores. El número de salas es","opciones":{"A":"una por cada procuraduría delegada.","B":"dos.","C":"tres.","D":"cinco."},"correcta":"C","explicacion":"El artículo 101 de la Ley 1952 de 2019, modificado por el artículo 16 de la Ley 2094 de 2021, establece que la Procuraduría contará con tres salas disciplinarias: de instrucción, ordinaria de juzgamiento y de juzgamiento de servidores de elección popular.","dificultad":2},{"id":"pgn-0016","eje":"pgn","nucleo":"especifico","origen":"estilo","fuente":"Ley 1952 de 2019, art. 102 (modif. Ley 2094 de 2021, art. 18)","enunciado":"El Procurador General puede desplazar a quien conoce de un proceso disciplinario por razones de orden público o imparcialidad, pero no puede hacerlo en los procesos contra","opciones":{"A":"servidores públicos de elección popular.","B":"servidores de la propia Procuraduría.","C":"servidores del nivel directivo.","D":"particulares que ejercen funciones públicas."},"correcta":"A","explicacion":"El artículo 102 modificado permite al Procurador asignar o desplazar el conocimiento de un asunto, pero precisa que en ningún caso podrá hacerlo en procesos contra servidores públicos de elección popular.","dificultad":3},{"id":"pgn-0017","eje":"pgn","nucleo":"especifico","origen":"estilo","fuente":"Decreto Ley 262 de 2000, art. 41","enunciado":"Los procuradores judiciales","opciones":{"A":"dependen de la Fiscalía cuando intervienen en procesos penales.","B":"solo intervienen en segunda instancia.","C":"tienen la condición de agentes del Ministerio Público, intervienen ante las autoridades judiciales y en los trámites de conciliación.","D":"son jueces especializados en asuntos disciplinarios."},"correcta":"C","explicacion":"El artículo 41 del Decreto Ley 262 de 2000 dispone que los procuradores judiciales tienen la condición de agentes del Ministerio Público, intervienen ante las autoridades judiciales y en los trámites de conciliación. No son jueces y no dependen de la Fiscalía.","dificultad":1},{"id":"pgn-0018","eje":"pgn","nucleo":"especifico","origen":"estilo","fuente":"Decreto Ley 262 de 2000, art. 37","enunciado":"Además de la intervención judicial, los procuradores judiciales pueden ejercer, cuando lo determine el Procurador General, funciones","opciones":{"A":"de control fiscal sobre los recursos públicos.","B":"de reglamentación de las leyes procesales.","C":"de juzgamiento penal en primera instancia.","D":"preventivas y de control de gestión, disciplinarias y de protección de derechos humanos."},"correcta":"D","explicacion":"El artículo 37 del Decreto Ley 262 de 2000 señala que los procuradores judiciales ejercen funciones preventivas y de control de gestión, disciplinarias, de protección de derechos humanos y de intervención, cuando lo determine el Procurador General.","dificultad":2},{"id":"pgn-0019","eje":"pgn","nucleo":"especifico","origen":"estilo","fuente":"Decreto Ley 262 de 2000, art. 182","enunciado":"Respecto de la clasificación de los empleos de la Procuraduría General de la Nación, la regla general es que","opciones":{"A":"son de carrera, con excepción de los de libre nombramiento y remoción señalados en la norma.","B":"son provisionales hasta que la CNSC convoque concurso.","C":"son de libre nombramiento y remoción, salvo los del nivel asistencial.","D":"son de período fijo de cuatro años."},"correcta":"A","explicacion":"El artículo 182 del Decreto Ley 262 de 2000 dispone que los empleos de la Procuraduría son de carrera, con excepción de los de libre nombramiento y remoción que el mismo artículo enumera. La carrera de la PGN es especial y la administra la propia entidad, no la CNSC.","dificultad":1},{"id":"pgn-0020","eje":"pgn","nucleo":"especifico","origen":"estilo","fuente":"Decreto Ley 262 de 2000, art. 190","enunciado":"Para proveer de forma definitiva un empleo de carrera de la Procuraduría, el primer orden de prioridad corresponde a","opciones":{"A":"el empleado provisional que lleve más tiempo en el cargo.","B":"la persona inscrita en carrera que deba ser trasladada por su condición de desplazada por la violencia o riesgo inminente para su seguridad.","C":"el servidor de carrera con mejor calificación de servicios.","D":"quien ocupe el primer puesto en la lista de elegibles vigente."},"correcta":"B","explicacion":"El artículo 190 fija el orden: primero, el servidor de carrera desplazado o en riesgo; segundo, el reintegrado por orden judicial; tercero, el de carrera con cargo suprimido que optó por la incorporación; y cuarto, el primero de la lista de elegibles vigente.","dificultad":3},{"id":"pgn-0021","eje":"pgn","nucleo":"especifico","origen":"estilo","fuente":"Decreto Ley 262 de 2000, art. 188","enunciado":"El encargo y el nombramiento provisional en vacancia definitiva de un cargo de carrera de la Procuraduría pueden hacerse hasta por","opciones":{"A":"seis meses, prorrogables por un período igual.","B":"un año, sin prórroga.","C":"tres meses, prorrogables una vez.","D":"cuatro años, término del período del Procurador."},"correcta":"A","explicacion":"El artículo 188 del Decreto Ley 262 de 2000 dispone que el encargo y la provisionalidad podrán hacerse hasta por seis meses, prorrogables por un período igual; si no ha culminado el proceso de selección, pueden extenderse hasta que culmine.","dificultad":2},{"id":"pgn-0022","eje":"pgn","nucleo":"especifico","origen":"estilo","fuente":"Decreto Ley 262 de 2000, art. 192","enunciado":"El concurso de la Procuraduría debe convocarse como de ascenso cuando existan en la entidad, por lo menos,","opciones":{"A":"tres empleados de carrera con calificación sobresaliente.","B":"diez empleados provisionales en el mismo nivel.","C":"dos empleados de carrera por cada vacante.","D":"cinco empleados inscritos en carrera que cumplan los requisitos para ascender."},"correcta":"D","explicacion":"El artículo 192 dispone que el concurso debe convocarse de ascenso cuando existan por lo menos cinco empleados inscritos en carrera que cumplan los requisitos para ascender, según certificación de la División de Gestión Humana.","dificultad":2},{"id":"pgn-0023","eje":"pgn","nucleo":"especifico","origen":"estilo","fuente":"Decreto Ley 262 de 2000, art. 203","enunciado":"En los procesos de selección de la Procuraduría, la prueba que siempre es obligatoria es","opciones":{"A":"la prueba de ejecución.","B":"la entrevista.","C":"el análisis de antecedentes.","D":"la prueba psicotécnica."},"correcta":"C","explicacion":"El artículo 203 establece que la prueba de análisis de antecedentes es obligatoria y que se aplicarán como mínimo dos pruebas más, de las cuales al menos una será eliminatoria y una deberá ser escrita.","dificultad":2},{"id":"pgn-0024","eje":"pgn","nucleo":"especifico","origen":"estilo","fuente":"Decreto Ley 262 de 2000, art. 204","enunciado":"Cuando en un concurso de la Procuraduría se programa entrevista, esta","opciones":{"A":"es eliminatoria y vale el treinta por ciento.","B":"no puede valer más del veinte por ciento de la calificación definitiva y nunca es eliminatoria.","C":"reemplaza la prueba de conocimientos.","D":"la califica un solo evaluador designado por el jefe del área."},"correcta":"B","explicacion":"El artículo 204 dispone que la entrevista no podrá tener un valor superior al veinte por ciento de la calificación definitiva y nunca será eliminatoria; el jurado lo integran mínimo tres personas.","dificultad":2},{"id":"pgn-0025","eje":"pgn","nucleo":"especifico","origen":"estilo","fuente":"Decreto Ley 262 de 2000, art. 208","enunciado":"Las pruebas aplicadas o por utilizar en los procesos de selección de la Procuraduría","opciones":{"A":"pueden ser solicitadas por cualquier ciudadano mediante derecho de petición.","B":"tienen carácter reservado y solo las conocen los responsables de su elaboración y aplicación, los concursantes al momento de presentarlas y la Comisión de Carrera cuando investigue.","C":"se entregan a los aspirantes una semana antes para su estudio.","D":"son públicas una vez aplicadas y deben publicarse en la página web."},"correcta":"B","explicacion":"El artículo 208 del Decreto Ley 262 de 2000 dispone que las pruebas tienen carácter reservado. Por eso casi no existen preguntas oficiales públicas de concursos anteriores de la PGN.","dificultad":1},{"id":"pgn-0026","eje":"pgn","nucleo":"especifico","origen":"estilo","fuente":"Decreto Ley 262 de 2000, art. 216; Resolución 076 de 2026","enunciado":"Para integrar la lista de elegibles en un concurso de la Procuraduría, el concursante debe obtener un puntaje total","opciones":{"A":"igual o superior al ochenta por ciento del máximo posible.","B":"igual o superior a sesenta y cinco puntos en la prueba de conocimientos, sin importar el total.","C":"igual o superior al setenta por ciento del máximo posible.","D":"superior al promedio de los concursantes."},"correcta":"C","explicacion":"El artículo 216 del Decreto Ley 262 de 2000 exige un puntaje total igual o superior al setenta por ciento del máximo posible para integrar la lista de elegibles. Los 65 puntos son el mínimo para aprobar la prueba de conocimientos, que es solo una etapa eliminatoria.","dificultad":2},{"id":"pgn-0027","eje":"pgn","nucleo":"especifico","origen":"estilo","fuente":"Decreto Ley 262 de 2000, art. 218","enunciado":"La persona seleccionada por concurso abierto, no inscrita en carrera, será nombrada en período de prueba por un término de","opciones":{"A":"seis meses.","B":"un año.","C":"dos meses.","D":"cuatro meses."},"correcta":"D","explicacion":"El artículo 218 del Decreto Ley 262 de 2000 establece un período de prueba de cuatro meses, al cabo del cual se evalúa el desempeño laboral. El régimen general de la Ley 909 de 2004 prevé seis meses, pero la PGN tiene régimen especial.","dificultad":2},{"id":"pgn-0028","eje":"pgn","nucleo":"especifico","origen":"estilo","fuente":"Decreto Ley 262 de 2000, art. 217","enunciado":"Publicada la lista de elegibles, el nombramiento en período de prueba o en propiedad debe producirse dentro de los","opciones":{"A":"veinte días hábiles siguientes, salvo lo previsto sobre el orden de prioridad.","B":"seis meses siguientes.","C":"treinta días hábiles siguientes a la firmeza de la lista.","D":"diez días calendario siguientes."},"correcta":"A","explicacion":"El artículo 217 del Decreto Ley 262 de 2000 dispone que dentro de los veinte días hábiles siguientes a la publicación de la lista de elegibles deberá producirse el nombramiento, salvo lo previsto en el artículo 190.","dificultad":3},{"id":"proc-0001","eje":"proc-disciplinario","nucleo":"especifico","origen":"estilo","fuente":"Ley 1952 de 2019, art. 208 (modif. Ley 2094 de 2021, art. 34)","enunciado":"Llega a una oficina de control interno disciplinario un informe sobre pérdida de documentos, pero no se sabe qué servidor los tenía a cargo. La actuación que procede es","opciones":{"A":"la indagación previa, para identificar o individualizar al posible autor.","B":"la citación a audiencia y formulación de cargos.","C":"la apertura de investigación disciplinaria contra el jefe de la dependencia.","D":"el archivo inmediato por falta de autor conocido."},"correcta":"A","explicacion":"El artículo 208 dispone que en caso de duda sobre la identificación o individualización del posible autor se adelantará indagación previa. No puede abrirse investigación contra alguien sin elementos que lo identifiquen, ni archivarse sin agotar la indagación, y los cargos son muy posteriores.","dificultad":1},{"id":"proc-0002","eje":"proc-disciplinario","nucleo":"especifico","origen":"estilo","fuente":"Ley 1952 de 2019, art. 208 (modif. Ley 2094 de 2021, art. 34)","enunciado":"La indagación previa en el proceso disciplinario tiene una duración de","opciones":{"A":"doce meses en todos los casos.","B":"seis meses, prorrogables hasta en dieciocho meses más para faltas gravísimas.","C":"tres meses, prorrogables por una sola vez.","D":"seis meses, extensible a otros seis cuando se investigan violaciones a derechos humanos o al DIH."},"correcta":"D","explicacion":"Según el artículo 208 modificado, la indagación previa dura seis meses y culmina con archivo o apertura de investigación; en investigaciones por violación de derechos humanos o DIH puede extenderse otros seis meses.","dificultad":2},{"id":"proc-0003","eje":"proc-disciplinario","nucleo":"especifico","origen":"estilo","fuente":"Ley 1952 de 2019, art. 213 (modif. Ley 2094 de 2021, art. 36)","enunciado":"Se abrió investigación disciplinaria contra tres servidores de una gobernación por varias faltas. El término de la investigación es","opciones":{"A":"dieciocho meses, por la pluralidad de investigados.","B":"doce meses improrrogables.","C":"seis meses, prorrogable hasta en otro tanto por tratarse de varios investigados y faltas.","D":"tres meses, prorrogables por tres más."},"correcta":"C","explicacion":"El artículo 213 fija seis meses desde la apertura, prorrogables hasta en otro tanto cuando se investigan varias faltas o a dos o más servidores. Los dieciocho meses son el máximo para infracciones a derechos humanos o DIH.","dificultad":2},{"id":"proc-0004","eje":"proc-disciplinario","nucleo":"especifico","origen":"estilo","fuente":"Ley 1952 de 2019, art. 213 (modif. Ley 2094 de 2021, art. 36)","enunciado":"Cuando se investiga una infracción al Derecho Internacional de los Derechos Humanos, el término de la investigación disciplinaria no podrá exceder de","opciones":{"A":"seis meses.","B":"dieciocho meses.","C":"doce meses.","D":"veinticuatro meses."},"correcta":"B","explicacion":"El inciso segundo del artículo 213, modificado por la Ley 2094 de 2021, establece que en investigaciones por infracción al Derecho Internacional de los Derechos Humanos o al DIH el término no podrá exceder de dieciocho meses.","dificultad":2},{"id":"proc-0005","eje":"proc-disciplinario","nucleo":"especifico","origen":"estilo","fuente":"Ley 1952 de 2019, art. 220","enunciado":"Recaudadas las pruebas de la investigación, el funcionario declara cerrada la investigación. A continuación debe","opciones":{"A":"formular de inmediato el pliego de cargos.","B":"remitir el expediente al funcionario de juzgamiento.","C":"correr traslado por diez días para alegatos precalificatorios.","D":"citar a audiencia de descargos."},"correcta":"C","explicacion":"El artículo 220 ordena que, cerrada la investigación, se corra traslado por diez días para que los sujetos procesales presenten alegatos previos a la evaluación. Solo después se decide si se formulan cargos o se archiva (art. 221).","dificultad":2},{"id":"proc-0006","eje":"proc-disciplinario","nucleo":"especifico","origen":"estilo","fuente":"Ley 1952 de 2019, art. 221 (modif. Ley 2094 de 2021, art. 38)","enunciado":"En la decisión de evaluación de la investigación disciplinaria, el funcionario de conocimiento","opciones":{"A":"resuelve el recurso de apelación contra el auto de apertura.","B":"impone la sanción si encuentra probada la falta.","C":"decide si el juicio será verbal u ordinario.","D":"formula pliego de cargos o termina la actuación y ordena el archivo."},"correcta":"D","explicacion":"El artículo 221 establece que, mediante decisión motivada, el funcionario evalúa las pruebas y formula pliego de cargos o termina la actuación y archiva. La sanción solo se impone en el fallo, y la elección del juicio la hace el funcionario de juzgamiento (art. 225A).","dificultad":1},{"id":"proc-0007","eje":"proc-disciplinario","nucleo":"especifico","origen":"estilo","fuente":"Ley 1952 de 2019, art. 12 (modif. Ley 2094 de 2021, art. 3)","enunciado":"Una de las garantías incorporadas por la Ley 2094 de 2021 al debido proceso disciplinario es que","opciones":{"A":"el funcionario instructor no sea el mismo que adelante el juzgamiento.","B":"todas las decisiones sean consultadas al superior.","C":"la investigación la adelante siempre la Procuraduría.","D":"el disciplinable sea juzgado por un jurado de conciencia."},"correcta":"A","explicacion":"El artículo 12 modificado dispone que el disciplinable será investigado y luego juzgado por funcionario diferente, y que debe garantizarse que el instructor no sea el mismo que adelante el juzgamiento. Las demás alternativas no están previstas en la norma.","dificultad":1},{"id":"proc-0008","eje":"proc-disciplinario","nucleo":"especifico","origen":"estilo","fuente":"Ley 1952 de 2019, arts. 12 y 102 (modif. Ley 2094 de 2021)","enunciado":"Si el primer fallo sancionatorio en un proceso disciplinario lo profiere el Procurador General de la Nación, la doble conformidad se resuelve por","opciones":{"A":"el Viceprocurador General de la Nación.","B":"una sala de tres personas que cumplan los requisitos del artículo 232 de la Constitución, sorteadas de una lista de doce nombres.","C":"la Sala de Consulta y Servicio Civil del Consejo de Estado.","D":"la Comisión Nacional de Disciplina Judicial."},"correcta":"B","explicacion":"El artículo 102 modificado prevé que la doble conformidad de las decisiones sancionatorias del Procurador General se resuelva por una sala de tres personas con los requisitos del artículo 232 de la Constitución, sorteadas de una lista de doce nombres.","dificultad":3},{"id":"proc-0009","eje":"proc-disciplinario","nucleo":"especifico","origen":"estilo","fuente":"Ley 1952 de 2019, art. 121 (modif. Ley 2094 de 2021, art. 20)","enunciado":"Según el Código General Disciplinario, debe notificarse personalmente","opciones":{"A":"la decisión que ordena incorporar un documento.","B":"el auto que reconoce personería a un defensor.","C":"el pliego de cargos.","D":"el auto que fija fecha para una diligencia de testimonio."},"correcta":"C","explicacion":"El artículo 121 dispone que se notifican personalmente los autos de apertura de investigación, de vinculación, el pliego de cargos y su variación, y los fallos de instancia. Las demás son decisiones de sustanciación que se comunican (art. 129).","dificultad":1},{"id":"proc-0010","eje":"proc-disciplinario","nucleo":"especifico","origen":"estilo","fuente":"Ley 1952 de 2019, art. 131 (modif. Ley 2094 de 2021, art. 25)","enunciado":"Un fallo de primera instancia en procedimiento ordinario se notificó personalmente el lunes. Para recursos distintos a la apelación del fallo, la regla general del Código es que la reposición y la apelación se interponen","opciones":{"A":"desde la expedición de la decisión hasta el vencimiento de los cinco días siguientes a la notificación.","B":"dentro de los diez días siguientes a la expedición de la decisión.","C":"únicamente en la audiencia en que se profirió la decisión.","D":"dentro de los tres días siguientes a la ejecutoria."},"correcta":"A","explicacion":"El artículo 131 fija como regla general que la reposición y la apelación se interponen desde la expedición hasta cinco días después de la notificación. Solo si la notificación es en estrados deben interponerse en la audiencia.","dificultad":2},{"id":"proc-0011","eje":"proc-disciplinario","nucleo":"especifico","origen":"estilo","fuente":"Ley 1952 de 2019, art. 225G (adic. Ley 2094 de 2021, art. 46)","enunciado":"En el juicio ordinario disciplinario, el recurso de apelación contra el fallo de primera instancia debe interponerse y sustentarse","opciones":{"A":"verbalmente en la misma audiencia de lectura del fallo.","B":"dentro de los cinco días siguientes a la ejecutoria.","C":"dentro de los treinta días hábiles siguientes al fallo.","D":"por escrito dentro de los diez días siguientes a su notificación."},"correcta":"D","explicacion":"El artículo 225G, adicionado por la Ley 2094 de 2021, dispone que en el juicio ordinario la apelación contra el fallo se interpone y sustenta por escrito dentro de los diez días siguientes a la notificación. La interposición en la misma diligencia corresponde al juicio verbal (art. 233).","dificultad":3},{"id":"proc-0012","eje":"proc-disciplinario","nucleo":"especifico","origen":"estilo","fuente":"Ley 1952 de 2019, art. 135","enunciado":"El disciplinado, único apelante, recurre un fallo que le impuso suspensión de seis meses. Al resolver, el superior considera que la falta merecía destitución. El superior","opciones":{"A":"puede imponer la destitución si lo motiva adecuadamente.","B":"no puede agravar la sanción, por la prohibición de la reformatio in pejus.","C":"debe anular el fallo y devolver para nueva calificación.","D":"puede aumentar la suspensión hasta dieciocho meses."},"correcta":"B","explicacion":"El artículo 135 prohíbe al superior agravar la sanción cuando el investigado es apelante único. Cualquier aumento, sea destitución o mayor suspensión, desconoce esa garantía.","dificultad":1},{"id":"proc-0013","eje":"proc-disciplinario","nucleo":"especifico","origen":"estilo","fuente":"Ley 1952 de 2019, art. 136","enunciado":"El funcionario de primera instancia rechazó el recurso de apelación interpuesto por el defensor. Contra esa decisión procede","opciones":{"A":"la revocatoria directa.","B":"el recurso de queja.","C":"la consulta.","D":"el recurso de reposición."},"correcta":"B","explicacion":"El artículo 136 señala que el recurso de queja procede contra la decisión que rechaza el recurso de apelación; se interpone dentro del término de ejecutoria de esa decisión (art. 137).","dificultad":1},{"id":"proc-0014","eje":"proc-disciplinario","nucleo":"especifico","origen":"estilo","fuente":"Ley 1952 de 2019, art. 133 (modif. Ley 2094 de 2021, art. 27)","enunciado":"Durante la etapa de investigación, el funcionario niega las pruebas solicitadas por el disciplinable. Contra esa decisión procede","opciones":{"A":"el recurso de reposición.","B":"ningún recurso, por ser decisión de trámite.","C":"el recurso de apelación en el efecto suspensivo.","D":"el recurso de queja."},"correcta":"A","explicacion":"El artículo 133 modificado incluye entre las decisiones susceptibles de reposición la que niega las pruebas en la etapa de investigación. La apelación procede contra la que niega pruebas en la etapa de juicio (art. 134).","dificultad":2},{"id":"proc-0015","eje":"proc-disciplinario","nucleo":"especifico","origen":"estilo","fuente":"Ley 1952 de 2019, art. 134","enunciado":"El recurso de apelación procede únicamente contra","opciones":{"A":"todas las decisiones interlocutorias y los fallos.","B":"los fallos sancionatorios, pero no los absolutorios.","C":"la decisión que niega pruebas en juicio, la de archivo, la que finaliza el trámite del testigo renuente o el quejoso temerario y el fallo de primera instancia.","D":"el auto de apertura de investigación y el pliego de cargos."},"correcta":"C","explicacion":"El artículo 134 enumera taxativamente las decisiones apelables: la que niega pruebas en juicio, la decisión de archivo, la que finaliza el procedimiento para el testigo renuente y el quejoso temerario, y el fallo de primera instancia. Contra el pliego de cargos no procede recurso (art. 222).","dificultad":2},{"id":"proc-0016","eje":"proc-disciplinario","nucleo":"especifico","origen":"estilo","fuente":"Ley 1952 de 2019, art. 225A (adic. Ley 2094 de 2021, art. 40)","enunciado":"Un servidor es sorprendido por su jefe en el momento en que sustrae dinero de la caja menor. Recibido el expediente con el pliego de cargos, el funcionario de juzgamiento debe adelantar, por regla general,","opciones":{"A":"el juicio ordinario.","B":"el procedimiento abreviado de la Ley 1437 de 2011.","C":"la indagación previa.","D":"el juicio verbal."},"correcta":"D","explicacion":"El artículo 225A dispone que el juicio verbal se adelanta cuando el disciplinable es sorprendido en el momento de la comisión de la falta o con elementos provenientes de ella. Solo por complejidad u otras razones motivadas puede optarse por el ordinario.","dificultad":2},{"id":"proc-0017","eje":"proc-disciplinario","nucleo":"especifico","origen":"estilo","fuente":"Ley 1952 de 2019, art. 225A (adic. Ley 2094 de 2021, art. 40)","enunciado":"Contra el auto de sustanciación que decide si el juzgamiento se adelanta por juicio ordinario o verbal","opciones":{"A":"procede apelación en el efecto devolutivo.","B":"no procede recurso alguno.","C":"procede queja.","D":"procede reposición."},"correcta":"B","explicacion":"El artículo 225A, adicionado por la Ley 2094 de 2021, establece expresamente que contra la decisión que fija el juzgamiento a seguir no procede recurso alguno.","dificultad":2},{"id":"proc-0018","eje":"proc-disciplinario","nucleo":"especifico","origen":"estilo","fuente":"Ley 1952 de 2019, art. 225B (adic. Ley 2094 de 2021, art. 41)","enunciado":"En el juicio ordinario, el auto que dispone aplicar ese procedimiento deja el expediente a disposición de los sujetos procesales para presentar descargos y solicitar pruebas por","opciones":{"A":"cinco días.","B":"diez días.","C":"quince días.","D":"treinta días."},"correcta":"C","explicacion":"El artículo 225B dispone que el expediente quedará en secretaría por quince días para que los sujetos procesales presenten descargos y aporten o soliciten pruebas; la renuencia a presentarlos no interrumpe el trámite.","dificultad":2},{"id":"proc-0019","eje":"proc-disciplinario","nucleo":"especifico","origen":"estilo","fuente":"Ley 1952 de 2019, art. 225C (adic. Ley 2094 de 2021, art. 42)","enunciado":"En el juicio ordinario, las pruebas decretadas deben practicarse en un término no mayor de","opciones":{"A":"noventa días.","B":"treinta días hábiles.","C":"seis meses.","D":"veinte días prorrogables por otros veinte."},"correcta":"A","explicacion":"El artículo 225C fija un término no mayor de noventa días para practicar las pruebas en el juicio ordinario. El término de veinte días prorrogables corresponde al juicio verbal (art. 227).","dificultad":2},{"id":"proc-0020","eje":"proc-disciplinario","nucleo":"especifico","origen":"estilo","fuente":"Ley 1952 de 2019, art. 227 (modif. Ley 2094 de 2021, art. 48)","enunciado":"En el juicio verbal, la práctica de pruebas se adelantará hasta por","opciones":{"A":"dos meses prorrogables.","B":"noventa días improrrogables.","C":"diez días, sin prórroga.","D":"veinte días, prorrogables por una sola vez hasta por el mismo lapso."},"correcta":"D","explicacion":"El artículo 227 modificado señala que en el juicio verbal las pruebas se practican hasta por veinte días, prorrogables una sola vez por el mismo lapso mediante decisión motivada. Los noventa días son propios del juicio ordinario.","dificultad":2},{"id":"proc-0021","eje":"proc-disciplinario","nucleo":"especifico","origen":"estilo","fuente":"Ley 1952 de 2019, art. 162 (modif. Ley 2094 de 2021, art. 30)","enunciado":"Un disciplinable acepta los cargos durante la etapa de investigación por una falta grave. Como beneficio, la sanción de suspensión","opciones":{"A":"se convertirá en amonestación escrita.","B":"se disminuirá hasta la mitad.","C":"no tiene reducción, porque solo procede en juzgamiento.","D":"se reducirá en una tercera parte."},"correcta":"B","explicacion":"El artículo 162 dispone que si la confesión o aceptación de cargos se produce en la investigación, las sanciones de inhabilidad, suspensión o multa se disminuirán hasta la mitad; si es en juzgamiento, se reducen en una tercera parte.","dificultad":2},{"id":"proc-0022","eje":"proc-disciplinario","nucleo":"especifico","origen":"estilo","fuente":"Ley 1952 de 2019, art. 162 (modif. Ley 2094 de 2021, art. 30)","enunciado":"El beneficio de reducción de la sanción por confesión o aceptación de cargos no se aplica cuando se trate de","opciones":{"A":"faltas cometidas por particulares.","B":"faltas cometidas por servidores del nivel directivo.","C":"las faltas gravísimas del artículo 52, relacionadas con derechos humanos y DIH.","D":"faltas graves dolosas."},"correcta":"C","explicacion":"El artículo 162 excluye expresamente el beneficio cuando se trate de las faltas gravísimas del artículo 52, que corresponden a infracciones al Derecho Internacional de los Derechos Humanos y al DIH.","dificultad":2},{"id":"proc-0023","eje":"proc-disciplinario","nucleo":"especifico","origen":"estilo","fuente":"Ley 1952 de 2019, art. 161 (modif. Ley 2094 de 2021, art. 29)","enunciado":"Para que la aceptación de cargos sea válida, el Código General Disciplinario exige, entre otros requisitos, que","opciones":{"A":"la persona esté asistida por defensor.","B":"el quejoso manifieste su conformidad.","C":"se haga después de notificado el fallo.","D":"se presente por escrito ante el nominador."},"correcta":"A","explicacion":"El artículo 161 exige que la confesión o aceptación se haga ante la autoridad competente, con asistencia de defensor, informando al disciplinable sus garantías y verificando que sea voluntaria, consciente, libre, espontánea e informada.","dificultad":1},{"id":"proc-0024","eje":"proc-disciplinario","nucleo":"especifico","origen":"estilo","fuente":"Ley 1952 de 2019, art. 217","enunciado":"Durante una investigación por falta gravísima hay serios elementos de juicio de que el investigado, desde su cargo, está alterando los archivos que son prueba del proceso. El funcionario puede","opciones":{"A":"trasladarlo de sede sin decisión motivada.","B":"suspenderlo provisionalmente con remuneración por un año.","C":"destituirlo de inmediato, por la gravedad de la falta.","D":"ordenar motivadamente la suspensión provisional del servidor, sin remuneración, por tres meses prorrogables."},"correcta":"D","explicacion":"El artículo 217 permite la suspensión provisional, sin remuneración, cuando la permanencia en el cargo posibilite interferir en la investigación o continuar la falta. Dura tres meses, prorrogables hasta en otro tanto, y es objeto de consulta. La destitución solo procede en el fallo.","dificultad":2},{"id":"proc-0025","eje":"proc-disciplinario","nucleo":"especifico","origen":"estilo","fuente":"Ley 1952 de 2019, art. 218","enunciado":"Un servidor suspendido provisionalmente es absuelto en el fallo. Según el Código General Disciplinario","opciones":{"A":"solo tendrá derecho al pago de la mitad de los salarios.","B":"será reintegrado, pero sin pago de salarios.","C":"será reintegrado y se le pagará la remuneración dejada de percibir durante la suspensión.","D":"deberá demandar ante lo contencioso para obtener el reintegro."},"correcta":"C","explicacion":"El artículo 218 dispone que el suspendido provisionalmente será reintegrado y tendrá derecho al pago de la remuneración dejada de percibir cuando la investigación termine con fallo absolutorio, archivo o terminación del proceso.","dificultad":1},{"id":"proc-0026","eje":"proc-disciplinario","nucleo":"especifico","origen":"estilo","fuente":"Ley 1952 de 2019, art. 202","enunciado":"Es causal de nulidad en el proceso disciplinario","opciones":{"A":"la violación del derecho de defensa del investigado.","B":"el desistimiento del quejoso.","C":"la falta de firma del quejoso en la queja.","D":"el error en el nombre de la entidad en el fallo."},"correcta":"A","explicacion":"El artículo 202 señala como causales de nulidad la falta de competencia para proferir el fallo, la violación del derecho de defensa y las irregularidades sustanciales que afecten el debido proceso. El error en el nombre de la entidad se corrige (art. 140).","dificultad":1},{"id":"proc-0027","eje":"proc-disciplinario","nucleo":"especifico","origen":"estilo","fuente":"Ley 1952 de 2019, art. 206 (modif. Ley 2094 de 2021, art. 32)","enunciado":"La solicitud de nulidad en el proceso disciplinario puede formularse","opciones":{"A":"únicamente dentro de la etapa de investigación.","B":"hasta antes de dar traslado para alegatos de conclusión.","C":"solo dentro de los cinco días siguientes a la notificación del pliego.","D":"en cualquier momento, incluso después del fallo de segunda instancia."},"correcta":"B","explicacion":"El artículo 206 modificado permite formular la solicitud de nulidad hasta antes de dar traslado para alegatos de conclusión, indicando la causal y sus fundamentos de hecho y de derecho.","dificultad":2},{"id":"proc-0028","eje":"proc-disciplinario","nucleo":"especifico","origen":"estilo","fuente":"Ley 1952 de 2019, art. 141 (modif. Ley 2094 de 2021, art. 28)","enunciado":"La Procuraduría puede revocar, de oficio o a petición del quejoso o de las víctimas, un fallo absolutorio o el archivo de la actuación cuando","opciones":{"A":"el quejoso no esté conforme con la decisión, en cualquier tipo de falta.","B":"lo solicite el superior jerárquico del disciplinado.","C":"hayan transcurrido más de cinco años desde el archivo.","D":"se trate de faltas que constituyan infracciones al Derecho Internacional de los Derechos Humanos o al DIH."},"correcta":"D","explicacion":"El artículo 141 modificado permite revocar el fallo absolutorio o el archivo solo cuando se trate de infracciones al Derecho Internacional de los Derechos Humanos y al DIH; quejoso y víctimas pueden pedirlo dentro de los cuatro meses siguientes a conocer la decisión.","dificultad":3},{"id":"tra-0001","eje":"transparencia","nucleo":"general","origen":"estilo","fuente":"Ley 1712 de 2014, art. 2","enunciado":"Según el principio de máxima publicidad de la Ley 1712 de 2014, toda información en posesión, bajo control o custodia de un sujeto obligado","opciones":{"A":"es reservada mientras el jefe de la entidad no autorice su divulgación.","B":"es pública y solo puede ser reservada o limitada por disposición constitucional o legal.","C":"es pública únicamente para quien acredite interés directo.","D":"es pública solo después de cinco años de producida."},"correcta":"B","explicacion":"El artículo 2 de la Ley 1712 de 2014 consagra el principio de máxima publicidad para titular universal: la información es pública y solo puede reservarse o limitarse por disposición constitucional o legal. No se exige acreditar interés ni autorización del jefe de la entidad.","dificultad":1},{"id":"tra-0002","eje":"transparencia","nucleo":"general","origen":"estilo","fuente":"Ley 1712 de 2014, art. 5","enunciado":"Una empresa privada que presta el servicio de acueducto recibe una solicitud de información sobre la calidad del agua que suministra. Respecto de la Ley 1712 de 2014, la empresa","opciones":{"A":"es sujeto obligado respecto de la información directamente relacionada con la prestación del servicio público.","B":"es sujeto obligado respecto de toda su información, incluida la comercial reservada.","C":"solo debe responder si la solicitud la presenta la Superintendencia.","D":"no es sujeto obligado, por ser persona jurídica privada."},"correcta":"A","explicacion":"El literal c del artículo 5 incluye como sujetos obligados a las personas privadas que presten servicios públicos, respecto de la información directamente relacionada con la prestación del servicio. No cubre toda su información, y la solicitud puede hacerla cualquier persona.","dificultad":2},{"id":"tra-0003","eje":"transparencia","nucleo":"general","origen":"estilo","fuente":"Ley 1712 de 2014, art. 6, lits. c y d","enunciado":"La información que, estando en poder de un sujeto obligado, pertenece al ámbito propio, particular y privado o semiprivado de una persona natural o jurídica, se denomina","opciones":{"A":"información pública reservada.","B":"dato abierto.","C":"información pública de divulgación proactiva.","D":"información pública clasificada."},"correcta":"D","explicacion":"El literal c del artículo 6 define la información pública clasificada como la que pertenece al ámbito propio, particular, privado o semiprivado de una persona. La reservada es la exceptuada por daño a intereses públicos (art. 19).","dificultad":2},{"id":"tra-0004","eje":"transparencia","nucleo":"general","origen":"estilo","fuente":"Ley 1712 de 2014, art. 22","enunciado":"La reserva de la información exceptuada por daño a los intereses públicos, como la defensa y seguridad nacional, no puede extenderse por un período mayor a","opciones":{"A":"treinta años.","B":"cinco años.","C":"quince años.","D":"diez años."},"correcta":"C","explicacion":"El artículo 22 de la Ley 1712 de 2014 dispone que la reserva de las informaciones amparadas por el artículo 19 no deberá extenderse por un período mayor a quince años.","dificultad":2},{"id":"tra-0005","eje":"transparencia","nucleo":"general","origen":"estilo","fuente":"Ley 1712 de 2014, art. 21","enunciado":"Un documento contiene en su mayoría información pública y en una parte datos protegidos por reserva legal. El sujeto obligado debe","opciones":{"A":"exigir al solicitante que justifique su interés.","B":"elaborar una versión pública que mantenga la reserva solo de la parte indispensable.","C":"negar la totalidad del documento.","D":"entregar el documento completo, porque prevalece la publicidad."},"correcta":"B","explicacion":"El artículo 21 ordena que, cuando no toda la información de un documento esté protegida, se haga una versión pública que mantenga la reserva únicamente de la parte indispensable y se entregue lo demás.","dificultad":1},{"id":"tra-0006","eje":"transparencia","nucleo":"general","origen":"estilo","fuente":"Ley 1712 de 2014, art. 21","enunciado":"Una entidad niega información sobre presuntas ejecuciones extrajudiciales invocando reserva legal. Según la Ley 1712 de 2014","opciones":{"A":"las excepciones de acceso no aplican en casos de violación de derechos humanos o delitos de lesa humanidad.","B":"la información solo puede entregarse por orden de la Fiscalía.","C":"la reserva se levanta automáticamente a los cinco años.","D":"la reserva prevalece siempre sobre el interés de las víctimas."},"correcta":"A","explicacion":"El inciso tercero del artículo 21 dispone que las excepciones de acceso no aplican en casos de violación de derechos humanos o delitos de lesa humanidad, y que deben protegerse los derechos de las víctimas.","dificultad":2},{"id":"tra-0007","eje":"transparencia","nucleo":"general","origen":"estilo","fuente":"Ley 1712 de 2014, art. 25, parágrafo","enunciado":"Una solicitud de acceso a la información está redactada de forma confusa y no explica para qué se quiere la información. La entidad","opciones":{"A":"debe responder solo si el solicitante acredita interés legítimo.","B":"debe rechazarla de plano por falta de motivación.","C":"puede exigir que se presente nuevamente por medio de abogado.","D":"no puede rechazarla por fundamentación inadecuada o incompleta."},"correcta":"D","explicacion":"El parágrafo del artículo 25 dispone que en ningún caso podrá rechazarse la petición por motivos de fundamentación inadecuada o incompleta. La solicitud puede ser oral o escrita, incluso por vía electrónica.","dificultad":1},{"id":"tra-0008","eje":"transparencia","nucleo":"general","origen":"estilo","fuente":"Ley 1712 de 2014, art. 26","enunciado":"Respecto del costo de la respuesta a una solicitud de acceso a información pública, la Ley 1712 de 2014 establece que","opciones":{"A":"es gratuita solo para personas de estratos 1 y 2.","B":"la entidad puede cobrar una tarifa por el tiempo de búsqueda.","C":"será gratuita o sujeta a un costo que no supere el valor de la reproducción y envío.","D":"siempre tiene un costo fijado anualmente por el Ministerio de Hacienda."},"correcta":"C","explicacion":"El artículo 26 dispone que la respuesta será gratuita o sujeta a un costo que no supere el valor de la reproducción y envío, y que se preferirá la respuesta electrónica con consentimiento del solicitante.","dificultad":1},{"id":"tra-0009","eje":"transparencia","nucleo":"general","origen":"estilo","fuente":"Ley 1712 de 2014, art. 28","enunciado":"En una controversia sobre si cierta información debe permanecer reservada, la carga de probar que la reserva procede corresponde a","opciones":{"A":"el sujeto obligado.","B":"el juez de tutela, de oficio.","C":"el solicitante.","D":"el Ministerio Público."},"correcta":"A","explicacion":"El artículo 28 asigna al sujeto obligado la carga de aportar las razones y pruebas que fundamenten que la información debe permanecer reservada o confidencial y su relación con un objetivo legítimo.","dificultad":1},{"id":"tra-0010","eje":"transparencia","nucleo":"general","origen":"estilo","fuente":"Ley 1712 de 2014, art. 23","enunciado":"La entidad encargada de velar por el adecuado cumplimiento de las obligaciones de la Ley 1712 de 2014 es","opciones":{"A":"el Archivo General de la Nación, exclusivamente.","B":"la Superintendencia de Industria y Comercio.","C":"la Contraloría General de la República.","D":"el Ministerio Público."},"correcta":"D","explicacion":"El artículo 23 asigna al Ministerio Público velar por el cumplimiento de la ley, con base en la metodología que defina la Procuraduría. El Archivo General participa en estándares documentales, pero no tiene esa función de vigilancia.","dificultad":1},{"id":"tra-0011","eje":"transparencia","nucleo":"general","origen":"estilo","fuente":"Ley 1712 de 2014, art. 4, parágrafo","enunciado":"Una ciudadana teme represalias si pide información sobre contratos de su municipio. Según la Ley 1712 de 2014, puede","opciones":{"A":"pedir a la Fiscalía que formule la solicitud en su nombre.","B":"solicitar ante el Ministerio Público el procedimiento especial de solicitud con identificación reservada.","C":"presentar la solicitud por medio de un concejal.","D":"pedir la información sin identificarse, y la entidad debe responder en el diario oficial."},"correcta":"B","explicacion":"El parágrafo del artículo 4 permite que, cuando el usuario considere que la solicitud pone en riesgo su integridad o la de su familia, solicite ante el Ministerio Público el procedimiento especial de solicitud con identificación reservada.","dificultad":2},{"id":"tra-0012","eje":"transparencia","nucleo":"general","origen":"estilo","fuente":"Ley 1712 de 2014, art. 27","enunciado":"Cuando la respuesta a una solicitud invoca la reserva de seguridad y defensa nacional o relaciones internacionales, el solicitante puede interponer recurso de reposición","opciones":{"A":"únicamente de forma verbal ante el personero.","B":"dentro de los diez días siguientes, como en el CPACA.","C":"por escrito y sustentado en la diligencia de notificación o dentro de los tres días siguientes.","D":"dentro del mes siguiente a la respuesta."},"correcta":"C","explicacion":"El artículo 27 fija un término especial: el recurso de reposición se interpone por escrito y sustentado en la diligencia de notificación o dentro de los tres días siguientes; si se mantiene la reserva, el asunto se remite al juez para que decida.","dificultad":3},{"id":"tra-0013","eje":"transparencia","nucleo":"general","origen":"estilo","fuente":"Ley 1712 de 2014, art. 29","enunciado":"Un funcionario destruye deliberadamente un informe después de que un ciudadano lo solicitó. Según la Ley 1712 de 2014, esa conducta","opciones":{"A":"será sancionada en los términos del artículo 292 del Código Penal.","B":"se sanciona únicamente con multa administrativa.","C":"solo genera una amonestación escrita.","D":"no tiene consecuencias si el informe no era reservado."},"correcta":"A","explicacion":"El artículo 29 dispone que todo acto de ocultamiento, destrucción o alteración deliberada de información pública, una vez solicitada, será sancionado conforme al artículo 292 del Código Penal, además de las consecuencias disciplinarias.","dificultad":2},{"id":"tra-0014","eje":"transparencia","nucleo":"general","origen":"estilo","fuente":"Ley 1712 de 2014, art. 9","enunciado":"Es información mínima que todo sujeto obligado debe publicar de manera proactiva respecto de su estructura","opciones":{"A":"las actas de las reuniones de defensa nacional.","B":"las estrategias de defensa judicial en procesos en curso.","C":"la descripción de su estructura orgánica, funciones, deberes y la ubicación de sus sedes y horarios de atención.","D":"las hojas de vida completas con datos de salud de sus servidores."},"correcta":"C","explicacion":"El artículo 9 obliga a publicar la estructura orgánica, funciones y deberes, sedes y horarios, entre otros. Los datos de salud son información clasificada y las estrategias de defensa judicial o de defensa nacional pueden ser reservadas.","dificultad":1},{"id":"tra-0015","eje":"transparencia","nucleo":"general","origen":"estilo","fuente":"Ley 1712 de 2014, art. 3","enunciado":"El principio de la Ley 1712 de 2014 según el cual la información debe publicarse de manera rutinaria y proactiva, sin esperar una solicitud, es el de","opciones":{"A":"celeridad.","B":"gratuidad.","C":"no discriminación.","D":"divulgación proactiva de la información."},"correcta":"D","explicacion":"El artículo 3 consagra, entre otros, el principio de divulgación proactiva, que obliga a publicar información de interés público sin que medie solicitud. La gratuidad se refiere al costo y la no discriminación al trato igual a los solicitantes.","dificultad":1},{"id":"tra-0016","eje":"transparencia","nucleo":"general","origen":"estilo","fuente":"Ley 1474 de 2011, art. 3","enunciado":"Un exsecretario de Hacienda departamental, dos meses después de retirarse, quiere asesorar a una empresa privada en un asunto tributario que él mismo conoció en el cargo. Según el Estatuto Anticorrupción","opciones":{"A":"puede hacerlo si informa a la entidad.","B":"le está prohibido, porque los exservidores no pueden gestionar intereses privados en asuntos relacionados con sus funciones durante los dos años siguientes al retiro.","C":"solo está prohibido si la empresa es contratista de la entidad.","D":"puede hacerlo libremente, porque ya no es servidor público."},"correcta":"B","explicacion":"El artículo 3 de la Ley 1474 de 2011 prohíbe a los exservidores, durante los dos años siguientes a la dejación del cargo, prestar servicios de asistencia, representación o asesoría en asuntos relacionados con las funciones propias del cargo o respecto de la entidad a la que prestaron servicios.","dificultad":2},{"id":"tra-0017","eje":"transparencia","nucleo":"general","origen":"estilo","fuente":"Ley 1474 de 2011, art. 73","enunciado":"Cada entidad del orden nacional, departamental y municipal debe elaborar anualmente una estrategia de lucha contra la corrupción y de atención al ciudadano, que incluye, entre otros,","opciones":{"A":"el plan de compras de bienes de consumo.","B":"la lista de proveedores preferidos de la entidad.","C":"el plan de vacaciones de los servidores.","D":"el mapa de riesgos de corrupción y las medidas para mitigarlos."},"correcta":"D","explicacion":"El artículo 73 de la Ley 1474 de 2011 obliga a elaborar anualmente el plan anticorrupción y de atención al ciudadano, que contempla el mapa de riesgos de corrupción, las medidas para mitigarlos, las estrategias antitrámites y los mecanismos para mejorar la atención al ciudadano.","dificultad":1},{"id":"tra-0018","eje":"transparencia","nucleo":"general","origen":"estilo","fuente":"Ley 1474 de 2011, art. 76","enunciado":"Según el Estatuto Anticorrupción, en toda entidad pública debe existir por lo menos una dependencia encargada de","opciones":{"A":"recibir, tramitar y resolver las quejas, sugerencias y reclamos de los ciudadanos relacionados con el cumplimiento de la misión de la entidad.","B":"realizar el control fiscal interno de la entidad.","C":"seleccionar al personal de carrera.","D":"adelantar los procesos penales contra servidores de la entidad."},"correcta":"A","explicacion":"El artículo 76 de la Ley 1474 de 2011 ordena que en toda entidad exista al menos una dependencia encargada de recibir, tramitar y resolver las quejas, sugerencias y reclamos de los ciudadanos. Los procesos penales son de la Fiscalía y el control fiscal, de las contralorías.","dificultad":1},{"id":"tra-0019","eje":"transparencia","nucleo":"general","origen":"estilo","fuente":"Código de Integridad del Servicio Público (DAFP, 2017); Decreto 1499 de 2017 (MIPG)","enunciado":"Son los valores del Código de Integridad del Servicio Público adoptado en el Modelo Integrado de Planeación y Gestión","opciones":{"A":"austeridad, solidaridad, libertad, eficacia y celeridad.","B":"honestidad, respeto, compromiso, diligencia y justicia.","C":"lealtad, obediencia, disciplina, eficiencia y rentabilidad.","D":"legalidad, tipicidad, antijuridicidad, culpabilidad y punibilidad."},"correcta":"B","explicacion":"El Código de Integridad del Servicio Público, adoptado por el Departamento Administrativo de la Función Pública en el marco del MIPG, contempla cinco valores: honestidad, respeto, compromiso, diligencia y justicia; cada entidad puede agregar hasta dos valores propios.","dificultad":1},{"id":"tra-0020","eje":"transparencia","nucleo":"general","origen":"estilo","fuente":"Ley 1474 de 2011, art. 9","enunciado":"En las entidades de la Rama Ejecutiva del orden territorial, el jefe de la oficina de control interno es designado por","opciones":{"A":"el concejo o la asamblea, para un período de dos años.","B":"la Contraloría territorial, por concurso.","C":"el respectivo gobernador o alcalde, para un período fijo de cuatro años.","D":"el Procurador General de la Nación."},"correcta":"C","explicacion":"El artículo 9 de la Ley 1474 de 2011 dispone que en el orden territorial el jefe de control interno es designado por el gobernador o alcalde para un período fijo de cuatro años, en la mitad del respectivo período del mandatario.","dificultad":2},{"id":"tra-0021","eje":"transparencia","nucleo":"general","origen":"estilo","fuente":"Ley 2013 de 2019, arts. 1 y 2","enunciado":"La Ley 2013 de 2019 obliga a los servidores públicos y demás sujetos señalados a","opciones":{"A":"renunciar a sus cuentas bancarias en el exterior.","B":"publicar sus historias clínicas.","C":"inscribirse en un partido político.","D":"publicar y divulgar su declaración de bienes y rentas, el registro de conflictos de interés y la declaración del impuesto sobre la renta."},"correcta":"D","explicacion":"La Ley 2013 de 2019 busca garantizar la transparencia mediante la publicación y divulgación de la declaración de bienes y rentas, el registro de conflictos de interés y la declaración del impuesto sobre la renta y complementarios de los sujetos obligados.","dificultad":2},{"id":"tra-0022","eje":"transparencia","nucleo":"general","origen":"estilo","fuente":"Ley 1712 de 2014, art. 18","enunciado":"Una alcaldía recibe la solicitud de copia de la historia laboral completa de un empleado, con sus datos de salud y de familia. Según la Ley 1712 de 2014, la entidad","opciones":{"A":"debe consultar previamente al Ministerio Público.","B":"debe entregarla completa, porque todo dato de un servidor es público.","C":"puede negar motivadamente y por escrito el acceso a la información que dañe la intimidad del servidor, con las limitaciones propias de su condición de servidor público.","D":"debe negarla toda, incluso cargo y salario."},"correcta":"C","explicacion":"El literal a del artículo 18 permite negar motivadamente el acceso a información clasificada cuando pueda dañar el derecho a la intimidad, bajo las limitaciones que impone la condición de servidor público. Datos como el cargo y la remuneración son públicos.","dificultad":2},{"id":"tra-0023","eje":"transparencia","nucleo":"general","origen":"estilo","fuente":"Ley 1712 de 2014, art. 26","enunciado":"El término para responder una solicitud de acceso a información pública es el establecido en","opciones":{"A":"el artículo 14 de la Ley 1437 de 2011, para peticiones de documentos e información.","B":"un reglamento interno que fije cada entidad.","C":"el Decreto 2591 de 1991.","D":"el Código General del Proceso para las pruebas documentales."},"correcta":"A","explicacion":"El artículo 26 de la Ley 1712 de 2014 remite a los términos del artículo 14 de la Ley 1437 de 2011, sustituido por la Ley 1755 de 2015, que fija diez días para peticiones de documentos e información.","dificultad":2},{"id":"tra-0024","eje":"transparencia","nucleo":"general","origen":"estilo","fuente":"Ley 1712 de 2014, art. 21","enunciado":"Una autoridad se niega a indicar siquiera si un documento solicitado obra en su poder. Según la Ley 1712 de 2014, ello solo es posible cuando","opciones":{"A":"el documento tenga menos de un año de producido.","B":"el daño causado al interés protegido sea mayor al interés público de obtener acceso a la información.","C":"el jefe de la entidad lo considere conveniente.","D":"el solicitante no sea residente en el municipio."},"correcta":"B","explicacion":"El inciso segundo del artículo 21 dispone que ninguna autoridad puede negarse a indicar si un documento obra en su poder o negar su divulgación, salvo que el daño al interés protegido sea mayor al interés público de acceder a la información.","dificultad":3},{"id":"tra-0025","eje":"transparencia","nucleo":"general","origen":"estilo","fuente":"Constitución Política, art. 74","enunciado":"El fundamento constitucional directo del derecho de acceso a los documentos públicos es el artículo 74 de la Constitución, que dispone que","opciones":{"A":"todas las personas tienen derecho a acceder a los documentos públicos salvo los casos que establezca la ley.","B":"el acceso requiere autorización judicial previa.","C":"los documentos públicos son reservados por diez años.","D":"solo los ciudadanos colombianos pueden acceder a documentos públicos."},"correcta":"A","explicacion":"El artículo 74 de la Constitución consagra el derecho de todas las personas a acceder a los documentos públicos, salvo los casos que establezca la ley, y declara inviolable el secreto profesional.","dificultad":1},{"id":"tra-0026","eje":"transparencia","nucleo":"general","origen":"estilo","fuente":"Ley 1712 de 2014, art. 19","enunciado":"Para que una entidad pueda negar el acceso a información pública reservada por daño a los intereses públicos, se requiere que","opciones":{"A":"el jefe de la entidad declare la reserva mediante circular interna.","B":"el acceso esté expresamente prohibido por una norma legal o constitucional y la negativa sea motivada y por escrito.","C":"el documento haya sido marcado como confidencial por quien lo elaboró.","D":"el solicitante sea un medio de comunicación."},"correcta":"B","explicacion":"El artículo 19 permite rechazar el acceso de forma motivada y por escrito solo cuando el acceso esté expresamente prohibido por una norma legal o constitucional, en materias como defensa y seguridad nacional o seguridad pública. Una circular o una marca interna no crean reserva.","dificultad":2},{"id":"tra-0027","eje":"transparencia","nucleo":"general","origen":"estilo","fuente":"Ley 1712 de 2014, art. 6, lit. j","enunciado":"Los datos primarios o sin procesar, en formatos estándar e interoperables, que se ponen a disposición de cualquier ciudadano de forma libre para su reutilización, son","opciones":{"A":"datos semiprivados.","B":"documentos de archivo.","C":"datos abiertos.","D":"información clasificada."},"correcta":"C","explicacion":"El artículo 6 de la Ley 1712 de 2014 define los datos abiertos como datos primarios o sin procesar, en formatos estándar e interoperables, que se ponen a disposición de cualquier persona de forma libre y sin restricciones para su reutilización.","dificultad":1},{"id":"tra-0028","eje":"transparencia","nucleo":"general","origen":"estilo","fuente":"Ley 1474 de 2011, art. 4","enunciado":"Un exservidor que ejerció cargos de nivel directivo en una entidad quiere celebrar un contrato con esa misma entidad un año después de su retiro. Según el Estatuto Anticorrupción","opciones":{"A":"puede contratar si la Procuraduría lo autoriza.","B":"puede contratar si participa en igualdad de condiciones.","C":"solo está inhabilitado durante seis meses.","D":"está inhabilitado, por haber ejercido cargo directivo en la entidad dentro de los dos años anteriores."},"correcta":"D","explicacion":"El artículo 4 de la Ley 1474 de 2011, que adicionó el artículo 8 de la Ley 80 de 1993, inhabilita para contratar con la entidad a quienes ejercieron cargos en el nivel directivo en ella durante los dos años siguientes a su retiro.","dificultad":2}]};
